public struct RuntimeTaskMetadata:
    Sendable
{
    public let id:
        RuntimeTaskID

    public let name:
        String

    public let workload:
        RuntimeWorkload

    public let priority:
        RuntimePriority

    public let createdAt:
        ContinuousClock.Instant

    public init(
        id:
            RuntimeTaskID = RuntimeTaskID(),

        name:
            String,

        workload:
            RuntimeWorkload,

        priority:
            RuntimePriority
    ) {

        self.id =
            id

        self.name =
            name

        self.workload =
            workload

        self.priority =
            priority

        self.createdAt =
            ContinuousClock.now
    }
}


// ============================================================
// MARK: - Runtime Task Result
// ============================================================

public enum RuntimeTaskResult:
    Sendable
{
    case completed
    case cancelled
    case failed(String)
}


// ============================================================
// MARK: - Runtime Task Record
// ============================================================

public struct RuntimeTaskRecord:
    Sendable
{
    public let metadata:
        RuntimeTaskMetadata

    public var startedAt:
        ContinuousClock.Instant?

    public var completedAt:
        ContinuousClock.Instant?

    public var result:
        RuntimeTaskResult?

    public var duration:
        Duration?

    public init(
        metadata:
            RuntimeTaskMetadata
    ) {

        self.metadata =
            metadata

        self.startedAt =
            nil

        self.completedAt =
            nil

        self.result =
            nil

        self.duration =
            nil
    }
}


// ============================================================
// MARK: - Runtime Statistics
// ============================================================

public struct RuntimeStatistics:
    Sendable
{
    public private(set) var
        submitted:
            UInt64 = 0

    public private(set) var
        completed:
            UInt64 = 0

    public private(set) var
        cancelled:
            UInt64 = 0

    public private(set) var
        failed:
            UInt64 = 0

    public private(set) var
        active:
            UInt64 = 0

    public private(set) var
        totalRuntime:
            Duration = .zero

    public private(set) var
        maximumLatency:
            Duration = .zero

    public mutating func submittedTask() {

        submitted &+= 1
        active &+= 1
    }

    public mutating func completedTask(
        duration:
            Duration
    ) {

        completed &+= 1

        if active > 0 {
            active -= 1
        }

        totalRuntime +=
            duration

        if duration >
            maximumLatency
        {

            maximumLatency =
                duration
        }
    }

    public mutating func cancelledTask() {

        cancelled &+= 1

        if active > 0 {
            active -= 1
        }
    }

    public mutating func failedTask() {

        failed &+= 1

        if active > 0 {
            active -= 1
        }
    }
}


// ============================================================
// MARK: - Runtime Error
// ============================================================

public enum HighPerformanceRuntimeError:
    Error,
    Sendable
{
    case shuttingDown
    case concurrencyLimitReached
    case taskNotFound
}


// ============================================================
// MARK: - Bounded Concurrency Gate
// ============================================================

public actor ConcurrencyGate {

    private let maximum:
        Int

    private var active:
        Int = 0

    private var waiters:
        [CheckedContinuation<Void, Never>] =
            []

    public init(
        maximum:
            Int
    ) {

        self.maximum =
            max(
                1,
                maximum
            )
    }

    public func acquire()
        async
    {

        if active <
            maximum
        {

            active += 1
            return
        }

        await withCheckedContinuation {
            continuation in

            waiters.append(
                continuation
            )
        }

        active += 1
    }

    public func release() {

        if let continuation =
            waiters.first
        {

            waiters.removeFirst()

            continuation.resume()

        } else {

            if active > 0 {
                active -= 1
            }
        }
    }

    public func activeCount()
        -> Int
    {

        active
    }

    public func capacity()
        -> Int
    {

        maximum
    }
}


// ============================================================
// MARK: - Runtime Scheduler
// ============================================================

public actor HighPerformanceScheduler {

    private let gate:
        ConcurrencyGate

    private var tasks:
        [RuntimeTaskID:
            Task<Void, Never>] =
            [:]

    private var records:
        [RuntimeTaskID:
            RuntimeTaskRecord] =
            [:]

    private var statistics =
        RuntimeStatistics()

    private var acceptingWork:
        Bool = true

    public init(
        maximumConcurrentTasks:
            Int = 4
    ) {

        gate =
            ConcurrencyGate(
                maximum:
                    maximumConcurrentTasks
            )
    }

    // ========================================================
    // MARK: Submit
    // ========================================================

    public func submit(
        metadata:
            RuntimeTaskMetadata,

        operation:
            @escaping @Sendable () async throws -> Void
    ) throws
        -> RuntimeTaskID
    {

        guard
            acceptingWork
        else {

            throw
                HighPerformanceRuntimeError
                    .shuttingDown
        }

        let id =
            metadata.id

        records[id] =
            RuntimeTaskRecord(
                metadata:
                    metadata
            )

        statistics
            .submittedTask()

        let priority =
            metadata.priority
                .taskPriority

        let task =
            Task(
                priority:
                    priority
            ) { [weak self] in

                await self?
                    .execute(
                        id:
                            id,

                        operation:
                            operation
                    )
            }

        tasks[id] =
            task

        return id
    }

    // ========================================================
    // MARK: Execute
    // ========================================================

    private func execute(
        id:
            RuntimeTaskID,

        operation:
            @escaping @Sendable () async throws -> Void
    ) async {

        await gate.acquire()

        defer {

            Task {
                await gate.release()
            }
        }

        guard
            var record =
                records[id]
        else {
            return
        }

        let start =
            ContinuousClock.now

        record.startedAt =
            start

        records[id] =
            record

        do {

            try await operation()

            let end =
                ContinuousClock.now

            let duration =
                end -
                start

            await finish(
                id:
                    id,

                result:
                    .completed,

                duration:
                    duration
            )

        } catch is CancellationError {

            await finish(
                id:
                    id,

                result:
                    .cancelled,

                duration:
                    ContinuousClock.now -
                    start
            )

        } catch {

            await finish(
                id:
                    id,

                result:
                    .failed(
                        String(
                            describing:
                                error
                        )
                    ),

                duration:
                    ContinuousClock.now -
                    start
            )
        }
    }

    // ========================================================
    // MARK: Finish
    // ========================================================

    private func finish(
        id:
            RuntimeTaskID,

        result:
            RuntimeTaskResult,

        duration:
            Duration
    ) {

        guard
            var record =
                records[id]
        else {
            return
        }

        record.completedAt =
            ContinuousClock.now

        record.result =
            result

        record.duration =
            duration

        records[id] =
            record

        switch result {

        case .completed:

            statistics
                .completedTask(
                    duration:
                        duration
                )

        case .cancelled:

            statistics
                .cancelledTask()

        case .failed:

            statistics
                .failedTask()
        }

        tasks[id] =
            nil
    }

    // ========================================================
    // MARK: Cancel
    // ========================================================

    public func cancel(
        _ id:
            RuntimeTaskID
    ) {

        tasks[id]?.cancel()
    }

    // ========================================================
    // MARK: Cancel All
    // ========================================================

    public func cancelAll() {

        for task
            in tasks.values
        {

            task.cancel()
        }

        tasks.removeAll()
    }

    // ========================================================
    // MARK: Shutdown
    // ========================================================

    public func shutdown() {

        acceptingWork =
            false

        cancelAll()
    }

    // ========================================================
    // MARK: Records
    // ========================================================

    public func taskRecord(
        _ id:
            RuntimeTaskID
    )
        -> RuntimeTaskRecord?
    {

        records[id]
    }

    public func activeTaskCount()
        -> Int
    {

        Int(
            statistics.active
        )
    }

    public func statisticsSnapshot()
        -> RuntimeStatistics
    {

        statistics
    }
}


// ============================================================
// MARK: - Runtime Clock
// ============================================================

public struct RuntimeClock:
    Sendable
{

    private let clock:
        ContinuousClock

    public init() {

        clock =
            ContinuousClock()
    }

    public func measure<T:
        Sendable>(
        _ operation:
            () async throws -> T
    ) async throws
        -> (
            result:
                T,

            duration:
                Duration
        )
    {

        let start =
            clock.now

        let result =
            try await operation()

        let end =
            clock.now

        return (
            result,
            end -
            start
        )
    }
}


// ============================================================
// MARK: - Backpressure Controller
// ============================================================

public actor RuntimeBackpressureController {

    private var load:
        Double = 0

    private let warningThreshold:
        Double

    private let criticalThreshold:
        Double

    public init(
        warningThreshold:
            Double = 0.70,

        criticalThreshold:
            Double = 0.90
    ) {

        self.warningThreshold =
            warningThreshold

        self.criticalThreshold =
            criticalThreshold
    }

    public func update(
        active:
            Int,

        capacity:
            Int
    ) {

        guard
            capacity > 0
        else {

            load =
                1

            return
        }

        load =
            Double(active) /
            Double(capacity)
    }

    public func shouldThrottle()
        -> Bool
    {

        load >=
            warningThreshold
    }

    public func shouldRejectBackgroundWork()
        -> Bool
    {

        load >=
            criticalThreshold
    }

    public func currentLoad()
        -> Double
    {

        load
    }
}


