    ) {

        logger.debug(
            "\(message, privacy: .public)"
        )
    }
}


// ============================================================
// MARK: - Runtime Health
// ============================================================

public enum PerformanceHealth:
    String,
    Sendable
{
    case excellent
    case healthy
    case constrained
    case overloaded
}


// ============================================================
// MARK: - Performance Evaluator
// ============================================================

public actor PerformanceHealthEvaluator {

    private var lastLoad:
        Double = 0

    public func evaluate(
        load:
            Double
    ) -> PerformanceHealth {

        lastLoad =
            load

        switch load {

        case ..<0.50:
            return .excellent

        case ..<0.75:
            return .healthy

        case ..<0.90:
            return .constrained

        default:
            return .overloaded
        }
    }

    public func currentLoad()
        -> Double
    {

        lastLoad
    }
}


// ============================================================
// MARK: - Master Performance Runtime
// ============================================================

public actor HighPerformanceRuntime {

    public static let shared =
        HighPerformanceRuntime()

    private let scheduler:
        HighPerformanceScheduler

    private let backpressure:
        RuntimeBackpressureController

    private let healthEvaluator:
        PerformanceHealthEvaluator

    private let logger:
        RuntimeLogger

    private var started:
        Bool = false

    private init() {

        scheduler =
            HighPerformanceScheduler(
                maximumConcurrentTasks:
                    4
            )

        backpressure =
            RuntimeBackpressureController()

        healthEvaluator =
            PerformanceHealthEvaluator()

        logger =
            RuntimeLogger(
                subsystem:
                    "EliteiPhoneRuntime",

                category:
                    "Performance"
            )
    }

    // ========================================================
    // MARK: Start
    // ========================================================

    public func start() {

        guard
            !started
        else {
            return
        }

        started =
            true

        logger.info(
            "High-performance runtime started"
        )
    }

    // ========================================================
    // MARK: Stop
    // ========================================================

    public func stop() async {

        guard
            started
        else {
            return
        }

        started =
            false

        await scheduler.shutdown()

        logger.info(
            "High-performance runtime stopped"
        )
    }

    // ========================================================
    // MARK: Submit
    // ========================================================

    @discardableResult
    public func submit(
        name:
            String,

        workload:
            RuntimeWorkload,

        priority:
            RuntimePriority = .normal,

        operation:
            @escaping @Sendable () async throws -> Void
    ) async throws
        -> RuntimeTaskID
    {

        guard
            started
        else {

            throw
                HighPerformanceRuntimeError
                    .shuttingDown
        }

        let active =
            await scheduler
                .activeTaskCount()

        let capacity =
            await scheduler
                .capacity()

        await backpressure.update(
            active:
                active,

            capacity:
                capacity
        )

        if priority ==
            .background &&
            await backpressure
                .shouldRejectBackgroundWork()
        {

            logger.warning(
                "Background task deferred: \(name)"
            )

            throw
                HighPerformanceRuntimeError
                    .concurrencyLimitReached
        }

        let metadata =
            RuntimeTaskMetadata(

                name:
                    name,

                workload:
                    workload,

                priority:
                    priority
            )

        logger.debug(
            "Submitting task: \(name)"
        )

        return try await scheduler.submit(
            metadata:
                metadata,

            operation:
                operation
        )
    }

    // ========================================================
    // MARK: Cancel
    // ========================================================

    public func cancel(
        _ id:
            RuntimeTaskID
    ) async {

        await scheduler.cancel(
            id
        )
    }

    // ========================================================
    // MARK: Statistics
    // ========================================================

    public func statistics()
        async -> RuntimeStatistics
    {

        await scheduler
            .statisticsSnapshot()
    }

    // ========================================================
    // MARK: Health
    // ========================================================

    public func health()
        async -> PerformanceHealth
    {

        let active =
            await scheduler
                .activeTaskCount()

        let capacity =
            await scheduler
                .capacity()

        let load =
            capacity > 0
            ? Double(active) /
                Double(capacity)
            : 1

        return await healthEvaluator
            .evaluate(
                load:
                    load
            )
    }
}


// ============================================================
// MARK: - Workload Executor
// ============================================================

public struct RuntimeWorkloadExecutor:
    Sendable
{

    private let runtime:
        HighPerformanceRuntime

    public init(
        runtime:
            HighPerformanceRuntime =
                .shared
    ) {

        self.runtime =
            runtime
    }

    @discardableResult
    public func execute(
        name:
            String,

        workload:
            RuntimeWorkload,

        priority:
            RuntimePriority = .normal,

        operation:
            @escaping @Sendable () async throws -> Void
    ) async throws
        -> RuntimeTaskID
    {

        try await runtime.submit(

            name:
                name,

            workload:
                workload,

            priority:
                priority,

            operation:
                operation
        )
    }
}


