// ============================================================
// MARK: - Runtime Performance Snapshot
// ============================================================

public struct RuntimePerformanceSnapshot:
    Sendable
{
    public let health:
        PerformanceHealth

    public let activeTasks:
        Int

    public let submitted:
        UInt64

    public let completed:
        UInt64

    public let cancelled:
        UInt64

    public let failed:
        UInt64

    public let maximumLatency:
        Duration

    public init(
        health:
            PerformanceHealth,

        statistics:
            RuntimeStatistics
    ) {

        self.health =
            health

        self.activeTasks =
            Int(
                statistics.active
            )

        self.submitted =
            statistics.submitted

        self.completed =
            statistics.completed

        self.cancelled =
            statistics.cancelled

        self.failed =
            statistics.failed

        self.maximumLatency =
            statistics.maximumLatency
    }
}


// ============================================================
// MARK: - Runtime Monitor
// ============================================================

@MainActor
public final class RuntimePerformanceMonitor:
    ObservableObject
{

    @Published
    public private(set) var
        health:
            PerformanceHealth =
                .healthy

    @Published
    public private(set) var
        activeTasks:
            Int = 0

    @Published
    public private(set) var
        completedTasks:
            UInt64 = 0

    @Published
    public private(set) var
        failedTasks:
            UInt64 = 0

    private var task:
        Task<Void, Never>?

    public init() {
    }

    public func start() {

        task?.cancel()

        task =
            Task {

                while
                    !Task.isCancelled
                {

                    let runtime =
                        HighPerformanceRuntime
                            .shared

                    let health =
                        await runtime
                            .health()

                    let statistics =
                        await runtime
                            .statistics()

                    await MainActor.run {

                        self.health =
                            health

                        self.activeTasks =
                            Int(
                                statistics.active
                            )

                        self.completedTasks =
                            statistics.completed

                        self.failedTasks =
                            statistics.failed
                    }

                    try? await Task.sleep(
                        for:
                            .seconds(2)
                    )
                }
            }
    }

    public func stop() {

        task?.cancel()

        task =
            nil
    }
}


