// ============================================================
// MARK: - Application Bootstrap
// ============================================================

@MainActor
public final class EliteiPhoneRuntime {

    public static let shared =
        EliteiPhoneRuntime()

    public let monitor:
        RuntimePerformanceMonitor

    private init() {

        monitor =
            RuntimePerformanceMonitor()
    }

    public func launch() {

        Task {

            await HighPerformanceRuntime
                .shared
                .start()

            await MainActor.run {

                self.monitor.start()
            }
        }
    }

    public func shutdown() {

        monitor.stop()

        Task {

            await HighPerformanceRuntime
                .shared
                .stop()
        }
    }
}


