public struct PowerRuntimeEnvironment:
    Sendable
{
    public let powerState:
        RuntimePowerState

    public let thermalState:
        RuntimeThermalState

    public let batteryLevel:
        Float

    public let lowPowerMode:
        Bool

    public init(
        powerState:
            RuntimePowerState,

        thermalState:
            RuntimeThermalState,

        batteryLevel:
            Float,

        lowPowerMode:
            Bool
    ) {

        self.powerState =
            powerState

        self.thermalState =
