}


// ============================================================
// MARK: - Runtime Decision
// ============================================================

public enum PowerWorkloadDecision:
    Sendable
{
    case run
    case throttle
    case defer
    case reject
}


// ============================================================
// MARK: - Decision
// ============================================================

public struct PowerDecision:
    Sendable
{
    public let workload:
        PowerWorkload

    public let decision:
        PowerWorkloadDecision

    public let policy:
        PowerWorkloadPolicy

    public let reason:
        String
}


// ============================================================
// MARK: - Power Governor
// ============================================================

public actor PowerGovernor {

    private var environment:
        PowerRuntimeEnvironment

    private var profile:
        PowerGovernorProfile

    private var manualOverride:
        PowerGovernorMode?

    public init() {

        self.environment =
            PowerRuntimeEnvironment(

                powerState:
                    .normal,

                thermalState:
                    .nominal,

                batteryLevel:
                    1.0,

                lowPowerMode:
                    false
            )

        self.profile =
            PowerGovernorProfiles
                .balanced
    }

    // ========================================================
    // MARK: Environment
    // ========================================================

    public func updateEnvironment(
        _ environment:
            PowerRuntimeEnvironment
    ) {

        self.environment =
            environment

        recalculateProfile()
    }

    // ========================================================
    // MARK: Override
    // ========================================================

    public func setOverride(
        _ mode:
            PowerGovernorMode?
    ) {

        manualOverride =
            mode

        recalculateProfile()
    }

    // ========================================================
    // MARK: Automatic Profile
    // ========================================================

    private func recalculateProfile() {

        if let manualOverride {

            profile =
                profileFor(
                    manualOverride
                )

            return
        }

        switch environment.thermalState {

        case .critical:

            profile =
                PowerGovernorProfiles
                    .emergency

        case .serious:

            profile =
                PowerGovernorProfiles
                    .efficiency

        case .fair:

            if environment.lowPowerMode {

                profile =
                    PowerGovernorProfiles
                        .efficiency

            } else {

                profile =
                    PowerGovernorProfiles
                        .balanced
            }

        case .nominal:

            if environment.lowPowerMode {

                profile =
                    PowerGovernorProfiles
                        .efficiency

            } else if environment.batteryLevel < 0.15 {

                profile =
                    PowerGovernorProfiles
                        .efficiency

            } else {

                profile =
                    PowerGovernorProfiles
                        .balanced
            }
        }
    }

    private func profileFor(
        _ mode:
            PowerGovernorMode
    )
        -> PowerGovernorProfile
    {

        switch mode {

        case .maximumPerformance:
            return PowerGovernorProfiles
                .maximumPerformance

        case .performance:
            return PowerGovernorProfiles
                .performance

        case .balanced:
            return PowerGovernorProfiles
                .balanced

        case .efficiency:
            return PowerGovernorProfiles
                .efficiency

        case .emergency:
            return PowerGovernorProfiles
                .emergency
        }
    }

    // ========================================================
    // MARK: Decision
    // ========================================================

    public func decision(
        for workload:
            PowerWorkload
    )
        -> PowerDecision
    {

        let policy =
            profile.policy(
                for:
                    workload
            )

        if !policy.allowed {

            return PowerDecision(

                workload:
                    workload,

                decision:
                    .reject,

                policy:
                    policy,

                reason:
                    "Workload disabled by power policy"
            )
        }

        if environment.thermalState ==
            .critical
        {

            switch workload {

            case .userInterface,
                 .networking:

                return PowerDecision(

                    workload:
                        workload,

                    decision:
                        .run,

                    policy:
                        policy,

                    reason:
                        "Critical thermal state; essential work retained"
                )

            default:

                return PowerDecision(

                    workload:
                        workload,

                    decision:
                        .defer,

                    policy:
                        policy,

                    reason:
                        "Critical thermal state"
                )
            }
        }

        if environment.lowPowerMode &&
            policy.deferWhenLowPower
        {

            return PowerDecision(

                workload:
                    workload,

                decision:
                    .throttle,

                policy:
                    policy,

                reason:
                    "Low Power Mode enabled"
            )
        }

        if (
            environment.thermalState ==
                .serious ||
            environment.thermalState ==
                .fair
        ) &&
        policy.deferWhenThermallyConstrained
        {

            return PowerDecision(

                workload:
                    workload,

                decision:
                    .throttle,

                policy:
                    policy,

                reason:
                    "Thermal state requires workload reduction"
            )
        }

        return PowerDecision(

            workload:
                workload,

            decision:
                .run,

            policy:
                policy,

            reason:
                "Workload permitted"
        )
    }

    // ========================================================
    // MARK: Current Profile
    // ========================================================

    public func currentProfile()
        -> PowerGovernorProfile
    {

        profile
    }

    public func currentEnvironment()
        -> PowerRuntimeEnvironment
    {

        environment
    }
}


// ============================================================
// MARK: - Adaptive Interval
// ============================================================

public struct AdaptiveWorkInterval:
    Sendable
{
    public let frequencyHz:
        Double

    public var interval:
        Duration
    {

        guard frequencyHz > 0 else {
            return .seconds(60)
        }

        let seconds =
            1.0 /
            frequencyHz

        return .milliseconds(
            Int(
                max(
                    1,
                    seconds * 1000
                )
            )
        )
    }
}


// ============================================================
// MARK: - Adaptive Scheduler
// ============================================================

public actor AdaptivePowerScheduler {

    private let governor:
        PowerGovernor

    public init(
        governor:
            PowerGovernor
    ) {

        self.governor =
            governor
    }

    public func interval(
        for workload:
            PowerWorkload
    )
        async -> AdaptiveWorkInterval
    {

        let profile =
            await governor
                .currentProfile()

        let policy =
            profile.policy(
                for:
                    workload
            )

        return AdaptiveWorkInterval(
            frequencyHz:
                policy.targetFrequencyHz
        )
    }

    public func decision(
        for workload:
            PowerWorkload
    )
        async -> PowerDecision
    {

        await governor.decision(
            for:
                workload
        )
    }
}


