// ============================================================
// MARK: - Runtime Governor Service
// ============================================================

public actor BatteryThermalRuntime {

    public static let shared =
        BatteryThermalRuntime()

    public let governor:
        PowerGovernor

    public let scheduler:
        AdaptivePowerScheduler

    private let thermalObserver:
        ThermalObserver

    private var monitorTask:
        Task<Void, Never>?

    private var running:
        Bool = false

    private init() {

        let governor =
            PowerGovernor()

        self.governor =
            governor

        self.scheduler =
            AdaptivePowerScheduler(
                governor:
                    governor
            )

        self.thermalObserver =
            ThermalObserver()
    }

    // ========================================================
    // MARK: Start
    // ========================================================

    public func start() {

        guard !running else {
            return
        }

        running =
            true

        monitorTask =
            Task { [weak self] in

                while
                    !Task.isCancelled
                {

                    await self?
                        .refreshEnvironment()

                    try? await Task.sleep(
                        for:
                            .seconds(2)
                    )
                }
            }
    }

    // ========================================================
    // MARK: Stop
    // ========================================================

    public func stop() {

        running =
            false

        monitorTask?.cancel()

        monitorTask =
            nil
    }

    // ========================================================
    // MARK: Refresh
    // ========================================================

    private func refreshEnvironment() async {

        let thermal =
            thermalObserver
                .currentState()

        let lowPower =
            ProcessInfo
                .processInfo
                .isLowPowerModeEnabled

        let battery =
            await MainActor.run {

                UIDevice.current
                    .batteryLevel
            }

        let powerState:
            RuntimePowerState =
                lowPower
                ? .lowPower
                : .normal

        let environment =
            PowerRuntimeEnvironment(

                powerState:
                    powerState,

                thermalState:
                    thermal,

                batteryLevel:
                    battery,

                lowPowerMode:
                    lowPower
            )

        await governor
            .updateEnvironment(
                environment
            )
    }

    // ========================================================
    // MARK: Decision
    // ========================================================

    public func decision(
        for workload:
            PowerWorkload
    )
        async -> PowerDecision
    {

        await governor
            .decision(
                for:
                    workload
            )
    }
}


// ============================================================
// MARK: - Governor Workload Gate
// ============================================================

public struct PowerAwareWorkloadGate:
    Sendable
{

    private let runtime:
        BatteryThermalRuntime

    public init(
        runtime:
            BatteryThermalRuntime =
                .shared
    ) {

        self.runtime =
            runtime
    }

    public func shouldRun(
        _ workload:
            PowerWorkload
    )
        async -> Bool
    {

        let decision =
            await runtime
                .decision(
                    for:
                        workload
                )

        switch decision.decision {

        case .run,
             .throttle:

            return true

        case .defer,
             .reject:

            return false
        }
    }
}


// ============================================================
// MARK: - Power-Aware Loop
// ============================================================

public struct PowerAwareLoop:
    Sendable
{

    private let scheduler:
        AdaptivePowerScheduler

    public init(
        scheduler:
            AdaptivePowerScheduler
    ) {

        self.scheduler =
            scheduler
    }

    public func run(
        workload:
            PowerWorkload,

        operation:
            @escaping @Sendable () async -> Void
    ) async {

        while
            !Task.isCancelled
        {

            let decision =
                await scheduler
                    .decision(
                        for:
                            workload
                    )

            switch decision.decision {

            case .run,
                 .throttle:

                await operation()

            case .defer:

                break

            case .reject:

                return
            }

            let interval =
                await scheduler
                    .interval(
                        for:
                            workload
                    )

            try? await Task.sleep(
                for:
                    interval.interval
            )
        }
    }
}


// ============================================================
// MARK: - Performance Runtime Integration
// ============================================================

public actor PerformancePowerBridge {

    private let powerRuntime:
        BatteryThermalRuntime

    public init(
        powerRuntime:
            BatteryThermalRuntime =
                .shared
    ) {

        self.powerRuntime =
            powerRuntime
    }

    public func allow(
        workload:
            PowerWorkload
    )
        async -> Bool
    {

        let decision =
            await powerRuntime
                .decision(
                    for:
                        workload
                )

        switch decision.decision {

        case .run,
             .throttle:

            return true

        case .defer,
             .reject:

            return false
        }
    }
}


// ============================================================
// MARK: - Memory Runtime Integration
// ============================================================

public actor MemoryPowerBridge {

    private let powerRuntime:
        BatteryThermalRuntime

    public init(
        powerRuntime:
            BatteryThermalRuntime =
                .shared
    ) {

        self.powerRuntime =
            powerRuntime
    }

    public func recommendedCacheMultiplier()
        async -> Double
    {

        let environment =
            await powerRuntime.governor
                .currentEnvironment()

        switch environment.thermalState {

        case .nominal:

            if environment.lowPowerMode {
                return 0.60
            }

            return 1.0

        case .fair:

            return 0.70

        case .serious:

            return 0.40

        case .critical:

            return 0.10
        }
    }
}


