// ============================================================

public actor PowerRuntimeSnapshotProvider {

    public init() {
    }

    public func snapshot()
        async -> PowerRuntimeSnapshot
    {

        let runtime =
            BatteryThermalRuntime.shared

        let governor =
            runtime.governor

        let profile =
            await governor
                .currentProfile()

        let environment =
            await governor
                .currentEnvironment()

        return PowerRuntimeSnapshot(

            mode:
                profile.mode,

            powerState:
                environment.powerState,

            thermalState:
                environment.thermalState,

            batteryLevel:
                environment.batteryLevel,

            lowPowerMode:
                environment.lowPowerMode
        )
    }
}


// ============================================================
// MARK: - Power Dashboard
// ============================================================

@MainActor
public final class PowerRuntimeMonitor:
    ObservableObject
{

    @Published
    public private(set) var
        snapshot:
            PowerRuntimeSnapshot?

    private var task:
        Task<Void, Never>?

    public init() {
    }

    public func start() {

        task?.cancel()

        task =
            Task {

                let provider =
                    PowerRuntimeSnapshotProvider()

                while
                    !Task.isCancelled
                {

                    let snapshot =
                        await provider
                            .snapshot()

                    self.snapshot =
                        snapshot

                    try? await Task.sleep(
                        for:
                            .seconds(2)
                    )
                }
            }
    }

    public func stop() {

        task?.cancel()

        task =
            nil
    }
}


