public struct PowerRuntimeView:
    View
{

    @StateObject
    private var monitor:
        PowerRuntimeMonitor

    public init(
        monitor:
            PowerRuntimeMonitor
    ) {

        _monitor =
            StateObject(
                wrappedValue:
                    monitor
            )
    }

    public var body: some View {

        VStack(
            alignment:
                .leading,

            spacing:
                8
        ) {

            Text(
                "POWER / THERMAL"
            )
            .font(
                .headline
            )

            if let snapshot =
                monitor.snapshot
            {

                statusRow(
                    "MODE",
                    snapshot.mode.rawValue
                )

                statusRow(
                    "THERMAL",
                    snapshot.thermalState.rawValue
                )

                statusRow(
                    "POWER",
                    snapshot.powerState.rawValue
                )

                statusRow(
                    "BATTERY",
                    "\(Int(snapshot.batteryLevel * 100))%"
                )

                statusRow(
                    "LOW POWER",
                    snapshot.lowPowerMode
                        ? "ON"
                        : "OFF"
                )
            }
        }
        .padding()
    }

    private func statusRow(
        _ title:
            String,

        _ value:
            String
    )
        -> some View
    {

        HStack {

            Text(
                title
            )

            Spacer()

            Text(
                value.uppercased()
            )
            .font(
                .system(
                    size:
                        11,

                    design:
                        .monospaced
                )
            )
        }
    }
}


