// ============================================================
// MARK: - Connectivity Monitor
// ============================================================

public actor NetworkConnectivityMonitor {

    private let monitor:
        NWPathMonitor

    private let queue:
        DispatchQueue

    private var state:
        NetworkState

    private var started:
        Bool = false

    public init() {

        monitor =
            NWPathMonitor()

        queue =
            DispatchQueue(
                label:
                    "EliteiPhone.NetworkMonitor",
                qos:
                    .utility
            )

        state =
            NetworkState(
                available:
                    false,

                interface:
                    .unavailable,

                quality:
                    .unavailable,

                expensive:
                    false,

                constrained:
                    false
            )
    }

    public func start() {

        guard !started else {
            return
        }

        started =
            true

        monitor.pathUpdateHandler =
            { [weak self] path in

                Task {

                    await self?
                        .update(
                            from:
                                path
                        )
                }
            }

        monitor.start(
            queue:
                queue
        )
    }

    public func stop() {

        guard started else {
            return
        }

        monitor.cancel()

        started =
            false
    }

    private func update(
        from path:
            NWPath
    ) {

        let interface =
            determineInterface(
                path
            )

        let quality =
            determineQuality(
                path
            )

        state =
            NetworkState(

                available:
                    path.status ==
                        .satisfied,

                interface:
                    interface,

                quality:
                    quality,

                expensive:
                    path.isExpensive,

                constrained:
                    path.isConstrained
            )
    }

    private func determineInterface(
        _ path:
            NWPath
    )
        -> NetworkInterface
    {

        if path.usesInterfaceType(
            .wifi
        ) {

            return .wifi
        }

        if path.usesInterfaceType(
            .cellular
        ) {

            return .cellular
        }

        if path.usesInterfaceType(
            .wiredEthernet
        ) {

            return .wired
        }

        if path.usesInterfaceType(
            .loopback
        ) {

            return .loopback
        }

        if path.status !=
            .satisfied
        {

            return .unavailable
        }

        return .other
    }

    private func determineQuality(
        _ path:
            NWPath
    )
        -> NetworkQuality
    {

        guard
            path.status ==
                .satisfied
        else {
            return .unavailable
        }

        if path.isConstrained {
            return .constrained
        }

        if path.isExpensive {
            return .fair
        }

        if path.usesInterfaceType(
            .wifi
        ) {

            return .excellent
        }

        if path.usesInterfaceType(
            .wiredEthernet
        ) {

            return .excellent
        }

        if path.usesInterfaceType(
            .cellular
        ) {

            return .good
        }

        return .fair
    }

    public func currentState()
        -> NetworkState
    {

        state
    }
}


// ============================================================
// MARK: - Retry Policy
// ============================================================

public struct NetworkRetryPolicy:
    Sendable
{
    public let maximumAttempts:
        Int

    public let initialDelay:
        Duration

    public let maximumDelay:
        Duration

    public init(
        maximumAttempts:
            Int = 4,

        initialDelay:
            Duration = .seconds(1),

        maximumDelay:
            Duration = .seconds(30)
    ) {

        self.maximumAttempts =
            max(
                1,
                maximumAttempts
            )

        self.initialDelay =
            initialDelay

        self.maximumDelay =
            maximumDelay
    }

    public func delay(
        for attempt:
            Int
    )
        -> Duration
    {

        guard attempt > 0 else {
            return .zero
        }

        let exponent =
            min(
                attempt - 1,
                10
            )

        let multiplier =
            pow(
                2.0,
                Double(exponent)
            )

        let baseSeconds =
            durationSeconds(
                initialDelay
            )

        let maximumSeconds =
            durationSeconds(
                maximumDelay
            )

        let seconds =
            min(
                baseSeconds *
                    multiplier,

                maximumSeconds
            )

        return .milliseconds(
            Int(
                seconds * 1000
            )
        )
    }

    private func durationSeconds(
        _ duration:
            Duration
    )
        -> Double
    {

        let components =
            duration.components

        return Double(
            components.seconds
        ) +
        Double(
            components.attoseconds
        ) /
        1_000_000_000_000_000_000
    }
}


