// MARK: - Offline Queue Item
// ============================================================

public struct OfflineNetworkItem:
    Sendable
{
    public let id:
        UUID

    public let request:
        RuntimeNetworkRequest

    public let queuedAt:
        Date

    public init(
        id:
            UUID = UUID(),

        request:
            RuntimeNetworkRequest
    ) {

        self.id =
            id

        self.request =
            request

        self.queuedAt =
            Date()
    }
}


// ============================================================
// MARK: - Offline Queue
// ============================================================

public actor OfflineNetworkQueue {

    private var items:
        [OfflineNetworkItem] =
            []

    public init() {
    }

    public func enqueue(
        _ item:
            OfflineNetworkItem
    ) {

        items.append(
            item
        )

        sort()
    }

    public func dequeue()
        -> OfflineNetworkItem?
    {

        guard
            !items.isEmpty
        else {
            return nil
        }

        return items.removeFirst()
    }

    public func remove(
        id:
            UUID
    ) {

        items.removeAll {
            $0.id == id
        }
    }

    public func count()
        -> Int
    {

        items.count
    }

    public func snapshot()
        -> [OfflineNetworkItem]
    {

        items
    }

    private func sort() {

        items.sort {

            if $0.request.policy.priority !=
                $1.request.policy.priority
            {

                return
                    $0.request.policy.priority >
                    $1.request.policy.priority
            }

            return
                $0.queuedAt <
                $1.queuedAt
        }
    }
}


// ============================================================
// MARK: - Network Metrics
// ============================================================

public struct NetworkMetrics:
    Sendable
{
    public private(set) var
        requests:
            UInt64 = 0

    public private(set) var
        successful:
            UInt64 = 0

    public private(set) var
        failed:
            UInt64 = 0

    public private(set) var
        retries:
            UInt64 = 0

    public private(set) var
        bytesReceived:
            UInt64 = 0

    public private(set) var
        bytesSent:
            UInt64 = 0

    public private(set) var
        totalLatency:
            Duration = .zero

    public mutating func recordRequest() {
        requests &+= 1
    }

    public mutating func recordSuccess(
        bytes:
            Int,

        latency:
            Duration
    ) {

        successful &+= 1

        bytesReceived &+=
            UInt64(
                max(
                    0,
                    bytes
                )
            )

        totalLatency +=
            latency
    }

    public mutating func recordFailure() {
        failed &+= 1
    }

    public mutating func recordRetry() {
        retries &+= 1
    }
}


// ============================================================
// MARK: - URLSession Transport
// ============================================================

public actor NetworkTransport {

    private let session:
        URLSession

    private var metrics =
        NetworkMetrics()

    public init() {

        let configuration =
            URLSessionConfiguration
                .default

        configuration.waitsForConnectivity =
            false

        configuration.timeoutIntervalForRequest =
            30

        configuration.timeoutIntervalForResource =
            60

        configuration.requestCachePolicy =
            .useProtocolCachePolicy

        session =
            URLSession(
                configuration:
                    configuration
            )
    }

    public func execute(
        request:
            RuntimeNetworkRequest
    ) async throws
        -> RuntimeNetworkResponse
    {

        metrics.recordRequest()

        let start =
            ContinuousClock.now

        do {

            let (
                data,
                response
            ) =
                try await session.data(
                    for:
                        request.urlRequest
                )

            let duration =
                ContinuousClock.now -
                start

            guard
                let http =
                    response
                    as? HTTPURLResponse
            else {

                metrics.recordFailure()

                throw
                    RuntimeNetworkError
                        .invalidResponse
            }

            guard
                200..<300
                    ~= http.statusCode
            else {

                metrics.recordFailure()

                throw
                    RuntimeNetworkError
                        .httpStatus(
                            http.statusCode
                        )
            }

            metrics.recordSuccess(
                bytes:
                    data.count,

                latency:
                    duration
            )

            return RuntimeNetworkResponse(

                requestID:
                    request.id,

                data:
                    data,

                response:
                    http,

                duration:
                    duration
            )

        } catch {

            metrics.recordFailure()

            if let runtimeError =
                error
                as? RuntimeNetworkError
            {

                throw runtimeError
            }

            if
                let urlError =
                    error
                    as? URLError
            {

                switch urlError.code {

                case .timedOut:

                    throw
                        RuntimeNetworkError
                            .timeout

                case .notConnectedToInternet,
                     .networkConnectionLost:

                    throw
                        RuntimeNetworkError
                            .unavailable

                default:

                    throw
                        RuntimeNetworkError
                            .transport(
                                urlError
                                    .localizedDescription
                            )
                }
            }

            throw
                RuntimeNetworkError
                    .transport(
                        error
                            .localizedDescription
                    )
        }
    }

    public func metricsSnapshot()
        -> NetworkMetrics
    {

        metrics
    }
}


// ============================================================
// MARK: - Network Runtime
// ============================================================

public actor HighPerformanceNetworkRuntime {

    public static let shared =
        HighPerformanceNetworkRuntime()

    public let connectivity:
        NetworkConnectivityMonitor

    public let queue:
        OfflineNetworkQueue

    private let transport:
        NetworkTransport

    private let retryPolicy:
        NetworkRetryPolicy

    private let logger:
        Logger

    private var running:
        Bool = false

    private var activeTasks:
        [UUID:
            Task<
                RuntimeNetworkResponse,
                Error
            >] =
            [:]

    private init() {

        connectivity =
            NetworkConnectivityMonitor()

        queue =
            OfflineNetworkQueue()

        transport =
            NetworkTransport()

        retryPolicy =
            NetworkRetryPolicy()

        logger =
            Logger(
                subsystem:
                    "EliteiPhoneRuntime",

                category:
                    "Network"
            )
    }

    // ========================================================
    // MARK: Start
    // ========================================================

    public func start() {

        guard !running else {
            return
        }

        running =
            true

        Task {

            await connectivity.start()
        }

        logger.info(
            "Network runtime started"
        )
    }

    // ========================================================
    // MARK: Stop
    // ========================================================

    public func stop() async {

        running =
            false

        await connectivity.stop()

        cancelAll()

        logger.info(
            "Network runtime stopped"
        )
    }

    // ========================================================
    // MARK: Execute
    // ========================================================

    public func execute(
        _ request:
            RuntimeNetworkRequest
    ) async throws
        -> RuntimeNetworkResponse
    {

        guard
            running
        else {

            throw
                RuntimeNetworkError
                    .unavailable
        }

        let state =
            await connectivity
                .currentState()

        try validatePolicy(
            request:
                request,

            state:
                state
        )

        let id =
            request.id

        let task =
            Task {
                [transport,
                 retryPolicy] in

                var attempt =
                    0

                while true {

                    try Task.checkCancellation()

                    do {

                        return try await
                            transport.execute(
                                request:
                                    request
                            )

                    } catch {

                        attempt += 1

                        if attempt >=
                            retryPolicy
                                .maximumAttempts
                        {

                            throw
                                RuntimeNetworkError
                                    .retryLimitExceeded
                        }

                        guard
                            shouldRetry(
                                error:
                                    error
                            )
                        else {

                            throw error
                        }

                        let delay =
                            retryPolicy.delay(
                                for:
                                    attempt
                            )

                        try await Task.sleep(
                            for:
                                delay
                        )
                    }
                }
            }

        activeTasks[id] =
            task

        defer {
            activeTasks[id] =
                nil
        }

        return try await task.value
    }

    // ========================================================
    // MARK: Policy Validation
    // ========================================================

    private func validatePolicy(
        request:
            RuntimeNetworkRequest,

        state:
            NetworkState
    ) throws {

        guard
            state.available
        else {

            throw
                RuntimeNetworkError
                    .unavailable
        }

        if state.interface ==
            .cellular &&
            !request.policy
                .allowsCellular
        {

            throw
                RuntimeNetworkError
                    .blockedByPolicy
        }

        if state.expensive &&
            !request.policy
                .allowsExpensiveNetwork
        {

            throw
                RuntimeNetworkError
                    .blockedByPolicy
        }

        if state.constrained &&
            !request.policy
                .allowsConstrainedNetwork
        {

            throw
                RuntimeNetworkError
                    .blockedByPolicy
        }
    }

    // ========================================================
    // MARK: Retry Decision
    // ========================================================

    private func shouldRetry(
        error:
            Error
    )
        -> Bool
    {

        if error
            is CancellationError
        {
            return false
        }

        if let networkError =
            error
            as? RuntimeNetworkError
        {

            switch networkError {

            case .unavailable,
                 .timeout,
                 .transport:

                return true

            case .httpStatus(
                let code
            ):

                return
                    code == 408 ||
                    code == 425 ||
                    code == 429 ||
                    code >= 500

            default:

                return false
            }
        }

        return false
    }

    // ========================================================
    // MARK: Offline Enqueue
    // ========================================================

    public func enqueueOffline(
        _ request:
            RuntimeNetworkRequest
    ) async {

        await queue.enqueue(
            OfflineNetworkItem(
                request:
                    request
            )
        )
    }

    // ========================================================
    // MARK: Flush Offline Queue
    // ========================================================

    public func flushOfflineQueue()
        async
    {

        let state =
            await connectivity
                .currentState()

        guard
            state.available
        else {
            return
        }

        while
            let item =
                await queue.dequeue()
        {

            do {

                _ =
                    try await execute(
                        item.request
                    )

            } catch {

                await queue.enqueue(
                    item
                )

                break
            }
        }
    }

    // ========================================================
    // MARK: Cancellation
    // ========================================================

    public func cancel(
        id:
            UUID
    ) {

        activeTasks[
            id
        ]?.cancel()

        activeTasks[
            id
        ] =
            nil
    }

    public func cancelAll() {

        for task
            in activeTasks.values
        {

            task.cancel()
        }

        activeTasks.removeAll()
    }

    // ========================================================
    // MARK: State
    // ========================================================

    public func currentNetworkState()
        async -> NetworkState
    {

        await connectivity
            .currentState()
    }

    // ========================================================
    // MARK: Metrics
    // ========================================================

    public func metrics()
        async -> NetworkMetrics
    {

        await transport
            .metricsSnapshot()
    }

    public func queuedRequestCount()
        async -> Int
    {

        await queue.count()
    }
}


// ============================================================
// MARK: - Connectivity-Aware Request Builder
// ============================================================

public struct RuntimeRequestBuilder:
    Sendable
{

    public init() {
    }

    public func get(
        url:
            URL,

        priority:
            NetworkRequestPriority =
                .normal,

        allowsCellular:
            Bool = true,

        allowsExpensiveNetwork:
            Bool = true
    )
        -> RuntimeNetworkRequest
    {

        var request =
            URLRequest(
                url:
                    url
            )

        request.httpMethod =
            "GET"

        let policy =
            NetworkRequestPolicy(

                priority:
                    priority,

                allowsCellular:
                    allowsCellular,

                allowsExpensiveNetwork:
                    allowsExpensiveNetwork
            )

        return RuntimeNetworkRequest(

            urlRequest:
                request,

            policy:
                policy
        )
    }

    public func post(
        url:
            URL,

        body:
            Data,

        priority:
            NetworkRequestPriority =
                .userInitiated
    )
        -> RuntimeNetworkRequest
    {

        var request =
            URLRequest(
                url:
                    url
            )

        request.httpMethod =
            "POST"

        request.httpBody =
            body

        request.setValue(
            "application/json",
            forHTTPHeaderField:
                "Content-Type"
        )

        return RuntimeNetworkRequest(

            urlRequest:
                request,

            policy:
                NetworkRequestPolicy(

                    priority:
                        priority
                )
        )
    }
}


// ============================================================
// MARK: - Network Runtime Snapshot
// ============================================================

public struct NetworkRuntimeSnapshot:
    Sendable
{
    public let state:
        NetworkState

    public let metrics:
        NetworkMetrics

    public let queuedRequests:
        Int
}


// ============================================================
// MARK: - Snapshot Provider
// ============================================================

public actor NetworkRuntimeSnapshotProvider {

    public init() {
    }

    public func snapshot()
        async -> NetworkRuntimeSnapshot
    {

        let runtime =
            HighPerformanceNetworkRuntime
                .shared

        let state =
            await runtime
                .currentNetworkState()

        let metrics =
            await runtime
                .metrics()

        let queued =
            await runtime
                .queuedRequestCount()

        return NetworkRuntimeSnapshot(

            state:
                state,

            metrics:
                metrics,

            queuedRequests:
                queued
        )
    }
}


// ============================================================
// MARK: - Network Monitor
// ============================================================

@MainActor
public final class NetworkRuntimeMonitor:
    ObservableObject
{

    @Published
    public private(set) var
        snapshot:
            NetworkRuntimeSnapshot?

    private var task:
        Task<Void, Never>?

    public init() {
    }

    public func start() {

        task?.cancel()

        task =
            Task {

                let provider =
                    NetworkRuntimeSnapshotProvider()

                while
                    !Task.isCancelled
                {

                    let snapshot =
                        await provider
                            .snapshot()

                    self.snapshot =
                        snapshot

                    try? await Task.sleep(
                        for:
                            .seconds(2)
                    )
                }
            }
    }

    public func stop() {

        task?.cancel()

        task =
            nil
    }
}


// ============================================================
// MARK: - Network Dashboard
// ============================================================

public struct NetworkRuntimeView:
    View
{

    @StateObject
    private var monitor:
        NetworkRuntimeMonitor

    public init(
        monitor:
            NetworkRuntimeMonitor
    ) {

        _monitor =
            StateObject(
                wrappedValue:
                    monitor
            )
    }

    public var body: some View {

        VStack(
            alignment:
                .leading,

            spacing:
                8
        ) {

            Text(
                "NETWORK RUNTIME"
            )
            .font(
                .headline
            )

            if let snapshot =
                monitor.snapshot
            {

                row(
                    "STATE",
                    snapshot.state.available
                        ? "AVAILABLE"
                        : "OFFLINE"
                )

                row(
                    "INTERFACE",
                    snapshot.state
                        .interface
                        .rawValue
                )

                row(
                    "QUALITY",
                    snapshot.state
                        .quality
                        .rawValue
                )

                row(
                    "EXPENSIVE",
                    snapshot.state.expensive
                        ? "YES"
                        : "NO"
                )

                row(
                    "QUEUED",
                    "\(snapshot.queuedRequests)"
                )

                row(
                    "SUCCESS",
                    "\(snapshot.metrics.successful)"
                )

                row(
                    "FAILED",
                    "\(snapshot.metrics.failed)"
                )
            }
        }
        .padding()
    }

    private func row(
        _ title:
            String,

        _ value:
            String
    )
        -> some View
    {

        HStack {

            Text(
                title
            )

            Spacer()

            Text(
                value.uppercased()
            )
            .font(
                .system(
                    size:
                        10,

                    design:
                        .monospaced
                )
            )
        }
    }
}


// ============================================================
// MARK: - Application Network Runtime
// ============================================================

@MainActor
public final class EliteiPhoneNetworkRuntime {

    public static let shared =
        EliteiPhoneNetworkRuntime()

    public let monitor:
        NetworkRuntimeMonitor

    private init() {

        monitor =
            NetworkRuntimeMonitor()
    }

    public func start() {

        Task {

            await HighPerformanceNetworkRuntime
                .shared
                .start()

            monitor.start()
        }
    }

    public func stop() {

        monitor.stop()

        Task {

            await HighPerformanceNetworkRuntime
                .shared
                .stop()
        }
    }
}
```

### The resulting networking architecture

```text
                         #4 NETWORK RUNTIME
                                │
             ┌──────────────────┼──────────────────┐
             │                  │                  │
             ▼                  ▼                  ▼
       PATH MONITOR         REQUEST ENGINE     OFFLINE QUEUE
             │                  │                  │
       Wi-Fi / 5G          PRIORITY              RETRY
       Cellular             POLICY              BACKOFF
       Ethernet             TIMEOUT              RESUME
             │                  │                  │
             └──────────────────┼──────────────────┘
                                ▼
                           URLSession
                                │
                                ▼
                         Internet / APIs
```

### The major improvement

The app no longer needs every subsystem to independently figure out whether it should use the network.

For example:

```swift
let request =
    RuntimeRequestBuilder()
        .get(
            url: serverURL,
            priority: .userInitiated,
            allowsCellular: true,
            allowsExpensiveNetwork: false
        )

let response =
    try await HighPerformanceNetworkRuntime
        .shared
        .execute(request)
```

The networking layer can then reject or defer the request when the current connection violates its policy.

### Offline-first behaviour

A background synchronization system can instead do:

```swift
await HighPerformanceNetworkRuntime
    .shared
    .enqueueOffline(request)
```

When connectivity returns:

```text
OFFLINE
   │
   ▼
QUEUE REQUEST
   │
   │
   ├──── Wi-Fi unavailable
   │
   └──── Cellular available
                │
                ▼
         Policy evaluation
                │
         ┌──────┴──────┐
         ▼             ▼
      WAIT            SEND
```

This becomes particularly powerful when combined with **#3**:

```text
             NETWORK REQUEST
                    │
             ┌──────▼──────┐
             │ #3 POWER    │
             │ GOVERNOR     │
             └──────┬──────┘
                    │
             ┌──────▼──────┐
             │ #4 NETWORK  │
             │ GOVERNOR    │
             └──────┬──────┘
                    │
          ┌─────────┼─────────┐
          ▼         ▼         ▼
        WIFI      CELLULAR   OFFLINE
          │         │         │
          └─────────┼─────────┘
                    ▼
                URLSession
```

So an expensive background synchronisation operation can eventually become **power-aware + connection-aware**, while an interactive request remains responsive.

One production refinement I'd make before calling this subsystem finished is replacing the array-backed offline queue with a persistent transactional queue, which naturally leads into **#5 — the iPhone Persistent Storage & Data Engine**.




```swift
//
//  PersistentStorageEngine.swift
//  iPhoneRuntime
//
//  #5 — Persistent Storage & Data Engine
//
//  Application-level persistent storage architecture.
//  Designed for Swift 6 / modern iOS.
//
//  Goals:
//  - Actor-isolated storage
//  - Atomic persistence
//  - Versioned records
//  - Durable offline network queue
//  - Bounded disk cache
//  - Retention policies
//  - Crash-safe manifest replacement
//  - No blocking disk work on MainActor
//

import Foundation
import OSLog

// MARK: - Storage Namespace

public enum StorageNamespace: String, Codable, Sendable {
    case application
    case networkOutbox
    case cache
    case telemetry
    case analytics
    case diagnostics
    case configuration
}

// MARK: - Storage Priority

public enum StoragePriority: Int, Codable, Comparable, Sendable {
    case background = 0
    case normal = 1
    case important = 2
    case critical = 3

    public static func < (
        lhs: StoragePriority,
        rhs: StoragePriority
    ) -> Bool {
        lhs.rawValue < rhs.rawValue
    }
}

// MARK: - Persistent Envelope

public struct PersistentEnvelope<Value: Codable & Sendable>: Codable, Sendable {

    public let schemaVersion: Int
    public let identifier: UUID
    public let createdAt: Date
    public let updatedAt: Date
    public let value: Value

    public init(
        schemaVersion: Int = 1,
        identifier: UUID = UUID(),
        createdAt: Date = Date(),
        updatedAt: Date = Date(),
        value: Value
    ) {
        self.schemaVersion = schemaVersion
        self.identifier = identifier
        self.createdAt = createdAt
        self.updatedAt = updatedAt
        self.value = value
    }
}

// MARK: - Storage Errors

public enum PersistentStorageError: Error, LocalizedError, Sendable {

    case directoryCreationFailed
    case encodingFailed
    case decodingFailed
    case recordNotFound
    case invalidIdentifier
    case atomicReplacementFailed
    case quotaExceeded
    case migrationFailed
    case corruptedManifest

    public var errorDescription: String? {

        switch self {
        case .directoryCreationFailed:
            return "Unable to create the persistent storage directory."

        case .encodingFailed:
            return "Unable to encode the persistent record."

        case .decodingFailed:
            return "Unable to decode the persistent record."

        case .recordNotFound:
            return "The requested persistent record was not found."

        case .invalidIdentifier:
            return "The supplied storage identifier is invalid."

        case .atomicReplacementFailed:
            return "The atomic storage replacement failed."

        case .quotaExceeded:
            return "The storage quota has been exceeded."

        case .migrationFailed:
            return "The persistent record migration failed."

        case .corruptedManifest:
            return "The persistent storage manifest is corrupted."
        }
    }
}

// MARK: - Storage Configuration

public struct StorageConfiguration: Sendable {

    public let rootDirectory: URL
    public let maximumCacheBytes: Int64
    public let maximumCacheItems: Int
    public let defaultRetention: TimeInterval

    public init(
        rootDirectory: URL,
        maximumCacheBytes: Int64 = 250 * 1024 * 1024,
        maximumCacheItems: Int = 2_000,
        defaultRetention: TimeInterval = 30 * 24 * 60 * 60
    ) {
        self.rootDirectory = rootDirectory
        self.maximumCacheBytes = maximumCacheBytes
        self.maximumCacheItems = maximumCacheItems
        self.defaultRetention = defaultRetention
    }

    public static func applicationDefault() -> StorageConfiguration {

        let applicationSupport =
            FileManager.default.urls(
                for: .applicationSupportDirectory,
                in: .userDomainMask
            )[0]

        return StorageConfiguration(
            rootDirectory:
                applicationSupport
                .appendingPathComponent(
                    "ElitePhoneRuntime",
                    isDirectory: true
                )
        )
    }
}

// MARK: - Storage Paths

public actor StoragePathResolver {

    private let configuration: StorageConfiguration

    public init(configuration: StorageConfiguration) {
        self.configuration = configuration
    }

    public func namespaceDirectory(
        _ namespace: StorageNamespace
    ) -> URL {

        configuration.rootDirectory
            .appendingPathComponent(
                namespace.rawValue,
                isDirectory: true
            )
    }

    public func recordURL(
        namespace: StorageNamespace,
        identifier: UUID
    ) -> URL {

        namespaceDirectory(namespace)
            .appendingPathComponent(
                "\(identifier.uuidString).json"
            )
    }

    public func manifestURL(
        namespace: StorageNamespace
    ) -> URL {

        namespaceDirectory(namespace)
            .appendingPathComponent("manifest.json")
    }
}

// MARK: - Atomic File Store

public actor AtomicFileStore {

    private let fileManager: FileManager
    private let logger = Logger(
        subsystem: "ElitePhoneRuntime",
        category: "AtomicFileStore"
    )

    public init(
        fileManager: FileManager = .default
    ) {
        self.fileManager = fileManager
    }

    public func ensureDirectory(
        _ directory: URL
    ) throws {

        do {
            try fileManager.createDirectory(
                at: directory,
                withIntermediateDirectories: true
            )
        } catch {
            logger.error(
                "Directory creation failed: \(error.localizedDescription)"
            )

            throw PersistentStorageError.directoryCreationFailed
        }
    }

    public func write(
        _ data: Data,
        to url: URL
    ) throws {

        try ensureDirectory(url.deletingLastPathComponent())

        do {
            try data.write(
                to: url,
                options: [.atomic]
            )
        } catch {
            throw PersistentStorageError.atomicReplacementFailed
        }
    }

    public func read(
        from url: URL
    ) throws -> Data {

        do {
            return try Data(contentsOf: url)
        } catch {
            throw PersistentStorageError.recordNotFound
        }
    }

    public func delete(
        _ url: URL
    ) throws {

        guard fileManager.fileExists(atPath: url.path) else {
            return
        }

        try fileManager.removeItem(at: url)
    }

    public func exists(
        _ url: URL
    ) -> Bool {

        fileManager.fileExists(
            atPath: url.path
        )
    }

    public func fileSize(
        _ url: URL
    ) -> Int64 {

        guard
            let attributes =
                try? fileManager.attributesOfItem(
                    atPath: url.path
                ),
            let size =
                attributes[
                    .size
                ] as? NSNumber
        else {
            return 0
        }

        return size.int64Value
    }
}

// MARK: - Persistent Key/Value Store

public actor PersistentKeyValueStore {

    private let namespace: StorageNamespace
    private let paths: StoragePathResolver
    private let files: AtomicFileStore

    private let encoder = JSONEncoder()
    private let decoder = JSONDecoder()

    public init(
        namespace: StorageNamespace,
        paths: StoragePathResolver,
        files: AtomicFileStore
    ) {
        self.namespace = namespace
        self.paths = paths
        self.files = files
    }

    public func set<Value: Codable & Sendable>(
        key: String,
        value: Value
    ) async throws {

        guard
            let identifier =
                UUID(uuidString: key)
                ?? UUID(
                    uuidString:
                        UUID(
                            md5: Data(key.utf8)
                        ).uuidString
                )
        else {
            throw PersistentStorageError.invalidIdentifier
        }

        let envelope = PersistentEnvelope(
            value: value
        )

        do {
            let data = try encoder.encode(envelope)

            let url = await paths.recordURL(
                namespace: namespace,
                identifier: identifier
            )

            try await files.write(
                data,
                to: url
            )

        } catch {
            throw PersistentStorageError.encodingFailed
        }
    }

    public func get<Value: Codable & Sendable>(
        key: String,
        as type: Value.Type
    ) async throws -> Value {

        guard
            let identifier = UUID(uuidString: key)
        else {
            throw PersistentStorageError.invalidIdentifier
        }

        let url = await paths.recordURL(
            namespace: namespace,
            identifier: identifier
        )

        let data = try await files.read(
            from: url
        )

        do {
            let envelope =
                try decoder.decode(
                    PersistentEnvelope<Value>.self,
                    from: data
                )

            return envelope.value

        } catch {
            throw PersistentStorageError.decodingFailed
        }
    }

    public func delete(
        key: String
    ) async throws {

        guard
            let identifier = UUID(uuidString: key)
        else {
            throw PersistentStorageError.invalidIdentifier
        }

        let url = await paths.recordURL(
            namespace: namespace,
            identifier: identifier
        )

        try await files.delete(url)
    }
}

// MARK: - Persistent Queue Entry

public struct PersistentQueueEntry<Value: Codable & Sendable>: Codable, Sendable {

    public let identifier: UUID
    public let createdAt: Date
    public let priority: StoragePriority
    public let value: Value

    public init(
        identifier: UUID = UUID(),
        createdAt: Date = Date(),
        priority: StoragePriority = .normal,
        value: Value
    ) {
        self.identifier = identifier
        self.createdAt = createdAt
        self.priority = priority
        self.value = value
    }
}

// MARK: - Queue Manifest

private struct PersistentQueueManifest: Codable, Sendable {

    var schemaVersion: Int = 1

    /// IDs are maintained separately from the actual payload files.
    var orderedIdentifiers: [UUID] = []

    var updatedAt: Date = Date()
}

// MARK: - Persistent Queue

public actor PersistentQueue<Value: Codable & Sendable> {

    private let namespace: StorageNamespace
    private let paths: StoragePathResolver
    private let files: AtomicFileStore

    private let encoder = JSONEncoder()
    private let decoder = JSONDecoder()

    private var manifest = PersistentQueueManifest()
    private var loaded = false

    public init(
        namespace: StorageNamespace,
        paths: StoragePathResolver,
        files: AtomicFileStore
    ) {
        self.namespace = namespace
        self.paths = paths
        self.files = files
    }

    // MARK: Loading

    private func ensureLoaded() async throws {

        guard !loaded else {
            return
        }

        let url = await paths.manifestURL(
            namespace: namespace
        )

        guard await files.exists(url) else {
            loaded = true
            return
        }

        do {
            let data = try await files.read(
                from: url
            )

            manifest =
                try decoder.decode(
                    PersistentQueueManifest.self,
                    from: data
                )

            loaded = true

        } catch {
            throw PersistentStorageError.corruptedManifest
        }
    }

    // MARK: Manifest Persistence

    private func persistManifest() async throws {

        manifest.updatedAt = Date()

        let data = try encoder.encode(
            manifest
        )

        let url = await paths.manifestURL(
            namespace: namespace
        )

        try await files.write(
            data,
            to: url
        )
    }

    // MARK: Entry URL

    private func entryURL(
        _ identifier: UUID
    ) async -> URL {

        await paths.recordURL(
            namespace: namespace,
            identifier: identifier
        )
    }

    // MARK: Enqueue

    @discardableResult
    public func enqueue(
        _ value: Value,
        priority: StoragePriority = .normal
    ) async throws -> UUID {

        try await ensureLoaded()

        let entry = PersistentQueueEntry(
            priority: priority,
            value: value
        )

        let data = try encoder.encode(entry)

        let url = await entryURL(
            entry.identifier
        )

        // Payload first.
        try await files.write(
            data,
            to: url
        )

        // Manifest second.
        manifest.orderedIdentifiers.append(
            entry.identifier
        )

        do {
            try await persistManifest()
        } catch {
            // Roll back payload if manifest persistence fails.
            try? await files.delete(url)
            manifest.orderedIdentifiers.removeAll {
                $0 == entry.identifier
            }

            throw PersistentStorageError.atomicReplacementFailed
        }

        return entry.identifier
    }

    // MARK: Peek

    public func peek() async throws
        -> PersistentQueueEntry<Value>?
    {
        try await ensureLoaded()

        guard
            let identifier =
                manifest.orderedIdentifiers.first
        else {
            return nil
        }

        let url = await entryURL(identifier)

        let data = try await files.read(
            from: url
        )

        do {
            return try decoder.decode(
                PersistentQueueEntry<Value>.self,
                from: data
            )
        } catch {
            throw PersistentStorageError.decodingFailed
        }
    }

    // MARK: Remove

    public func remove(
        identifier: UUID
    ) async throws {

        try await ensureLoaded()

        let url = await entryURL(identifier)

        try await files.delete(url)

        manifest.orderedIdentifiers.removeAll {
            $0 == identifier
        }

        try await persistManifest()
    }

    // MARK: Count

    public func count() async throws -> Int {

        try await ensureLoaded()

        return manifest.orderedIdentifiers.count
    }

    // MARK: Clear

    public func removeAll() async throws {

        try await ensureLoaded()

        for identifier in manifest.orderedIdentifiers {

            let url = await entryURL(identifier)

            try? await files.delete(url)
        }

        manifest.orderedIdentifiers.removeAll()

        try await persistManifest()
    }

    // MARK: Snapshot

    public func identifiers() async throws
        -> [UUID]
    {
        try await ensureLoaded()

        return manifest.orderedIdentifiers
    }
}

// MARK: - Persistent Network Request

/// Serializable representation of a network request.
/// URLRequest itself is intentionally not persisted directly.
public struct PersistentHTTPRequest:
    Codable,
    Sendable
{

    public let identifier: UUID
    public let url: URL
    public let method: String
    public let headers: [String: String]
    public let body: Data?
    public let createdAt: Date
    public let priority: StoragePriority
    public let retryCount: Int

    public init(
        identifier: UUID = UUID(),
        url: URL,
        method: String = "GET",
        headers: [String: String] = [:],
        body: Data? = nil,
        createdAt: Date = Date(),
        priority: StoragePriority = .normal,
        retryCount: Int = 0
    ) {
        self.identifier = identifier
        self.url = url
        self.method = method
        self.headers = headers
        self.body = body
        self.createdAt = createdAt
        self.priority = priority
        self.retryCount = retryCount
    }

    public func makeURLRequest() -> URLRequest {

        var request = URLRequest(
            url: url
        )

        request.httpMethod = method
        request.httpBody = body

        for (key, value) in headers {
            request.setValue(
                value,
                forHTTPHeaderField: key
            )
        }

        return request
    }
}

// MARK: - Network Outbox

public actor PersistentNetworkOutbox {

    private let queue:
        PersistentQueue<PersistentHTTPRequest>

    public init(
        paths: StoragePathResolver,
        files: AtomicFileStore
    ) {
        self.queue = PersistentQueue(
            namespace: .networkOutbox,
            paths: paths,
            files: files
        )
    }

    @discardableResult
    public func enqueue(
        _ request: PersistentHTTPRequest,
        priority: StoragePriority = .normal
    ) async throws -> UUID {

        try await queue.enqueue(
            request,
            priority: priority
        )
    }

    public func next()
        async throws -> PersistentQueueEntry<PersistentHTTPRequest>?
    {
        try await queue.peek()
    }

    public func acknowledge(
        _ identifier: UUID
    ) async throws {

        try await queue.remove(
            identifier: identifier
        )
    }

    public func pendingCount()
        async throws -> Int
    {
        try await queue.count()
    }

    public func removeAll()
        async throws
    {
        try await queue.removeAll()
    }
}

// MARK: - Cache Entry

public struct DiskCacheEntry<Value: Codable & Sendable>:
    Codable,
    Sendable
{

    public let key: String
    public let createdAt: Date
    public let expiresAt: Date?
    public let value: Value

    public init(
        key: String,
        createdAt: Date = Date(),
        expiresAt: Date? = nil,
        value: Value
    ) {
        self.key = key
        self.createdAt = createdAt
        self.expiresAt = expiresAt
        self.value = value
    }

    public var isExpired: Bool {

        guard let expiresAt else {
            return false
        }

        return Date() >= expiresAt
    }
}

// MARK: - Cache Metadata

private struct CacheMetadata:
    Codable,
    Sendable
{

    let key: String
    let lastAccess: Date
    let size: Int64
}

// MARK: - Disk Cache

public actor PersistentDiskCache<Value: Codable & Sendable> {

    private let paths: StoragePathResolver
    private let files: AtomicFileStore

    private let maximumBytes: Int64
    private let maximumItems: Int

    private var metadata:
        [String: CacheMetadata] = [:]

    private let encoder = JSONEncoder()
    private let decoder = JSONDecoder()

    public init(
        paths: StoragePathResolver,
        files: AtomicFileStore,
        maximumBytes: Int64 = 250 * 1024 * 1024,
        maximumItems: Int = 2_000
    ) {
        self.paths = paths
        self.files = files
        self.maximumBytes = maximumBytes
        self.maximumItems = maximumItems
    }

    private func cacheIdentifier(
        _ key: String
    ) -> UUID {

        UUID(
            md5: Data(
                key.utf8
            )
        )
    }

    private func cacheURL(
        _ key: String
    ) async -> URL {

        await paths.recordURL(
            namespace: .cache,
            identifier: cacheIdentifier(key)
        )
    }

    public func set(
        key: String,
        value: Value,
        expiration: TimeInterval? = nil
    ) async throws {

        let expiresAt =
            expiration.map {
                Date().addingTimeInterval($0)
            }

        let entry = DiskCacheEntry(
            key: key,
            expiresAt: expiresAt,
            value: value
        )

        let data = try encoder.encode(entry)

        let url = await cacheURL(key)

        try await files.write(
            data,
            to: url
        )

        metadata[key] = CacheMetadata(
            key: key,
            lastAccess: Date(),
            size: Int64(data.count)
        )

        try await enforceLimits()
    }

    public func get(
        key: String
    ) async throws -> Value? {

        let url = await cacheURL(key)

        guard await files.exists(url) else {
            return nil
        }

        let data = try await files.read(
            from: url
        )

        let entry =
            try decoder.decode(
                DiskCacheEntry<Value>.self,
                from: data
            )

        if entry.isExpired {

            try await files.delete(url)
            metadata.removeValue(
                forKey: key
            )

            return nil
        }

        metadata[key] = CacheMetadata(
            key: key,
            lastAccess: Date(),
            size: Int64(data.count)
        )

        return entry.value
    }

    public func remove(
        key: String
    ) async throws {

        let url = await cacheURL(key)

        try await files.delete(url)

        metadata.removeValue(
            forKey: key
        )
    }

    private func enforceLimits() async throws {

        while
            metadata.count > maximumItems
            ||
            totalBytes() > maximumBytes
        {

            guard
                let oldest =
                    metadata.values.min(
                        by: {
                            $0.lastAccess < $1.lastAccess
                        }
                    )
            else {
                break
            }

            let url = await cacheURL(
                oldest.key
            )

            try await files.delete(url)

            metadata.removeValue(
                forKey: oldest.key
            )
        }
    }

    private func totalBytes() -> Int64 {

        metadata.values.reduce(
            0
        ) {
            $0 + $1.size
        }
    }

    public func statistics()
        -> (items: Int, bytes: Int64)
    {
        (
            metadata.count,
            totalBytes()
        )
    }
}

