}

// MARK: - Render Clock

public actor RenderClock {

    private let clock =
        ContinuousClock()

    private var lastEmission:
        ContinuousClock.Instant?

    public init() {}

    public func shouldEmit(
        frequency: Double
    ) -> Bool {

        guard frequency > 0 else {
            return false
        }

        let now = clock.now

        guard let lastEmission else {

            self.lastEmission = now
            return true
        }

        let interval =
            1.0 / frequency

        let elapsed =
            lastEmission.duration(
                to: now
            )

        let elapsedSeconds =
            elapsed.components.secondsAsDouble

        guard elapsedSeconds >= interval else {
            return false
        }

        self.lastEmission = now

        return true
    }

    public func reset() {
        lastEmission = nil
    }
}

// MARK: - Duration Helper

private extension Duration {

    var components:
        (seconds: Int64, attoseconds: Int64)
    {
        let value = self

        return (
            value.components.seconds,
            value.components.attoseconds
        )
    }

    var secondsAsDouble: Double {

        Double(components.seconds)
        +
        Double(components.attoseconds)
        / 1_000_000_000_000_000_000
    }
}

// MARK: - Render State

public struct RenderState<Value: Sendable>:
    Sendable
{

    public let value: Value
    public let sequence: UInt64
    public let timestamp: Date

    public init(
        value: Value,
        sequence: UInt64,
        timestamp: Date = Date()
    ) {
        self.value = value
        self.sequence = sequence
        self.timestamp = timestamp
    }
}

// MARK: - UI State Coalescer

public actor UIStateCoalescer<Value: Sendable> {

    private var pending:
        RenderState<Value>?

    private var sequence: UInt64 = 0

    private var flushTask:
        Task<Void, Never>?

    private let frequency: Double

    private let clock =
        ContinuousClock()

    private let continuation:
        @Sendable (RenderState<Value>) -> Void

    public init(
        frequency: Double,
        continuation:
            @escaping @Sendable
            (RenderState<Value>) -> Void
    ) {

        self.frequency =
            max(0.1, frequency)

        self.continuation =
            continuation
    }

    public func submit(
        _ value: Value
    ) {

        sequence += 1

        pending =
            RenderState(
                value: value,
                sequence: sequence
            )

        guard flushTask == nil else {
            return
        }

        let interval =
            1.0 / frequency

        flushTask =
            Task { [weak self] in

                let nanoseconds =
                    UInt64(
                        interval * 1_000_000_000
                    )

                try? await Task.sleep(
                    nanoseconds:
                        nanoseconds
                )

                guard
                    !Task.isCancelled
                else {
                    return
                }

                await self?.flush()
            }
    }

    private func flush() {

        guard
            let pending
        else {
            flushTask = nil
            return
        }

        self.pending = nil
        self.flushTask = nil

        continuation(pending)
    }

    public func stop() {

        flushTask?.cancel()
        flushTask = nil
        pending = nil
    }
}

// MARK: - Render Work Item

public struct RenderWorkItem:
    Identifiable,
    Sendable
{

    public let id: UUID
    public let workload: UIWorkload
    public let priority: UIPriority
    public let createdAt: Date

    public init(
        id: UUID = UUID(),
        workload: UIWorkload,
        priority: UIPriority,
        createdAt: Date = Date()
    ) {
        self.id = id
        self.workload = workload
        self.priority = priority
        self.createdAt = createdAt
    }
}

// MARK: - Render Scheduler

public actor RenderScheduler {

    private struct ScheduledWork {
        let item: RenderWorkItem
        let operation:
            @Sendable () async -> Void
    }

    private var queue:
        [ScheduledWork] = []

    private var isRunning = false

    private var currentMode:
        RenderMode = .balanced

    private let logger =
        Logger(
            subsystem:
                "EliteiPhoneRuntime",
            category:
                "RenderScheduler"
        )

    public init() {}

    public func setMode(
        _ mode: RenderMode
    ) {
        currentMode = mode
    }

    public func submit(
        workload: UIWorkload,
        priority: UIPriority,
        operation:
            @escaping @Sendable
            () async -> Void
    ) {

        let item =
            RenderWorkItem(
                workload: workload,
                priority: priority
            )

        queue.append(
            ScheduledWork(
                item: item,
                operation: operation
            )
        )

        queue.sort {
            $0.item.priority
                > $1.item.priority
        }

        startIfNeeded()
    }

    private func startIfNeeded() {

        guard !isRunning else {
            return
        }

        isRunning = true

        Task { [weak self] in

            await self?.drain()
        }
    }

    private func drain() async {

        while !queue.isEmpty {

            guard
                let work = queue.first
            else {
                break
            }

            queue.removeFirst()

            await work.operation()
        }

        isRunning = false

        logger.debug(
            "Render work queue drained."
        )
    }

    public func pendingCount() -> Int {
        queue.count
    }
}

// MARK: - Animation Policy

public struct AnimationPolicy:
    Sendable
{

    public let mode: RenderMode
    public let allowsAnimations: Bool
    public let allowsTransitions: Bool
    public let allowsContinuousEffects: Bool

    public init(
        mode: RenderMode,
        allowsAnimations: Bool,
        allowsTransitions: Bool,
        allowsContinuousEffects: Bool
    ) {
        self.mode = mode
        self.allowsAnimations =
            allowsAnimations
        self.allowsTransitions =
            allowsTransitions
        self.allowsContinuousEffects =
            allowsContinuousEffects
    }

    public static func forMode(
        _ mode: RenderMode
    ) -> AnimationPolicy {

        switch mode {

        case .maximum:
            return AnimationPolicy(
                mode: mode,
                allowsAnimations: true,
                allowsTransitions: true,
                allowsContinuousEffects: true
            )

        case .high:
            return AnimationPolicy(
                mode: mode,
                allowsAnimations: true,
                allowsTransitions: true,
                allowsContinuousEffects: true
            )

        case .balanced:
            return AnimationPolicy(
                mode: mode,
                allowsAnimations: true,
                allowsTransitions: true,
                allowsContinuousEffects: false
            )

        case .efficient:
            return AnimationPolicy(
                mode: mode,
                allowsAnimations: false,
                allowsTransitions: true,
                allowsContinuousEffects: false
            )

        case .emergency:
            return AnimationPolicy(
                mode: mode,
                allowsAnimations: false,
                allowsTransitions: false,
                allowsContinuousEffects: false
            )
        }
    }

    public var transaction:
        Transaction
    {
        var transaction =
            Transaction()

        transaction.animation =
            allowsAnimations
            ? .default
            : nil

        return transaction
    }
}

// MARK: - Image Cache

public actor RenderImageCache {

    private struct Entry {

        let image: UIImage
        let cost: Int64
        var lastAccess: Date
    }

    private var entries:
        [String: Entry] = [:]

    private let maximumCost: Int64

    private var currentCost: Int64 = 0

    public init(
        maximumCost:
            Int64 =
            128 * 1024 * 1024
    ) {
        self.maximumCost =
            maximumCost
    }

    public func insert(
        _ image: UIImage,
        forKey key: String,
        estimatedCost: Int64
    ) {

        if let old = entries[key] {

            currentCost -= old.cost
        }

        entries[key] =
            Entry(
                image: image,
                cost:
                    max(
                        1,
                        estimatedCost
                    ),
                lastAccess: Date()
            )

        currentCost +=
            max(
                1,
                estimatedCost
            )

        evictIfNeeded()
    }

    public func image(
        forKey key: String
    ) -> UIImage? {

        guard
            var entry = entries[key]
        else {
            return nil
        }

        entry.lastAccess =
            Date()

        entries[key] =
            entry

        return entry.image
    }

    public func remove(
        forKey key: String
    ) {

        guard
            let entry =
                entries.removeValue(
                    forKey: key
                )
        else {
            return
        }

        currentCost -= entry.cost
    }

    public func removeAll() {

        entries.removeAll()
        currentCost = 0
    }

    private func evictIfNeeded() {

        while currentCost > maximumCost {

            guard
                let oldest =
                    entries.values.min(
                        by: {
                            $0.lastAccess
                                <
                            $1.lastAccess
                        }
                    )
            else {
                break
            }

            guard
                let key =
                    entries.first(
                        where: {
                            $0.value.lastAccess
                            ==
                            oldest.lastAccess
                        }
                    )?.key
            else {
                break
            }

            currentCost -=
                entries[key]?.cost ?? 0

            entries.removeValue(
                forKey: key
            )
        }
    }

    public func statistics()
        -> (items: Int, cost: Int64)
    {
        (
            entries.count,
            currentCost
        )
    }
}

