// MARK: - Display Refresh Policy

@MainActor
public final class DisplayRefreshPolicy:
    ObservableObject
{

    @Published
    public private(set) var preferredFrameRate:
        Int = 60

    @Published
    public private(set) var mode:
        RenderMode = .balanced

    public init() {}

    public func apply(
        profile: RenderProfile
