// MARK: - Power Integration

public actor RenderPowerAdapter {

    private var mode:
        RenderMode = .balanced

    public init() {}

    public func apply(
        powerMode: String
    ) {

        switch powerMode {

        case "maximumPerformance":
            mode = .maximum

        case "performance":
            mode = .high

        case "balanced":
            mode = .balanced

        case "efficiency":
            mode = .efficient

        case "emergency":
            mode = .emergency

        default:
            mode = .balanced
        }
    }

    public func currentMode()
        -> RenderMode
    {
        mode
    }
}

// MARK: - UI Runtime

@MainActor
public final class HighPerformanceUIRuntime:
    ObservableObject
{

    public static let shared =
        HighPerformanceUIRuntime()

    public let state =
        RuntimeUIState()

    public let displayPolicy =
        DisplayRefreshPolicy()

    public let imageCache =
        RenderImageCache()

    public let scheduler =
        RenderScheduler()

    public let performanceMonitor =
        UIPerformanceMonitor()

    public let powerAdapter =
        RenderPowerAdapter()

    private var renderMode:
        RenderMode = .balanced

    private init() {}

    // MARK: Configure

    public func configure(
        profile: RenderProfile
    ) {

        renderMode =
            profile.mode

        displayPolicy.apply(
            profile: profile
        )

        state.apply(
            mode: profile.mode
        )

        Task {

            await scheduler.setMode(
                profile.mode
            )
        }
    }

    // MARK: Submit UI Work

    public func submit(
        workload: UIWorkload,
        priority: UIPriority,
        operation:
            @escaping @Sendable
            () async -> Void
    ) {

        Task {

            await scheduler.submit(
                workload: workload,
                priority: priority,
                operation: operation
            )
        }
    }

    // MARK: Dashboard Update

    public func updateDashboard(
        value: Double,
        status: String
    ) {

        Task {

            await performanceMonitor
                .recordStateUpdate()

            await MainActor.run {

                state.apply(
                    dashboardValue: value,
                    statusText: status
                )
            }
        }
    }

    // MARK: Animation

    public var animationPolicy:
        AnimationPolicy
    {
        AnimationPolicy.forMode(
            renderMode
        )
    }
}

