// MARK: - Image Pipeline

public actor RuntimeImagePipeline {

    private let cache:
        RenderImageCache

    public init(
        cache:
            RenderImageCache =
            RenderImageCache()
    ) {
        self.cache = cache
    }

    public func image(
        forKey key: String,
        loader:
            @escaping @Sendable
            () async throws -> UIImage
    ) async throws -> UIImage {

        if let cached =
            await cache.image(
                forKey: key
            ) {
            return cached
        }

        let image =
            try await loader()

        let estimatedCost =
            Int64(
                image.size.width
                *
                image.size.height
                *
                4
            )

        await cache.insert(
            image,
            forKey: key,
            estimatedCost:
                estimatedCost
        )

        return image
    }
}

