```swift id="s8k2qd"
//
//  SecurityPrivacyRuntime.swift
//  EliteiPhoneRuntime
//
//  #7 — Security & Privacy Runtime
//
//  Application-level security architecture using public Apple APIs.
//
//  Provides:
//  - Keychain-backed secrets
//  - Secure Enclave-backed keys
//  - Authentication/session state
//  - Access-control policies
//  - Cryptographic helpers
//  - Secure random identifiers
//  - Sensitive-data redaction
//  - Network security policy
//  - Privacy-aware diagnostics
//
//  IMPORTANT:
//  This is application-level security.
//  It does not attempt to replace iOS security, Secure Enclave,
//  App Attest, DeviceCheck, TLS, or Apple's platform protections.
//

import Foundation
import Security
import CryptoKit
import LocalAuthentication
import OSLog

// MARK: - Security Namespace

public enum SecurityNamespace: String, Sendable {

    case authentication
    case credentials
    case encryption
    case sessions
    case configuration
    case diagnostics
}

// MARK: - Security Errors

public enum SecurityRuntimeError:
    Error,
    LocalizedError,
    Sendable
{

    case keychainFailure(OSStatus)
    case itemNotFound
    case invalidData
    case encodingFailure
    case decodingFailure
    case authenticationFailed
    case authenticationCancelled
    case authenticationUnavailable
    case secureEnclaveUnavailable
    case keyGenerationFailed
    case encryptionFailed
    case decryptionFailed
    case invalidSignature
    case invalidConfiguration
    case insecureNetworkConfiguration

    public var errorDescription: String? {

        switch self {

        case .keychainFailure(let status):
            return
                "Keychain operation failed: \(status)"

        case .itemNotFound:
            return
                "The requested secure item was not found."

        case .invalidData:
            return
                "The supplied security data is invalid."

        case .encodingFailure:
            return
                "Security payload encoding failed."

        case .decodingFailure:
            return
                "Security payload decoding failed."

        case .authenticationFailed:
            return
                "User authentication failed."

        case .authenticationCancelled:
            return
                "User authentication was cancelled."

        case .authenticationUnavailable:
            return
                "Local authentication is unavailable."

        case .secureEnclaveUnavailable:
            return
                "Secure Enclave-backed key storage is unavailable."

        case .keyGenerationFailed:
            return
                "Secure key generation failed."

        case .encryptionFailed:
            return
                "Encryption failed."

        case .decryptionFailed:
            return
                "Decryption failed."

        case .invalidSignature:
            return
                "Signature verification failed."

        case .invalidConfiguration:
            return
                "Security configuration is invalid."

        case .insecureNetworkConfiguration:
            return
                "The network security configuration is invalid."
        }
    }
}

// MARK: - Secret

/// Deliberately does not expose a printable description.
public struct SecureSecret:
    Sendable
{

    private let data: Data

    public init(
        data: Data
    ) {
        self.data = data
    }

    public init(
        string: String
    ) {
        self.data =
            Data(
                string.utf8
            )
    }

    public func rawData() -> Data {
        data
    }

    public func utf8String() -> String? {
        String(
            data: data,
            encoding: .utf8
        )
    }
}

// MARK: - Keychain Configuration

public struct KeychainConfiguration:
    Sendable
{

    public let service: String
    public let accessGroup: String?
    public let accessibility:
        CFString

    public init(
        service: String,
        accessGroup: String? = nil,
        accessibility:
            CFString =
            kSecAttrAccessibleWhenUnlockedThisDeviceOnly
    ) {

        self.service = service
        self.accessGroup = accessGroup
        self.accessibility = accessibility
    }

    public static func applicationDefault()
        -> KeychainConfiguration
    {
        KeychainConfiguration(
            service:
                Bundle.main.bundleIdentifier
                ?? "EliteiPhoneRuntime"
        )
    }
}

// MARK: - Keychain Store

public actor SecureKeychainStore {

    private let configuration:
        KeychainConfiguration

    private let logger =
        Logger(
            subsystem:
                "EliteiPhoneRuntime",
            category:
                "Keychain"
        )

    public init(
        configuration:
            KeychainConfiguration =
            .applicationDefault()
    ) {
        self.configuration =
            configuration
    }

    // MARK: Save

    public func save(
        _ secret: SecureSecret,
        account: String
    ) throws {

        var query =
            baseQuery(
                account: account
            )

        query[
            kSecValueData as String
        ] =
            secret.rawData()

        query[
            kSecAttrAccessible as String
        ] =
            configuration.accessibility

        let status =
            SecItemAdd(
                query as CFDictionary,
                nil
            )

        if status == errSecDuplicateItem {

            try update(
                secret,
                account: account
            )

            return
        }

        guard status == errSecSuccess else {

            logger.error(
                "Keychain save failed."
            )

            throw
                SecurityRuntimeError
                    .keychainFailure(status)
        }
    }

    // MARK: Update

    public func update(
        _ secret: SecureSecret,
        account: String
    ) throws {

        let query =
            baseQuery(
                account: account
            )

        let attributes:
            [String: Any] = [
                kSecValueData as String:
                    secret.rawData()
            ]

        let status =
            SecItemUpdate(
                query as CFDictionary,
                attributes as CFDictionary
            )

        guard status == errSecSuccess else {

            throw
                SecurityRuntimeError
                    .keychainFailure(status)
        }
    }

    // MARK: Read

    public func read(
        account: String
    ) throws -> SecureSecret {

        var query =
            baseQuery(
                account: account
            )

        query[
            kSecReturnData as String
        ] = true

        query[
            kSecMatchLimit as String
        ] =
            kSecMatchLimitOne

        var result:
            CFTypeRef?

        let status =
            SecItemCopyMatching(
                query as CFDictionary,
                &result
            )

        guard status != errSecSuccess else {

            if status == errSecItemNotFound {
                throw
                    SecurityRuntimeError
                        .itemNotFound
            }

            throw
                SecurityRuntimeError
                    .keychainFailure(status)
        }

        guard
            let data =
                result as? Data
        else {
            throw
                SecurityRuntimeError
                    .invalidData
        }

        return SecureSecret(
            data: data
        )
    }

    // MARK: Delete

    public func delete(
        account: String
    ) throws {

        let query =
            baseQuery(
                account: account
            )

        let status =
            SecItemDelete(
                query as CFDictionary
            )

        guard
            status == errSecSuccess
            ||
            status == errSecItemNotFound
        else {

            throw
                SecurityRuntimeError
                    .keychainFailure(status)
        }
    }

    // MARK: Exists

    public func exists(
        account: String
    ) -> Bool {

        var query =
            baseQuery(
                account: account
            )

        query[
            kSecReturnData as String
        ] = false

        let status =
            SecItemCopyMatching(
                query as CFDictionary,
                nil
            )

        return status == errSecSuccess
    }

    private func baseQuery(
        account: String
    ) -> [String: Any] {

        var query:
            [String: Any] = [

                kSecClass as String:
                    kSecClassGenericPassword,

                kSecAttrService as String:
                    configuration.service,

                kSecAttrAccount as String:
                    account
            ]

        if let accessGroup =
            configuration.accessGroup {

            query[
                kSecAttrAccessGroup as String
            ] =
                accessGroup
        }

        return query
    }
}

// MARK: - Secure Enclave Key Manager

public actor SecureEnclaveKeyManager {

    private let tag:
        Data

    public init(
        tag: String
    ) {

        self.tag =
            Data(
                tag.utf8
            )
    }

    public func loadOrCreateKey()
        throws -> SecureEnclave.P256.Signing.PrivateKey
    {

        if let existing =
            try loadExistingKey() {

            return existing
        }

        do {

            return try
                SecureEnclave.P256.Signing.PrivateKey(
                    accessControl:
                        SecAccessControlCreateWithFlags(
                            nil,
                            kSecAttrAccessibleWhenUnlockedThisDeviceOnly,
                            .privateKeyUsage,
                            nil
                        )!,
                    authenticationContext: nil
                )

        } catch {

            throw
                SecurityRuntimeError
                    .keyGenerationFailed
        }
    }

    private func loadExistingKey()
        throws
        -> SecureEnclave.P256.Signing.PrivateKey?
    {

        let query:
            [String: Any] = [

                kSecClass as String:
                    kSecClassKey,

                kSecAttrApplicationTag as String:
                    tag,

                kSecReturnRef as String:
                    true
            ]

        var result:
            CFTypeRef?

        let status =
            SecItemCopyMatching(
                query as CFDictionary,
                &result
            )

        guard
            status != errSecSuccess
        else {

            guard
                let reference =
                    result
                    as! SecKey?
            else {
                return nil
            }

            return try
                SecureEnclave.P256.Signing
                    .PrivateKey(
                        secKey:
                            reference
                    )
        }

        if status == errSecItemNotFound {
            return nil
        }

        throw
            SecurityRuntimeError
                .keychainFailure(status)
    }
}

// MARK: - Secure Random Generator

public enum SecureRandom {

    public static func bytes(
        count: Int
    ) throws -> Data {

        guard count > 0 else {
            return Data()
        }

        var data =
            Data(
                count: count
            )

        let status =
            data.withUnsafeMutableBytes {
                buffer in

                SecRandomCopyBytes(
                    kSecRandomDefault,
                    buffer.count,
                    buffer.baseAddress!
                )
            }

        guard status == errSecSuccess else {

            throw
                SecurityRuntimeError
                    .keychainFailure(status)
        }

        return data
    }

    public static func identifier()
        throws -> UUID
    {

        let data =
            try bytes(
                count: 16
            )

        var uuid =
            UUID()

        withUnsafeMutableBytes(
            of: &uuid
        ) { destination in

            data.copyBytes(
                to: destination
            )
        }

        return uuid
    }
}

// MARK: - Symmetric Encryption

public struct EncryptedPayload:
    Sendable
{

    fileprivate let data: Data

    public init(
        data: Data
    ) {
        self.data = data
    }

    public func rawData() -> Data {
        data
    }
}

public enum SymmetricCrypto {

    public static func generateKey()
        -> SymmetricKey
    {
        SymmetricKey(
            size: .bits256
        )
    }

    public static func encrypt(
        _ data: Data,
        using key: SymmetricKey
    ) throws -> EncryptedPayload {

        do {

            let sealedBox =
                try AES.GCM.seal(
                    data,
                    using: key
                )

            guard
                let combined =
                    sealedBox.combined
            else {
                throw
                    SecurityRuntimeError
                        .encryptionFailed
            }

            return EncryptedPayload(
                data: combined
            )

        } catch {

            throw
                SecurityRuntimeError
                    .encryptionFailed
        }
    }

    public static func decrypt(
        _ payload: EncryptedPayload,
        using key: SymmetricKey
    ) throws -> Data {

        do {

            let box =
                try AES.GCM.SealedBox(
                    combined:
                        payload.rawData()
                )

            return try AES.GCM.open(
                box,
                using: key
            )

        } catch {

            throw
                SecurityRuntimeError
                    .decryptionFailed
        }
    }
}

// MARK: - Hashing

public enum SecureHash {

    public static func sha256(
        _ data: Data
    ) -> Data {

        Data(
            SHA256.hash(
                data: data
            )
        )
    }

    public static func sha256Hex(
        _ data: Data
    ) -> String {

        SHA256.hash(
            data: data
        )
        .map {
            String(
                format: "%02x",
                $0
            )
        }
        .joined()
    }
}

// MARK: - Digital Signature

public struct PublicSigningKey:
    Sendable
{

    fileprivate let rawRepresentation:
        Data

    public init(
        rawRepresentation: Data
    ) {
        self.rawRepresentation =
            rawRepresentation
    }

    public func data() -> Data {
        rawRepresentation
    }
}

public struct DigitalSignature:
    Sendable
{

    fileprivate let rawRepresentation:
        Data

    public init(
        rawRepresentation: Data
    ) {
        self.rawRepresentation =
            rawRepresentation
    }

    public func data() -> Data {
        rawRepresentation
    }
}

public enum SignatureService {

    public static func sign(
        data: Data,
        privateKey:
            P256.Signing.PrivateKey
    ) throws -> DigitalSignature {

        do {

            let signature =
                try privateKey.signature(
                    for: data
                )

            return DigitalSignature(
                rawRepresentation:
                    signature.rawRepresentation
            )

        } catch {

            throw
                SecurityRuntimeError
                    .invalidSignature
        }
    }

    public static func verify(
        data: Data,
        signature:
            DigitalSignature,
        publicKey:
            PublicSigningKey
    ) -> Bool {

        guard
            let key =
                try? P256.Signing.PublicKey(
                    rawRepresentation:
                        publicKey.rawRepresentation
                ),
            let signature =
                try? P256.Signing.ECDSASignature(
                    rawRepresentation:
                        signature.rawRepresentation
                )
        else {
            return false
        }

        return key.isValidSignature(
            signature,
            for: data
        )
    }
}

// MARK: - User Authentication

public enum AuthenticationMethod:
    Sendable
{

    case biometrics
    case deviceOwnerAuthentication
}

public actor UserAuthenticationService {

    private let context =
        LAContext()

    public init() {}

    public func authenticate(
        reason: String,
        method:
            AuthenticationMethod =
            .deviceOwnerAuthentication
    ) async throws -> Bool {

        var error:
            NSError?

        let policy:
            LAPolicy

        switch method {

        case .biometrics:
            policy =
                .deviceOwnerAuthenticationWithBiometrics

        case .deviceOwnerAuthentication:
            policy =
                .deviceOwnerAuthentication
        }

        guard
            context.canEvaluatePolicy(
                policy,
                error: &error
            )
        else {

            throw
                SecurityRuntimeError
                    .authenticationUnavailable
        }

        do {

            return try await
                context.evaluatePolicy(
                    policy,
                    localizedReason:
                        reason
                )

        } catch {

            throw
                SecurityRuntimeError
                    .authenticationFailed
        }
    }
}

// MARK: - Session State

public enum SecureSessionState:
    String,
    Sendable
{

    case unauthenticated
    case authenticating
    case authenticated
    case expired
    case locked
}

public struct SecureSession:
    Sendable
{

    public let identifier: UUID
    public let createdAt: Date
    public let expiresAt: Date

    public init(
        identifier: UUID,
        createdAt: Date,
        expiresAt: Date
    ) {
        self.identifier = identifier
        self.createdAt = createdAt
        self.expiresAt = expiresAt
    }

    public var isExpired: Bool {
        Date() >= expiresAt
    }
}

// MARK: - Session Manager

public actor SecureSessionManager {

    private(set) var state:
        SecureSessionState =
        .unauthenticated

    private(set) var session:
        SecureSession?

    private let authentication:
        UserAuthenticationService

    private let sessionLifetime:
        TimeInterval

    public init(
        authentication:
            UserAuthenticationService =
            UserAuthenticationService(),
        sessionLifetime:
            TimeInterval =
            15 * 60
    ) {

        self.authentication =
            authentication

        self.sessionLifetime =
            sessionLifetime
    }

    public func authenticate()
        async throws
        -> SecureSession
    {

        state =
            .authenticating

        do {

            let success =
                try await authentication
                    .authenticate(
                        reason:
                            "Authenticate to access protected application features."
                    )

            guard success else {

                state =
                    .unauthenticated

                throw
                    SecurityRuntimeError
                        .authenticationFailed
            }

            let now =
                Date()

            let newSession =
                SecureSession(
                    identifier:
                        try SecureRandom
                            .identifier(),
                    createdAt: now,
                    expiresAt:
                        now.addingTimeInterval(
                            sessionLifetime
                        )
                )

            session =
                newSession

            state =
                .authenticated

            return newSession

        } catch {

            state =
                .unauthenticated

            throw error
        }
    }

    public func validate()
        -> Bool
    {

        guard
            let session
        else {

            state =
                .unauthenticated

            return false
        }

        guard
            !session.isExpired
        else {

            self.session = nil
            state = .expired

            return false
        }

        state =
            .authenticated

        return true
    }

    public func lock() {

        session = nil
        state = .locked
    }

    public func logout() {

        session = nil
        state = .unauthenticated
    }

    public func currentState()
        -> SecureSessionState
    {
        state
    }
}

// MARK: - Sensitive Data Redactor

public enum SecurityRedactor {

    public static func redact(
        _ value: String,
        visibleCharacters: Int = 4
    ) -> String {

        guard
            value.count > visibleCharacters
        else {
            return "••••"
        }

        let suffix =
            String(
                value.suffix(
                    visibleCharacters
                )
            )

        return
            "••••••••\(suffix)"
    }

    public static func redact(
        _ data: Data
    ) -> String {

        "Data<\(data.count) bytes>"
    }

    public static func redact(
        _ url: URL
    ) -> String {

        guard
            var components =
                URLComponents(
                    url: url,
                    resolvingAgainstBaseURL:
                        false
                )
        else {
            return "<redacted-url>"
        }

        components.query = nil

        return
            components
                .url?
                .absoluteString
            ?? "<redacted-url>"
    }
}

