@MainActor
@Observable
public final class SecurityUIState {

    public private(set) var
        sessionState:
        SecureSessionState =
        .unauthenticated

    public private(set) var
        securityStatus:
        String =
        "Protected"

    public init() {}

    public func update(
        state:
            SecureSessionState
    ) {

        sessionState =
            state

        switch state {

        case .unauthenticated:
            securityStatus =
                "Authentication required"

        case .authenticating:
            securityStatus =
                "Authenticating"

        case .authenticated:
            securityStatus =
                "Authenticated"

        case .expired:
            securityStatus =
                "Session expired"

        case .locked:
            securityStatus =
                "Locked"
        }
    }
}

// MARK: - Security Runtime Controller

@MainActor
public final class EliteiPhoneSecurityRuntime:
    ObservableObject
{

    public static let shared =
        EliteiPhoneSecurityRuntime()

    public let runtime =
        SecurityPrivacyRuntime.shared

    public let state =
        SecurityUIState()

    private init() {}

    public func start() {

        Task {

            let current =
                await runtime.sessions
                    .currentState()

            await MainActor.run {

                state.update(
                    state: current
                )
            }
        }
    }

    public func authenticate() {

        Task {

            do {

                _ =
                    try await runtime
                    .sessions
                    .authenticate()

            } catch {

                // Deliberately do not expose
                // detailed authentication errors
                // directly to the UI.
            }

            let current =
                await runtime.sessions
                    .currentState()

            await MainActor.run {

                state.update(
                    state: current
                )
            }
        }
    }

    public func lock() {

        Task {

            await runtime.sessions.lock()

            let current =
                await runtime.sessions
                    .currentState()

            await MainActor.run {

                state.update(
                    state: current
                )
            }
        }
    }

    public func logout() {

        Task {

            await runtime.sessions.logout()

            let current =
                await runtime.sessions
                    .currentState()

            await MainActor.run {

                state.update(
                    state: current
                )
            }
        }
    }
}

