// MARK: - Model Loader

public actor CoreMLModelLoader {

    private var loadedModels:
        [String: MLModel] = [:]

    private let logger =
        Logger(
            subsystem:
                "EliteiPhoneRuntime",
            category:
                "MLModelLoader"
        )

    public init() {}

    public func load(
        descriptor:
            IntelligenceModelDescriptor,
        url:
            URL,
        policy:
            ModelExecutionPolicy
    ) async throws -> MLModel {

        if let cached =
            loadedModels[descriptor.id] {

            return cached
        }

        let configuration =
            MLModelConfiguration()

        configuration.computeUnits =
            policy.computeUnits

        let model =
            try await Task.detached(
                priority:
                    .userInitiated
            ) {

                try MLModel.load(
                    contentsOf:
                        url,
                    configuration:
                        configuration
                )
            }
            .value

        loadedModels[
            descriptor.id
        ] = model

        logger.info(
            "Loaded model \(descriptor.id, privacy: .public)"
        )

        return model
    }

    public func unload(
        modelID:
            String
    ) {

        loadedModels.removeValue(
            forKey:
                modelID
        )
    }

    public func unloadAll() {

        loadedModels.removeAll()
    }

    public func loadedModelIDs()
        -> [String]
    {
        Array(
            loadedModels.keys
        )
    }
}

// MARK: - Inference Clock

public actor InferenceClock {

    private let clock =
        ContinuousClock()

    private var lastExecution:
        ContinuousClock.Instant?

    public init() {}

    public func allow(
        frequency:
            Double
    ) -> Bool {

        guard frequency > 0 else {
            return false
        }

        let now =
            clock.now

        guard
            let lastExecution
        else {

            self.lastExecution =
                now

            return true
        }

        let elapsed =
            lastExecution.duration(
                to:
                    now
            )

        let elapsedSeconds =
            Double(
                elapsed.components.seconds
            )
            +
            Double(
                elapsed.components.attoseconds
            )
            /
            1_000_000_000_000_000_000

        let minimumInterval =
            1.0 / frequency

        guard
            elapsedSeconds
            >=
            minimumInterval
        else {
            return false
        }

        self.lastExecution =
            now

        return true
    }

    public func reset() {

        lastExecution = nil
    }
}

