// MARK: - Inference Semaphore

public actor AsyncPermitPool {

    private var available:
        Int

    private var waiters:
        [CheckedContinuation<Void, Never>] =
        []

    public init(
        permits:
            Int
    ) {

        self.available =
            max(
                1,
                permits
            )
    }

    public func acquire()
        async
    {

        if available > 0 {

            available -= 1
            return
        }

        await withCheckedContinuation {
            continuation in

            waiters.append(
                continuation
            )
        }
    }

    public func release() {

        if
            let continuation =
                waiters.first
        {

            waiters.removeFirst()

            continuation.resume()

        } else {

            available += 1
        }
    }
}

// MARK: - Intelligence Runtime Metrics

public struct IntelligenceMetrics:
    Sendable
{

    public private(set) var
        requests:
        UInt64 = 0

    public private(set) var
        completed:
        UInt64 = 0

    public private(set) var
        rejected:
        UInt64 = 0

    public private(set) var
        failures:
        UInt64 = 0

    public private(set) var
        lowConfidenceResults:
        UInt64 = 0

    public private(set) var
        totalInferenceTime:
        TimeInterval = 0

    public init() {}

    mutating func recordRequest() {
        requests += 1
    }

    mutating func recordCompletion(
        duration:
            TimeInterval
    ) {

        completed += 1
        totalInferenceTime +=
            duration
    }

    mutating func recordRejection() {
        rejected += 1
    }

    mutating func recordFailure() {
        failures += 1
    }

    mutating func recordLowConfidence() {
        lowConfidenceResults += 1
    }

    public var averageInferenceTime:
        TimeInterval
    {

        guard completed > 0 else {
            return 0
        }

        return
            totalInferenceTime
            /
            Double(completed)
    }
}

// MARK: - Intelligence Governor

public actor IntelligenceGovernor {

    private var profile:
        IntelligenceProfile =
        IntelligenceProfiles.balanced

    private var metrics =
        IntelligenceMetrics()

    private let clock =
        InferenceClock()

    public init() {}

    public func configure(
        profile:
            IntelligenceProfile
    ) {

        self.profile =
            profile
    }

    public func currentProfile()
        -> IntelligenceProfile
    {
        profile
    }

    public func shouldRun(
        workload:
            IntelligenceWorkload,
        priority:
            InferencePriority
    ) async -> Bool {

        if
            priority == .critical
        {
            return true
        }

        if
            priority == .background
            &&
            !profile
                .allowsBackgroundInference
        {
            metrics.recordRejection()
            return false
        }

        let allowed =
            await clock.allow(
                frequency:
                    profile
                    .maximumInferenceFrequency
            )

        if !allowed {

            metrics.recordRejection()
            return false
        }

        metrics.recordRequest()

        return true
    }

    public func validateConfidence(
        _ confidence:
            Double
    ) -> Bool {

        let valid =
            confidence
            >=
            profile.minimumConfidence

        if !valid {
            metrics.recordLowConfidence()
        }

        return valid
    }

    public func recordCompletion(
        duration:
            TimeInterval
    ) {

        metrics.recordCompletion(
            duration:
                duration
        )
    }

    public func recordFailure() {
        metrics.recordFailure()
    }

    public func snapshot()
        -> IntelligenceMetrics
    {
        metrics
    }
}

// MARK: - Generic Inference Engine

public actor LocalInferenceEngine {

    private let governor:
        IntelligenceGovernor

    private let permits:
        AsyncPermitPool

    private let logger =
        Logger(
            subsystem:
                "EliteiPhoneRuntime",
            category:
                "InferenceEngine"
        )

    public init(
        governor:
            IntelligenceGovernor =
            IntelligenceGovernor()
    ) {

        self.governor =
            governor

        self.permits =
            AsyncPermitPool(
                permits: 2
            )
    }

    public func configure(
        profile:
            IntelligenceProfile
    ) async {

        await governor.configure(
            profile:
                profile
        )
    }

    public func execute<Value: Sendable>(
        workload:
            IntelligenceWorkload,
        priority:
            InferencePriority,
        confidence:
            Double = 1.0,
        operation:
            @escaping @Sendable
            () async throws -> Value
    ) async throws
        -> InferenceResult<Value>
    {

        let allowed =
            await governor.shouldRun(
                workload:
                    workload,
                priority:
                    priority
            )

        guard allowed else {

            throw
                IntelligenceRuntimeError
                    .inferenceRejected
        }

        let profile =
            await governor.currentProfile()

        guard
            profile.maximumConcurrency
            > 0
        else {

            throw
                IntelligenceRuntimeError
                    .inferenceRejected
        }

        await permits.acquire()

        let start =
            ContinuousClock.now

        do {

            let value =
                try await operation()

            let duration =
                start.duration(
                    to:
                        ContinuousClock.now
                )

            let seconds =
                Double(
                    duration.components.seconds
                )
                +
                Double(
                    duration.components.attoseconds
                )
                /
                1_000_000_000_000_000_000

            await permits.release()

            await governor.recordCompletion(
                duration:
                    seconds
            )

            let accepted =
                await governor
                    .validateConfidence(
                        confidence
                    )

            guard accepted else {

                throw
                    IntelligenceRuntimeError
                        .lowConfidence
            }

            logger.debug(
                "Inference completed."
            )

            return InferenceResult(
                workload:
                    workload,
                value:
                    value,
                confidence:
                    confidence,
                duration:
                    seconds
            )

        } catch {

            await permits.release()

            await governor
                .recordFailure()

            throw error
        }
    }
}

