// MARK: - Vision Engine

public actor VisionInferenceEngine {

    private let inference:
        LocalInferenceEngine

    public init(
        inference:
            LocalInferenceEngine
            =
            LocalInferenceEngine()
    ) {

        self.inference =
            inference
    }

    public func detectObjects(
        request:
            VisionImageRequest,
        priority:
            InferencePriority =
            .userInitiated
    ) async throws
        -> InferenceResult<[DetectedObject]>
    {

        try await inference.execute(
            workload:
                .objectDetection,
            priority:
                priority
        ) {

            try await withCheckedThrowingContinuation {
                continuation in

                let request =
                    VNDetectRectanglesRequest {
                        request,
                        error in

                        if let error {

                            continuation.resume(
                                throwing:
                                    error
                            )

                            return
                        }

                        let results =
                            (
                                request.results
                                as? [
                                    VNRectangleObservation
                                ]
                            )
                            ?? []

                        let objects =
                            results.map {

                                DetectedObject(
                                    identifier:
                                        "rectangle",
                                    confidence:
                                        Double(
                                            $0.confidence
                                        ),
                                    boundingBox:
                                        $0.boundingBox
                                )
                            }

                        continuation.resume(
                            returning:
                                objects
                        )
                    }

                let handler =
                    VNImageRequestHandler(
                        cgImage:
                            request.image,
                        orientation:
                            request.orientation
                    )

                DispatchQueue.global(
                    qos:
                        .userInitiated
                ).async {

                    do {

                        try handler.perform(
                            [request]
                        )

                    } catch {

                        continuation.resume(
                            throwing:
                                error
                        )
                    }
                }
            }
        }
    }
}

// MARK: - ML Runtime Errors

public enum IntelligenceRuntimeError:
    Error,
    LocalizedError,
    Sendable
{

    case modelNotFound
    case modelLoadFailed
    case inferenceRejected
    case lowConfidence
    case invalidInput
    case inferenceFailed
    case memoryLimit
    case unsupportedWorkload

    public var errorDescription:
        String?
    {

        switch self {

        case .modelNotFound:
            return
                "The requested ML model was not found."

        case .modelLoadFailed:
            return
                "The ML model could not be loaded."

        case .inferenceRejected:
            return
                "The inference workload was rejected by the runtime governor."

        case .lowConfidence:
            return
                "The inference result did not meet the confidence threshold."

        case .invalidInput:
            return
                "The supplied inference input is invalid."

        case .inferenceFailed:
            return
                "The inference operation failed."

        case .memoryLimit:
            return
                "The intelligence runtime memory budget was exceeded."

        case .unsupportedWorkload:
            return
                "The requested intelligence workload is unsupported."
        }
    }
}

// MARK: - Model Memory Registry

public actor ModelMemoryRegistry {

    private struct ModelAllocation:
        Sendable
    {

        let identifier:
            String

        let bytes:
            Int64
    }

    private var allocations:
        [String: ModelAllocation] =
        [:]

    private let maximumBytes:
        Int64

    public init(
        maximumBytes:
            Int64 =
            512 * 1024 * 1024
    ) {

        self.maximumBytes =
            maximumBytes
    }

    public func reserve(
        model:
            IntelligenceModelDescriptor
    ) throws {

        let existing =
            allocations.values.reduce(
                0
            ) {
                $0 + $1.bytes
            }

        guard
            existing
            +
            model.estimatedMemoryBytes
            <=
            maximumBytes
        else {

            throw
                IntelligenceRuntimeError
                    .memoryLimit
        }

        allocations[
            model.id
        ] =
            ModelAllocation(
                identifier:
                    model.id,
                bytes:
                    model.estimatedMemoryBytes
            )
    }

    public func release(
        modelID:
            String
    ) {

        allocations.removeValue(
            forKey:
                modelID
        )
    }

    public func currentUsage()
        -> Int64
    {

        allocations.values.reduce(
            0
        ) {
            $0 + $1.bytes
        }
    }

    public func availableBytes()
        -> Int64
    {

        max(
            0,
            maximumBytes
            -
            currentUsage()
        )
    }
}

// MARK: - Intelligence Result Cache

public actor IntelligenceResultCache<Value: Sendable> {

    private struct Entry {
        let value:
            Value

        let createdAt:
            Date

        let expiresAt:
            Date?
    }

    private var entries:
        [String: Entry] =
        [:]

    public init() {}

    public func insert(
        key:
            String,
        value:
            Value,
        expiration:
            TimeInterval? =
            nil
    ) {

        let expiresAt =
            expiration.map {
                Date()
                    .addingTimeInterval(
                        $0
                    )
            }

        entries[key] =
            Entry(
                value:
                    value,
                createdAt:
                    Date(),
                expiresAt:
                    expiresAt
            )
    }

    public func value(
        forKey:
            String
    ) -> Value? {

        guard
            let entry =
                entries[
                    forKey
                ]
        else {
            return nil
        }

        if let expiresAt =
            entry.expiresAt,
            Date() >= expiresAt {

            entries.removeValue(
                forKey:
                    forKey
            )

            return nil
        }

        return entry.value
    }

    public func removeAll() {

        entries.removeAll()
    }
}

