// MARK: - Intelligence Controller

@MainActor
public final class EliteiPhoneIntelligenceRuntime:
    ObservableObject
{

    public static let shared =
        EliteiPhoneIntelligenceRuntime()

    public let runtime =
        OnDeviceIntelligenceRuntime.shared

    public let state =
        IntelligenceUIState()

    private init() {}

    public func start() {

        configure(
            profile:
                IntelligenceProfiles.balanced
        )
    }

    public func configure(
        profile:
            IntelligenceProfile
    ) {

        state.configure(
            mode:
                profile.mode
        )

        Task {

            await runtime.configure(
                profile:
                    profile
            )
        }
    }

    public func runLocalInference<Value: Sendable>(
        workload:
            IntelligenceWorkload,
        priority:
            InferencePriority,
        confidence:
            Double = 1.0,
        operation:
            @escaping @Sendable
            () async throws -> Value
    ) {

        Task {

            do {

                let result =
                    try await runtime
                    .inference
                    .execute(
                        workload:
                            workload,
                        priority:
                            priority,
                        confidence:
                            confidence,
                        operation:
                            operation
                    )

                await MainActor.run {

                    state.record(
                        result
                    )
                }

            } catch {

                await MainActor.run {

                    state.recordFailure()
                }
            }
        }
    }
}

