public final class MicrophoneHardwareSource:
NSObject,
@unchecked Sendable
{
public let subsystem: HardwareSubsystem = .microphone

```
private let audioEngine = AVAudioEngine()

private let lock = NSLock()

private var continuation:
    AsyncStream<HardwareEvent<AudioLevelSample>>.Continuation?

private var running = false

public override init() {
    super.init()
}

public func availability() -> HardwareAvailability {
    switch AVCaptureDevice.authorizationStatus(for: .audio) {
    case .authorized:
        return .available

    case .notDetermined:
        return .permissionRequired

    case .denied, .restricted:
        return .restricted

    @unknown default:
        return .unavailable
    }
}

public func requestPermission() async -> Bool {
    await AVCaptureDevice.requestAccess(for: .audio)
}

public func start() async throws {

    guard availability() == .available else {
        throw HardwareRuntimeError.permissionRequired(.microphone)
    }

    let audioSession = AVAudioSession.sharedInstance()

    try audioSession.setCategory(
        .record,
        mode: .measurement,
        options: []
    )

    try audioSession.setActive(true)

    let input = audioEngine.inputNode

    let format = input.inputFormat(
        forBus: 0
    )

    input.installTap(
        onBus: 0,
        bufferSize: 1_024,
        format: format
    ) { [weak self] buffer, _ in

        guard let self else { return }

        guard let channelData = buffer.floatChannelData?[0] else {
            return
        }

        let frameCount = Int(buffer.frameLength)

        guard frameCount > 0 else {
            return
        }

        var sumSquares = 0.0
        var peak = 0.0

        for index in 0..<frameCount {

            let sample = Double(channelData[index])

            sumSquares += sample * sample
            peak = max(peak, abs(sample))
        }

        let rms = sqrt(
            sumSquares / Double(frameCount)
        )

        let level = AudioLevelSample(
            rms: rms,
            peak: peak
        )

        self.lock.lock()

        self.continuation?.yield(
            HardwareEvent(value: level)
        )

        self.lock.unlock()
    }

    try audioEngine.start()

    lock.lock()
    running = true
    lock.unlock()
}

public func stop() async {

    audioEngine.inputNode.removeTap(onBus: 0)
    audioEngine.stop()

    try? AVAudioSession.sharedInstance().setActive(
        false,
        options: .notifyOthersOnDeactivation
    )

    lock.lock()

    continuation?.finish()
    continuation = nil
    running = false

    lock.unlock()
}

public func stream()
    -> AsyncStream<HardwareEvent<AudioLevelSample>>
{
    AsyncStream { continuation in
        self.lock.lock()
        self.continuation = continuation
        self.lock.unlock()
    }
}
```

}

