// ============================================================
// HAPTICS
// ============================================================

public enum HapticPattern: Sendable {
case click
case success
case warning
case failure
}

public actor HapticHardwareSource {

```
public let subsystem: HardwareSubsystem = .haptics

private var engine: CHHapticEngine?

public init() {}

public func availability() -> HardwareAvailability {

    guard CHHapticEngine.capabilitiesForHardware()
        .supportsHaptics
    else {
        return .unavailable
    }

    return .available
}

public func start() async throws {

    guard await availability() == .available else {
        throw HardwareRuntimeError.unavailable(.haptics)
    }

    let engine = try CHHapticEngine()

    try engine.start()

    self.engine = engine
}

public func stop() async {

    engine?.stop(completionHandler: nil)
    engine = nil
}

public func play(
    _ pattern: HapticPattern
) async throws {

    guard let engine else {
        throw HardwareRuntimeError.notRunning(.haptics)
    }

    let intensity: Float
    let sharpness: Float
    let duration: TimeInterval

    switch pattern {
    case .click:
        intensity = 0.7
        sharpness = 0.7
        duration = 0.05

    case .success:
        intensity = 0.8
        sharpness = 0.6
        duration = 0.12

    case .warning:
        intensity = 0.9
        sharpness = 0.4
        duration = 0.18

    case .failure:
        intensity = 1.0
        sharpness = 0.9
        duration = 0.25
    }

    let intensityParameter = CHHapticEventParameter(
        parameterID: .hapticIntensity,
        value: intensity
    )

    let sharpnessParameter = CHHapticEventParameter(
        parameterID: .hapticSharpness,
        value: sharpness
    )

    let event = CHHapticEvent(
        eventType: .hapticTransient,
        parameters: [
            intensityParameter,
            sharpnessParameter
        ],
        relativeTime: 0
    )

    let pattern = try CHHapticPattern(
        events: [event],
        parameters: []
    )

    let player = try engine.makePlayer(
        with: pattern
    )

    try player.start(atTime: 0)

    _ = duration
}
```

}

