import SwiftUI

public struct HardwareStatusView: View {

```
@State private var runtime =
    EliteiPhoneHardwareRuntime()

public init() {}

public var body: some View {

    List {

        Section("Hardware Runtime") {

            ForEach(
                HardwareSubsystem.allCases,
                id: \.self
            ) { subsystem in

                let state =
                    runtime.snapshot.states[subsystem]

                HStack {

                    VStack(
                        alignment: .leading,
                        spacing: 4
                    ) {

                        Text(
                            subsystem.rawValue
                                .capitalized
                        )
                        .font(.headline)

                        if let state {

                            Text(
                                state.availability.rawValue
                            )
                            .font(.caption)
                            .foregroundStyle(.secondary)
                        }
                    }

                    Spacer()

                    if state?.active == true {
                        Image(
                            systemName: "circle.fill"
                        )
                        .foregroundStyle(.green)
                    } else {
                        Image(
                            systemName: "circle"
                        )
                        .foregroundStyle(.secondary)
                    }
                }
            }
        }

        Section("Runtime") {

            Text(
                "Active subsystems: " +
                "\(runtime.snapshot.activeSubsystemCount)"
            )

            Text(
                "Events: " +
                "\(runtime.metrics.eventsReceived)"
            )

            Text(
                "Dropped: " +
                "\(runtime.metrics.droppedEvents)"
            )
        }
    }
    .task {
        await runtime.start()
    }
    .refreshable {
        await runtime.refresh()
    }
}
```

}

