                    )
                }

                Section("Subsystems") {

                    ForEach(
                        RuntimeSubsystem.allCases,
                        id: \.self
                    ) { subsystem in

                        if let record =
                            snapshot.subsystemHealth[
                                subsystem
                            ]
                        {

                            HStack {

                                Text(
                                    subsystem.rawValue
                                        .capitalized
                                )

                                Spacer()

                                Text(
                                    record.health.rawValue
                                )
                                .foregroundStyle(
                                    healthColor(
                                        record.health
                                    )
                                )
                            }
                        }
                    }
                }

                Section("Diagnostics") {

                    statusRow(
                        title: "Boots",
                        value:
                            "\(snapshot.metrics.bootCount)"
                    )

                    statusRow(
                        title: "Heartbeats",
                        value:
                            "\(snapshot.metrics.heartbeatCount)"
                    )

                    statusRow(
                        title: "Recoverable faults",
                        value:
                            "\(snapshot.metrics.recoverableFaultCount)"
                    )

                    statusRow(
                        title: "Critical faults",
                        value:
                            "\(snapshot.metrics.criticalFaultCount)"
                    )
                }

            } else {

                ProgressView(
                    "Starting runtime…"
                )
            }
        }
        .navigationTitle(
            "iPhone Runtime"
        )
    }
    .task {
        model.start()
    }
    .onDisappear {
        model.stop()
    }
}

@ViewBuilder
private func statusRow(
    title: String,
    value: String
) -> some View {

    HStack {
        Text(title)
        Spacer()
        Text(value)
            .foregroundStyle(.secondary)
    }
}

private func healthColor(
    _ health: SubsystemHealth
) -> Color {

    switch health {

    case .healthy:
        return .green

    case .degraded:
        return .orange

    case .failed:
        return .red

    case .unavailable:
        return .secondary

    case .unknown:
        return .secondary
    }
}
```

}

