// ============================================================
// PROCESS MEMORY READER
// ============================================================
//
// Uses task-level resident memory information where available.
//
// The runtime treats these values as diagnostics rather than
// as an authoritative replacement for Instruments/Xcode.
//
// ============================================================

public struct ProcessMemoryReader:
Sendable
{

```
public init() {}

public func snapshot()
    -> MemoryUsageSnapshot
{

    var info =
        mach_task_basic_info()

    var count =
        mach_msg_type_number_t(
            MemoryLayout<mach_task_basic_info>.size
            / MemoryLayout<natural_t>.size
        )

    let result = withUnsafeMutablePointer(
        to: &info
    ) {

        $0.withMemoryRebound(
            to: integer_t.self,
            capacity: Int(count)
        ) {

            task_info(
                mach_task_self_,
                task_flavor_t(
                    MACH_TASK_BASIC_INFO
                ),
                $0,
                &count
            )
        }
    }

    guard result == KERN_SUCCESS else {

        return MemoryUsageSnapshot(
            residentBytes: 0,
            footprintBytes: 0
        )
    }

    return MemoryUsageSnapshot(
        residentBytes:
            UInt64(info.resident_size),

        footprintBytes:
            UInt64(info.resident_size)
    )
}
```

}

// ============================================================
// BOUNDED LRU CACHE
// ============================================================

public actor MemoryBoundedCache<Key: Hashable & Sendable,
Value: Sendable>
{

```
private struct Entry:
    Sendable
{
    let value: Value
    let cost: Int64
    let insertedAt: Date
    var lastAccess: Date
}

private var storage:
    [Key: Entry] = [:]

private var currentCost: Int64 = 0

private let maximumCost: Int64

public init(
    maximumCost: Int64
) {
    self.maximumCost =
        max(0, maximumCost)
}

public func value(
    for key: Key
) -> Value? {

    guard var entry = storage[key]
    else {
        return nil
    }

    entry.lastAccess = .now

    storage[key] = entry

    return entry.value
}

public func insert(
    _ value: Value,
    for key: Key,
    cost: Int64
) {

    let safeCost = max(0, cost)

    if let existing = storage[key] {
        currentCost -= existing.cost
    }

    storage[key] = Entry(
        value: value,
        cost: safeCost,
        insertedAt: .now,
        lastAccess: .now
    )

    currentCost += safeCost

    evictIfNecessary()
}

public func remove(
    for key: Key
) {

    guard let entry = storage.removeValue(
        forKey: key
    ) else {
        return
    }

    currentCost -= entry.cost
}

public func removeAll() {

    storage.removeAll(
        keepingCapacity: true
    )

    currentCost = 0
}

public func trim(
    toCost limit: Int64
) {

    let target = max(0, limit)

    while currentCost > target,
          !storage.isEmpty
    {

        evictLeastRecentlyUsed()
    }
}

public func cost() -> Int64 {
    currentCost
}

public func count() -> Int {
    storage.count
}

private func evictIfNecessary() {

    while currentCost > maximumCost,
          !storage.isEmpty
    {
        evictLeastRecentlyUsed()
    }
}

private func evictLeastRecentlyUsed() {

    guard let key =
        storage.min(
            by: {
                $0.value.lastAccess <
                $1.value.lastAccess
            }
        )?.key
    else {
        return
    }

    remove(for: key)
}
```

}

