// ============================================================
// MEMORY PRESSURE MONITOR
// ============================================================

public actor MemoryPressureMonitor {

```
private var level:
    MemoryPressureLevel = .normal

private var monitoringTask:
    Task<Void, Never>?

private let reader:
    ProcessMemoryReader

private var latest:
    MemoryUsageSnapshot =
        MemoryUsageSnapshot(
            residentBytes: 0,
            footprintBytes: 0
        )

public init(
    reader: ProcessMemoryReader =
        ProcessMemoryReader()
) {
    self.reader = reader
}

public func start() {

    guard monitoringTask == nil else {
        return
    }

    monitoringTask = Task {

        while !Task.isCancelled {

            await sample()

            try? await Task.sleep(
                for: .seconds(2)
            )
        }
    }
}

public func stop() {

    monitoringTask?.cancel()
    monitoringTask = nil
}

private func sample() {

    latest =
        reader.snapshot()

    // iOS does not expose a universal public
    // "remaining application RAM" value.
    //
    // Therefore this monitor does not invent one.
    //
    // Actual pressure transitions are supplied through
    // UIApplication memory-warning notifications and
    // application-level policies.

}

public func reportWarning() {
    level = .warning
}

public func reportCritical() {
    level = .critical
}

public func reportNormal() {
    level = .normal
}

public func pressure()
    -> MemoryPressureLevel
{
    level
}

public func usage()
    -> MemoryUsageSnapshot
{
    latest
}
```

}

// ============================================================
// MEMORY PRESSURE NOTIFICATION BRIDGE
// ============================================================

@MainActor
public final class MemoryPressureNotificationBridge {

```
private var observer:
    NSObjectProtocol?

private let warning:
    @Sendable () async -> Void

public init(
    warning:
        @escaping @Sendable () async -> Void
) {

    self.warning = warning

    observer =
        NotificationCenter.default.addObserver(
            forName:
                UIApplication.didReceiveMemoryWarningNotification,
            object: nil,
            queue: .main
        ) { _ in

            Task {
                await warning()
            }
        }
}

deinit {

    if let observer {
        NotificationCenter.default.removeObserver(
            observer
        )
    }
}
```

}

