}
```

}

public actor MemoryWorkloadGovernor {

```
private var pressure:
    MemoryPressureLevel = .normal

private var budgets:
    [MemoryWorkload: MemoryBudget] = [:]

public init() {

    configureDefaults()
}

private func configureDefaults() {

    budgets[.userInterface] =
        MemoryBudget(
            workload: .userInterface,
            softLimit: 128 * 1024 * 1024,
            hardLimit: 256 * 1024 * 1024
        )

    budgets[.imageProcessing] =
        MemoryBudget(
            workload: .imageProcessing,
            softLimit: 256 * 1024 * 1024,
            hardLimit: 512 * 1024 * 1024
        )

    budgets[.videoProcessing] =
        MemoryBudget(
            workload: .videoProcessing,
            softLimit: 384 * 1024 * 1024,
            hardLimit: 768 * 1024 * 1024
        )

    budgets[.machineLearning] =
        MemoryBudget(
            workload: .machineLearning,
            softLimit: 512 * 1024 * 1024,
            hardLimit: 1024 * 1024 * 1024
        )

    budgets[.networking] =
        MemoryBudget(
            workload: .networking,
            softLimit: 64 * 1024 * 1024,
            hardLimit: 128 * 1024 * 1024
        )

    budgets[.database] =
        MemoryBudget(
            workload: .database,
            softLimit: 128 * 1024 * 1024,
            hardLimit: 256 * 1024 * 1024
        )

    budgets[.hardware] =
        MemoryBudget(
            workload: .hardware,
            softLimit: 128 * 1024 * 1024,
            hardLimit: 256 * 1024 * 1024
        )

    budgets[.analytics] =
        MemoryBudget(
            workload: .analytics,
            softLimit: 64 * 1024 * 1024,
            hardLimit: 128 * 1024 * 1024
        )

    budgets[.caching] =
        MemoryBudget(
            workload: .caching,
            softLimit: 256 * 1024 * 1024,
            hardLimit: 512 * 1024 * 1024
        )

    budgets[.diagnostics] =
        MemoryBudget(
            workload: .diagnostics,
            softLimit: 32 * 1024 * 1024,
            hardLimit: 64 * 1024 * 1024
        )
}

public func updatePressure(
    _ pressure: MemoryPressureLevel
) {
    self.pressure = pressure
}

public func decision(
    for request: MemoryWorkloadRequest
) -> MemoryWorkloadDecision {

    let budget =
        budgets[request.workload]

    switch pressure {

    case .normal:

        if let budget,
           request.estimatedBytes >
           budget.hardLimit
        {
            return MemoryWorkloadDecision(
                decision: .throttle,
                reason:
                    "Estimated allocation exceeds workload budget."
            )
        }

        return MemoryWorkloadDecision(
            decision: .run,
            reason: "Normal memory pressure."
        )

    case .warning:

        if request.priority >= 4 {
            return MemoryWorkloadDecision(
                decision: .runWithReducedCache,
                reason:
                    "Critical workload under memory warning."
            )
        }

        if request.estimatedBytes > 128 * 1024 * 1024 {
            return MemoryWorkloadDecision(
                decision: .throttle,
                reason:
                    "Large allocation under memory warning."
            )
        }

        return MemoryWorkloadDecision(
            decision: .runWithReducedCache,
            reason:
                "Memory pressure warning."
        )

    case .critical:

        if request.priority >= 4 &&
           request.estimatedBytes <
           64 * 1024 * 1024
        {
            return MemoryWorkloadDecision(
                decision: .run,
                reason:
                    "Small critical workload."
            )
        }

        if request.priority >= 3 {
            return MemoryWorkloadDecision(
                decision: .defer,
                reason:
                    "High memory pressure."
            )
        }

        return MemoryWorkloadDecision(
            decision: .reject,
            reason:
                "Memory pressure critical."
        )
    }
}
```

}

// ============================================================
// ALLOCATION REGISTRY
// ============================================================
//
// This is an application accounting system.
//
// It does NOT intercept every malloc() performed by iOS.
//
// ============================================================

public actor MemoryAllocationRegistry {

```
private var allocations:
    [UUID: MemoryAllocationRecord] = [:]

private var maximumRecords = 5_000

public init() {}

public func register(
    label: String,
    category: MemoryAllocationClass,
    estimatedBytes: Int64,
    owner: String? = nil
) -> UUID {

    let record =
        MemoryAllocationRecord(
            label: label,
            category: category,
            estimatedBytes:
                max(0, estimatedBytes),
            owner: owner
        )

    allocations[record.id] = record

    trimIfNecessary()

    return record.id
}

public func unregister(
    _ id: UUID
) {
    allocations.removeValue(
        forKey: id
    )
}

public func snapshot()
    -> [MemoryAllocationRecord]
{
    Array(allocations.values)
}

public func totalEstimatedBytes()
    -> Int64
{
    allocations.values.reduce(
        into: Int64(0)
    ) {
        $0 += $1.estimatedBytes
    }
}

public func byCategory()
    -> [MemoryAllocationClass: Int64]
{

    var result:
        [MemoryAllocationClass: Int64] = [:]

    for record in allocations.values {

        result[record.category, default: 0] +=
            record.estimatedBytes
    }

    return result
}

private func trimIfNecessary() {

    guard allocations.count >
            maximumRecords
    else {
        return
    }

    let excess =
        allocations.count -
        maximumRecords

    let oldest =
        allocations.values
            .sorted {
                $0.createdAt <
                $1.createdAt
            }
            .prefix(excess)

    for record in oldest {
        allocations.removeValue(
            forKey: record.id
        )
    }
}
```

}

// ============================================================
// MEMORY LEASE
// ============================================================
//
// Useful for large temporary workloads:
//
// let lease = await memory.acquire(...)
//
// defer {
//     Task {
//         await lease.release()
//     }
// }
//
// ============================================================

public struct MemoryLease:
Sendable
{

```
public let id: UUID

public let workload:
    MemoryWorkload

public let bytes:
    Int64
```

}

public actor MemoryLeaseManager {

```
private struct ActiveLease:
    Sendable
{
    let lease:
        MemoryLease

    let createdAt:
        Date
}

private var leases:
    [UUID: ActiveLease] = [:]

private let governor:
    MemoryWorkloadGovernor

public init(
    governor:
        MemoryWorkloadGovernor
) {
    self.governor = governor
}

public func acquire(
    workload: MemoryWorkload,
    bytes: Int64,
    priority: Int
) async -> MemoryLease?
{

    let request =
        MemoryWorkloadRequest(
            workload: workload,
            estimatedBytes: bytes,
            priority: priority
        )

    let decision =
        await governor.decision(
            for: request
        )

    switch decision.decision {

    case .run,
         .runWithReducedCache:

        let lease =
            MemoryLease(
                id: UUID(),
                workload: workload,
                bytes: max(0, bytes)
            )

        leases[lease.id] =
            ActiveLease(
                lease: lease,
                createdAt: .now
            )

        return lease

    case .throttle,
         .defer,
         .reject:

        return nil
    }
}

public func release(
    _ lease: MemoryLease
) {
    leases.removeValue(
        forKey: lease.id
    )
}

public func activeBytes()
    -> Int64
{
    leases.values.reduce(
        into: Int64(0)
    ) {
        $0 += $1.lease.bytes
    }
}
```

}

// ============================================================
// IMAGE CACHE
// ============================================================

public actor ImageMemoryCache {

```
private let cache:
    MemoryBoundedCache<String, Data>

public init(
    maximumBytes:
        Int64 = 128 * 1024 * 1024
) {
    cache =
        MemoryBoundedCache(
            maximumCost: maximumBytes
        )
}

public func insert(
    imageData: Data,
    key: String
) async {

    await cache.insert(
        imageData,
        for: key,
        cost: Int64(imageData.count)
    )
}

public func image(
    for key: String
) async -> Data? {

    await cache.value(
        for: key
    )
}

public func trim(
    aggressively: Bool
) async {

    if aggressively {

        await cache.trim(
            toCost: 16 * 1024 * 1024
        )

    } else {

        await cache.trim(
            toCost: 64 * 1024 * 1024
        )
    }
}

public func clear() async {
    await cache.removeAll()
}
```

}

// ============================================================
// MODEL MEMORY REGISTRY
// ============================================================

public struct ModelMemoryEntry:
Sendable,
Codable
{

```
public let identifier:
    String

public let estimatedBytes:
    Int64

public let loadedAt:
    Date

public init(
    identifier: String,
    estimatedBytes: Int64,
    loadedAt: Date = .now
) {
    self.identifier = identifier
    self.estimatedBytes =
        estimatedBytes
    self.loadedAt = loadedAt
}
```

}

public actor ModelMemoryRegistry {

```
private var models:
    [String: ModelMemoryEntry] = [:]

public init() {}

public func register(
    identifier: String,
    estimatedBytes: Int64
) {

    models[identifier] =
        ModelMemoryEntry(
            identifier: identifier,
            estimatedBytes:
                max(0, estimatedBytes)
        )
}

public func unregister(
    identifier: String
) {
    models.removeValue(
        forKey: identifier
    )
}

public func unloadLargest(
    maximumModels: Int
) {

    guard maximumModels >= 0 else {
        return
    }

    let sorted =
        models.values.sorted {
            $0.estimatedBytes >
            $1.estimatedBytes
        }

    let removeCount =
        max(
            0,
            sorted.count - maximumModels
        )

    for model in sorted.prefix(removeCount) {

        models.removeValue(
            forKey: model.identifier
        )
    }
}

public func snapshot()
    -> [ModelMemoryEntry]
{
    Array(models.values)
}

public func totalEstimatedBytes()
    -> Int64
{
    models.values.reduce(
        into: Int64(0)
    ) {
        $0 += $1.estimatedBytes
    }
}
```

}

