public actor MemoryDiagnosticsEngine {

```
private let pressureMonitor:
    MemoryPressureMonitor

private let registry:
    MemoryAllocationRegistry

private let leases:
    MemoryLeaseManager

private let models:
    ModelMemoryRegistry

public init(
    pressureMonitor:
        MemoryPressureMonitor,
    registry:
        MemoryAllocationRegistry,
    leases:
        MemoryLeaseManager,
    models:
        ModelMemoryRegistry
) {

    self.pressureMonitor =
        pressureMonitor

    self.registry =
        registry

    self.leases =
        leases

    self.models =
        models
}

public func snapshot()
    async -> MemoryDiagnosticsSnapshot
{

    MemoryDiagnosticsSnapshot(
        pressure:
            await pressureMonitor.pressure(),

        processMemory:
            await pressureMonitor.usage(),

        estimatedRegisteredBytes:
            await registry.totalEstimatedBytes(),

        activeLeaseBytes:
            await leases.activeBytes(),

        modelBytes:
            await models.totalEstimatedBytes()
    )
}
```

}

// ============================================================
// ADVANCED MEMORY RUNTIME
// ============================================================

public actor AdvancedMemoryRuntime {

```
public static let shared =
    AdvancedMemoryRuntime()

public let pressureMonitor:
    MemoryPressureMonitor

public let governor:
    MemoryWorkloadGovernor

public let allocations:
    MemoryAllocationRegistry

public let models:
    ModelMemoryRegistry

public let imageCache:
    ImageMemoryCache

private let leases:
    MemoryLeaseManager

public let diagnostics:
    MemoryDiagnosticsEngine

private var running = false

public init() {

    let pressure =
        MemoryPressureMonitor()

    let governor =
        MemoryWorkloadGovernor()

    let allocations =
        MemoryAllocationRegistry()

    let models =
        ModelMemoryRegistry()

    let leases =
        MemoryLeaseManager(
            governor: governor
        )

    self.pressureMonitor =
        pressure

    self.governor =
        governor

    self.allocations =
        allocations

    self.models =
        models

    self.imageCache =
        ImageMemoryCache()

    self.leases =
        leases

    self.diagnostics =
        MemoryDiagnosticsEngine(
            pressureMonitor: pressure,
            registry: allocations,
            leases: leases,
            models: models
        )
}

public func start() async {

    guard !running else {
        return
    }

    running = true

    await pressureMonitor.start()

    Logger.memory.info(
        "Advanced memory runtime started."
    )
}

public func stop() async {

    guard running else {
        return
    }

    await pressureMonitor.stop()

    await imageCache.clear()

    running = false

    Logger.memory.info(
        "Advanced memory runtime stopped."
    )
}

public func handleMemoryWarning()
    async
{

    await pressureMonitor.reportWarning()

    // First-stage reclamation.
    await imageCache.trim(
        aggressively: false
    )

    // Keep fewer resident models.
    await models.unloadLargest(
        maximumModels: 1
    )

    await governor.updatePressure(
        .warning
    )
}

public func handleCriticalMemoryPressure()
    async
{

    await pressureMonitor.reportCritical()

    // Aggressive application-owned cache reduction.
    await imageCache.trim(
        aggressively: true
    )

    await models.unloadLargest(
        maximumModels: 0
    )

    await governor.updatePressure(
        .critical
    )
}

public func handleNormalMemoryState()
    async
{

    await pressureMonitor.reportNormal()

    await governor.updatePressure(
        .normal
    )
}

public func acquire(
    workload: MemoryWorkload,
    bytes: Int64,
    priority: Int
) async -> MemoryLease?
{

    await leases.acquire(
        workload: workload,
        bytes: bytes,
        priority: priority
    )
}

public func release(
    _ lease: MemoryLease
) async {

    await leases.release(
        lease
    )
}

public func snapshot()
    async -> MemoryDiagnosticsSnapshot
{
    await diagnostics.snapshot()
}
```

}

