// MEMORY RUNTIME ADAPTER FOR #10
// ============================================================

public actor MemoryRuntimeAdapter:
RuntimeSubsystemAdapter
{

```
public let subsystem:
    RuntimeSubsystem = .memory

private let runtime:
    AdvancedMemoryRuntime

private var running = false

public init(
    runtime:
        AdvancedMemoryRuntime =
        .shared
) {
    self.runtime = runtime
}

public func start() async throws {

    await runtime.start()

    running = true
}

public func stop() async {

    await runtime.stop()

    running = false
}

public func healthCheck()
    async -> SubsystemHealth
{

    guard running else {
        return .unavailable
    }

    let snapshot =
        await runtime.snapshot()

    switch snapshot.pressure {

    case .normal:
        return .healthy

    case .warning:
        return .degraded

    case .critical:
        return .degraded
    }
}
```

}

