@MainActor
@Observable
public final class MemoryRuntimeViewModel {

```
public private(set) var snapshot:
    MemoryDiagnosticsSnapshot?

private let runtime:
    AdvancedMemoryRuntime

private var task:
    Task<Void, Never>?

public init(
    runtime:
        AdvancedMemoryRuntime =
        .shared
) {
    self.runtime = runtime
}

public func start() {

    task?.cancel()

    task = Task {

        while !Task.isCancelled {

            snapshot =
                await runtime.snapshot()

            try? await Task.sleep(
                for: .seconds(2)
            )
        }
    }
}

public func stop() {

    task?.cancel()
    task = nil
}
```

}

