@ViewBuilder
private func row(
    _ title: String,
    _ value: String
) -> some View {

    HStack {
        Text(title)
        Spacer()
        Text(value)
            .foregroundStyle(.secondary)
    }
}

private func formatBytes(
    _ bytes: UInt64
) -> String {

    ByteCountFormatter.string(
        fromByteCount:
            Int64(
                min(
                    bytes,
                    UInt64(Int64.max)
                )
            ),
        countStyle: .memory
    )
}
