// ============================================================
// MEMORY-AWARE TASK GATE
// ============================================================

public actor MemoryAwareTaskGate {

```
private let runtime:
    AdvancedMemoryRuntime

public init(
    runtime:
        AdvancedMemoryRuntime =
        .shared
) {
    self.runtime = runtime
}

public func run<Value: Sendable>(
    workload: MemoryWorkload,
    estimatedBytes: Int64,
    priority: Int,
    operation:
        @escaping @Sendable () async throws -> Value
) async throws -> Value {

    guard let lease =
        await runtime.acquire(
            workload: workload,
            bytes: estimatedBytes,
            priority: priority
        )
    else {
        throw HardwareRuntimeError
            .configurationFailed(
                .camera,
                "Memory workload rejected."
            )
    }

    defer {
        Task {
            await runtime.release(
                lease
            )
        }
    }

    return try await operation()
}
```

}

