```
public let id:
    UUID

public let workload:
    GPUWorkload

public let pipeline:
    String

public let submittedAt:
    Date

public let completedAt:
    Date

public let durationMilliseconds:
    Double

public let successful:
    Bool

public init(
    id: UUID = UUID(),
    workload: GPUWorkload,
    pipeline: String,
    submittedAt: Date,
    completedAt: Date,
    successful: Bool
) {

    self.id = id
    self.workload = workload
    self.pipeline = pipeline
    self.submittedAt = submittedAt
    self.completedAt = completedAt

    self.durationMilliseconds =
        completedAt.timeIntervalSince(
            submittedAt
        ) * 1000

    self.successful =
        successful
}
```

}

public struct GPUMetrics:
Sendable,
Codable
{

```
public private(set) var submitted:
    UInt64 = 0

public private(set) var completed:
    UInt64 = 0

public private(set) var failed:
    UInt64 = 0

public private(set) var totalGPUTimeMilliseconds:
    Double = 0

public private(set) var peakEstimatedBufferBytes:
    Int64 = 0

public mutating func recordSubmission() {
    submitted += 1
}

public mutating func recordCompletion(
    milliseconds: Double
) {

    completed += 1

    totalGPUTimeMilliseconds +=
        max(0, milliseconds)
}

public mutating func recordFailure() {
    failed += 1
}

public mutating func recordBufferBytes(
    _ bytes: Int64
) {

    peakEstimatedBufferBytes =
        max(
            peakEstimatedBufferBytes,
            bytes
        )
}
```

}

// ============================================================
// GPU PERMIT POOL
// ============================================================

public actor GPUPermitPool {

```
private var available:
    Int

private var waiters:
    [CheckedContinuation<Void, Never>] = []

public init(
    permits: Int
) {
    self.available =
        max(1, permits)
}

public func acquire() async {

    if available > 0 {

        available -= 1
        return
    }

    await withCheckedContinuation {
        continuation in

        waiters.append(
            continuation
        )
    }
}

public func release() {

    if let continuation =
        waiters.first
    {

        waiters.removeFirst()

        continuation.resume()

    } else {

        available += 1
    }
}

public func resize(
    to permits: Int
) {

    let target =
        max(1, permits)

    let waiting =
        min(
            waiters.count,
            max(
                0,
                target - available
            )
        )

    if waiting > 0 {

        for _ in 0..<waiting {

            let continuation =
                waiters.removeFirst()

            continuation.resume()
        }
    }

    available =
        max(
            0,
            target - waiters.count
        )
}
```

}

// ============================================================
// METAL PIPELINE REGISTRY
// ============================================================
//
// All MTL objects stay inside the Metal actor.
// Only Sendable descriptors cross the actor boundary.
//
// ============================================================

public actor MetalPipelineRegistry {

```
private let device:
    MTLDevice

private let library:
    MTLLibrary

private var pipelines:
    [ComputePipelineDescriptor:
        MTLComputePipelineState] = [:]

public init(
    device: MTLDevice,
    library: MTLLibrary
) {

    self.device =
        device

    self.library =
        library
}

public func pipeline(
    for descriptor:
        ComputePipelineDescriptor
) throws
    -> MTLComputePipelineState
{

    if let existing =
        pipelines[descriptor]
    {
        return existing
    }

    guard let function =
        library.makeFunction(
            name:
                descriptor.functionName
        )
    else {
        throw GPURuntimeError
            .functionNotFound(
                descriptor.functionName
            )
    }

    do {

        let pipeline =
            try device.makeComputePipelineState(
                function: function
            )

        pipelines[descriptor] =
            pipeline

        return pipeline

    } catch {

        throw GPURuntimeError
            .pipelineCreationFailed(
                descriptor.functionName
            )
    }
}

public func remove(
    _ descriptor:
        ComputePipelineDescriptor
) {
    pipelines.removeValue(
        forKey: descriptor
    )
}

public func clear() {
    pipelines.removeAll(
        keepingCapacity: true
    )
}

public func count() -> Int {
    pipelines.count
}
```

}

// ============================================================
// GPU BUFFER POOL
// ============================================================

public actor GPUBufferPool {

```
private let device:
    MTLDevice

private var buffers:
    [Int: [MTLBuffer]] = [:]

private var estimatedBytes:
    Int64 = 0

public init(
    device: MTLDevice
) {
    self.device =
        device
}

public func acquire(
    length: Int,
    options:
        MTLResourceOptions = []
) throws -> MTLBuffer {

    let size =
        max(1, length)

    if var bucket =
        buffers[size],
       !bucket.isEmpty
    {

        let buffer =
            bucket.removeLast()

        buffers[size] =
            bucket

        return buffer
    }

    guard let buffer =
        device.makeBuffer(
            length: size,
            options: options
        )
    else {
        throw GPURuntimeError
            .bufferCreationFailed
    }

    estimatedBytes +=
        Int64(size)

    return buffer
}

public func recycle(
    _ buffer: MTLBuffer
) {

    let size =
        buffer.length

    buffers[size, default: []]
        .append(buffer)
}

public func trim() {

    buffers.removeAll(
        keepingCapacity: true
    )

    estimatedBytes = 0
}

public func memoryEstimate()
    -> Int64
{
    estimatedBytes
}
```

}

// ============================================================
// GPU TEXTURE POOL
// ============================================================

public actor GPUTexturePool {

```
private let device:
    MTLDevice

private struct Key:
    Hashable,
    Sendable
{
    let width:
        Int

    let height:
        Int

    let pixelFormat:
        UInt64

    let usage:
        UInt64
}

private var textures:
    [Key: [MTLTexture]] = [:]

public init(
    device: MTLDevice
) {
    self.device =
        device
}

public func acquire(
    descriptor:
        GPUTextureDescriptor
) throws -> MTLTexture {

    let key =
        Key(
            width:
                descriptor.width,
            height:
                descriptor.height,
            pixelFormat:
                UInt64(
                    descriptor.pixelFormat.rawValue
                ),
            usage:
                UInt64(
                    descriptor.usage.rawValue
                )
        )

    if var bucket =
        textures[key],
       !bucket.isEmpty
    {

        let texture =
            bucket.removeLast()

        textures[key] =
            bucket

        return texture
    }

    let metalDescriptor =
        MTLTextureDescriptor.texture2DDescriptor(
            pixelFormat:
                descriptor.pixelFormat,
            width:
                descriptor.width,
            height:
                descriptor.height,
            mipmapped:
                false
        )

    metalDescriptor.usage =
        descriptor.usage

    guard let texture =
        device.makeTexture(
            descriptor:
                metalDescriptor
        )
    else {
        throw GPURuntimeError
            .textureCreationFailed
    }

    return texture
}

public func recycle(
    _ texture: MTLTexture,
    descriptor:
        GPUTextureDescriptor
) {

    let key =
        Key(
            width:
                descriptor.width,
            height:
                descriptor.height,
            pixelFormat:
                UInt64(
                    descriptor.pixelFormat.rawValue
                ),
            usage:
                UInt64(
                    descriptor.usage.rawValue
                )
        )

    textures[key, default: []]
        .append(texture)
}

public func trim() {

    textures.removeAll(
        keepingCapacity: true
    )
}
```

}

// ============================================================
// COMMAND BUFFER COMPLETION
// ============================================================

private final class CommandCompletionBox:
@unchecked Sendable
{

```
private let lock =
    NSLock()

private var finished =
    false

private var continuation:
    CheckedContinuation<Void, Error>?

init(
    continuation:
        CheckedContinuation<Void, Error>
) {
    self.continuation =
        continuation
}

func complete(
    error:
        Error?
) {

    lock.lock()
    defer {
        lock.unlock()
    }

    guard !finished else {
        return
    }

    finished = true

    let continuation =
        self.continuation

    self.continuation = nil

    if let error {

        continuation?.resume(
            throwing: error
        )

    } else {

        continuation?.resume()
    }
}
```

}

// ============================================================
// GPU COMMAND EXECUTOR
// ============================================================

public actor MetalCommandExecutor {

```
private let device:
    MTLDevice

private let commandQueue:
    MTLCommandQueue

private let pipelines:
    MetalPipelineRegistry

public init(
    device: MTLDevice,
    commandQueue:
        MTLCommandQueue,
    pipelines:
        MetalPipelineRegistry
) {

    self.device =
        device

    self.commandQueue =
        commandQueue

    self.pipelines =
        pipelines
}

public func execute(
    descriptor:
        ComputePipelineDescriptor,
    dispatch:
        GPUDispatch,
    configure:
        @escaping @Sendable (
            MTLComputeCommandEncoder
        ) throws -> Void
) async throws {

    guard
        dispatch.threadsPerGrid.width > 0,
        dispatch.threadsPerGrid.height > 0,
        dispatch.threadsPerGrid.depth > 0
    else {
        throw GPURuntimeError
            .invalidDispatch
    }

    let pipeline =
        try await pipelines.pipeline(
            for: descriptor
        )

    guard let commandBuffer =
        commandQueue.makeCommandBuffer()
    else {
        throw GPURuntimeError
            .commandBufferCreationFailed
    }

    guard let encoder =
        commandBuffer.makeComputeCommandEncoder()
    else {
        throw GPURuntimeError
            .commandEncoderCreationFailed
    }

    encoder.setComputePipelineState(
        pipeline
    )

    try configure(
        encoder
    )

    encoder.dispatchThreads(
        dispatch.threadsPerGrid,
        threadsPerThreadgroup:
            dispatch.threadsPerThreadgroup
    )

    encoder.endEncoding()

    try await withCheckedThrowingContinuation {
        continuation in

        let box =
            CommandCompletionBox(
                continuation:
                    continuation
            )

        commandBuffer.addCompletedHandler {
            buffer in

            if let error =
                buffer.error
            {
                box.complete(
                    error: error
                )
            } else {
                box.complete(
                    error: nil
                )
            }
        }

        commandBuffer.commit()
    }
}
```

}

// ============================================================
// GPU WORKLOAD GOVERNOR
// ============================================================

public actor GPUWorkloadGovernor {

```
private var policy:
    GPUExecutionPolicy =
        GPUExecutionPolicies.balanced

public init() {}

public func setPolicy(
    _ policy:
        GPUExecutionPolicy
) {
    self.policy =
        policy
}

public func currentPolicy()
    -> GPUExecutionPolicy
{
    policy
}

public func decision(
    workload:
        GPUWorkload,
    priority:
        GPUWorkloadPriority,
    estimatedBufferBytes:
        Int64
) -> Bool {

    if estimatedBufferBytes >
       policy.maximumBufferBytes
    {
        return false
    }

    if priority ==
        .background &&
       !policy.allowBackgroundWork
    {
        return false
    }

    if workload ==
        .machineLearning &&
       !policy.allowLargePipelines
    {
        // Balanced/efficiency modes can still run ML,
        // but should use smaller model/pipeline variants.
        return estimatedBufferBytes <
            policy.maximumBufferBytes / 2
    }

    return true
}
```

}

// ============================================================
// GPU RUNTIME
// ============================================================

public actor MetalGPURuntime {

```
public static let shared =
    MetalGPURuntime()

public let device:
    MTLDevice

public let deviceInformation:
    GPUDeviceInformation

private let commandQueue:
    MTLCommandQueue

public let pipelines:
    MetalPipelineRegistry

public let buffers:
    GPUBufferPool

public let textures:
    GPUTexturePool

public let governor:
    GPUWorkloadGovernor

private let permits:
    GPUPermitPool

private let executor:
    MetalCommandExecutor

private var metrics:
    GPUMetrics = GPUMetrics()

private var running =
    false

private init() {

    guard let device =
        MTLCreateSystemDefaultDevice()
    else {

        fatalError(
            "Metal is unavailable on this device."
        )
    }

    guard let queue =
        device.makeCommandQueue()
    else {

        fatalError(
            "Could not create Metal command queue."
        )
    }

    guard let library =
        device.makeDefaultLibrary()
    else {

        fatalError(
            "Could not create default Metal library."
        )
    }

    self.device =
        device

    self.deviceInformation =
        GPUDeviceInformation(
            device: device
        )

    self.commandQueue =
        queue

    let pipelines =
        MetalPipelineRegistry(
            device: device,
            library: library
        )

    self.pipelines =
        pipelines

    self.buffers =
        GPUBufferPool(
            device: device
        )

    self.textures =
        GPUTexturePool(
            device: device
        )

    self.governor =
        GPUWorkloadGovernor()

    self.permits =
        GPUPermitPool(
            permits: 2
        )

    self.executor =
        MetalCommandExecutor(
            device: device,
            commandQueue: queue,
            pipelines: pipelines
        )
}

public func start() async {

    guard !running else {
        return
    }

    running = true

    Logger.gpu.info(
        "Metal GPU runtime started on \(self.device.name, privacy: .public)."
    )
}

public func stop() async {

    guard running else {
        return
    }

    await buffers.trim()
    await textures.trim()
    await pipelines.clear()

    running = false

    Logger.gpu.info(
        "Metal GPU runtime stopped."
    )
}

public func setPolicy(
    _ policy:
        GPUExecutionPolicy
) async {

    await governor.setPolicy(
        policy
    )

    await permits.resize(
        to:
            policy.maximumConcurrentWorkloads
    )
}

public func execute(
    workload:
        GPUWorkload,
    priority:
        GPUWorkloadPriority,
    estimatedBufferBytes:
        Int64,
    pipeline:
        ComputePipelineDescriptor,
    dispatch:
        GPUDispatch,
    configure:
        @escaping @Sendable (
            MTLComputeCommandEncoder
        ) throws -> Void
) async throws {

    let allowed =
        await governor.decision(
            workload:
                workload,
            priority:
                priority,
            estimatedBufferBytes:
                estimatedBufferBytes
        )

    guard allowed else {

        throw GPURuntimeError
            .workloadRejected(
                "Execution policy denied workload."
            )
    }

    await permits.acquire()

    defer {

        Task {
            await permits.release()
        }
    }

    let id =
        UUID()

    let start =
        Date()

    metrics.recordSubmission()

    do {

        try await executor.execute(
            descriptor:
                pipeline,
            dispatch:
                dispatch,
            configure:
                configure
        )

        let end =
            Date()

        let milliseconds =
            end.timeIntervalSince(
                start
            ) * 1000

        metrics.recordCompletion(
            milliseconds:
                milliseconds
        )

        Logger.gpu.debug(
            "GPU workload completed: \(id.uuidString, privacy: .public), \(milliseconds, privacy: .public) ms"
        )

    } catch {

        metrics.recordFailure()

        Logger.gpu.error(
            "GPU workload failed: \(id.uuidString, privacy: .public)"
        )

        throw error
    }
}

public func makeBuffer(
    length:
        Int,
    options:
        MTLResourceOptions = []
) async throws -> MTLBuffer {

    try await buffers.acquire(
        length:
            length,
        options:
            options
    )
}

public func recycleBuffer(
    _ buffer:
        MTLBuffer
) async {

    await buffers.recycle(
        buffer
    )
}

public func makeTexture(
    descriptor:
        GPUTextureDescriptor
) async throws -> MTLTexture {

    try await textures.acquire(
        descriptor:
            descriptor
    )
}

public func recycleTexture(
    _ texture:
        MTLTexture,
    descriptor:
        GPUTextureDescriptor
) async {

    await textures.recycle(
        texture,
        descriptor:
            descriptor
    )
}

public func trimMemory() async {

    await buffers.trim()
    await textures.trim()
    await pipelines.clear()
}

public func currentMetrics()
    -> GPUMetrics
{
    metrics
}

public func bufferMemoryEstimate()
    async -> Int64
{
    await buffers.memoryEstimate()
}
```

}

// ============================================================
// GPU / POWER BRIDGE
// ============================================================

public actor GPUPowerPolicyBridge {

```
private let runtime:
    MetalGPURuntime

public init(
    runtime:
        MetalGPURuntime =
        .shared
) {
    self.runtime =
        runtime
}

public func apply(
    mode:
        GPUExecutionMode
) async {

    let policy:
        GPUExecutionPolicy

    switch mode {

    case .maximumPerformance:
        policy =
            GPUExecutionPolicies.maximum

    case .performance:
        policy =
            GPUExecutionPolicies.performance

    case .balanced:
        policy =
            GPUExecutionPolicies.balanced

    case .efficiency:
        policy =
            GPUExecutionPolicies.efficiency

    case .emergency:
        policy =
            GPUExecutionPolicies.emergency
    }

    await runtime.setPolicy(
        policy
    )
}
```

}

