// MARK: - Camera Position

public enum CameraPosition:
String,
Sendable,
Codable
{
case front
case back
}

// MARK: - Capture Quality

public enum CaptureQuality:
String,
Sendable,
Codable
{
case preview
case standard
case high
case maximum
}

// MARK: - Imaging Workload

public enum ImagingWorkload:
String,
Sendable,
Codable,
CaseIterable
{
case preview
case photo
case hdr
case raw
case video
case computerVision
case machineLearning
case thumbnail
case export
case editing
}

// MARK: - Image Processing Mode

public enum ImageProcessingMode:
String,
Sendable,
Codable
{
case passthrough
case preview
case balanced
case highQuality
case maximumQuality
}

// MARK: - Image Orientation

public enum ImageOrientation:
Int,
Sendable,
Codable
{
case up = 1
case down = 3
case left = 8
case right = 6
}

