public struct ImageFrameMetadata:
Sendable,
Codable
{

```
public let timestamp:
    Date

public let width:
    Int

public let height:
    Int

public let pixelFormat:
    UInt32

public let position:
    CameraPosition

public let orientation:
    ImageOrientation

public let isHDR:
    Bool

public let estimatedBytes:
    Int64

public init(
    timestamp: Date = .now,
    width: Int,
    height: Int,
    pixelFormat: UInt32,
    position: CameraPosition,
    orientation: ImageOrientation = .up,
    isHDR: Bool = false,
    estimatedBytes: Int64
) {

    self.timestamp = timestamp
    self.width = width
    self.height = height
    self.pixelFormat = pixelFormat
    self.position = position
    self.orientation = orientation
    self.isHDR = isHDR
    self.estimatedBytes = estimatedBytes
}
```

}

