// ============================================================
// CAMERA ERROR
// ============================================================

public enum ImagingRuntimeError:
Error,
LocalizedError,
Sendable
{

```
case cameraUnavailable
case permissionDenied
case configurationFailed(String)
case captureSessionFailed
case noVideoOutput
case invalidPixelBuffer
case imageCreationFailed
case imageEncodingFailed
case processingFailed(String)
case memoryRejected
case unsupportedFormat
case cancelled

public var errorDescription:
    String?
{

    switch self {

    case .cameraUnavailable:
        return "Camera is unavailable."

    case .permissionDenied:
        return "Camera permission was denied."

    case .configurationFailed(let reason):
        return "Camera configuration failed: \(reason)"

    case .captureSessionFailed:
        return "Camera capture session failed."

    case .noVideoOutput:
        return "Camera video output is unavailable."

    case .invalidPixelBuffer:
        return "Invalid camera pixel buffer."

    case .imageCreationFailed:
        return "Could not create image."

    case .imageEncodingFailed:
        return "Could not encode image."

    case .processingFailed(let reason):
        return "Image processing failed: \(reason)"

    case .memoryRejected:
        return "Image workload rejected by memory policy."

    case .unsupportedFormat:
        return "Unsupported image format."

    case .cancelled:
        return "Image operation cancelled."
    }
}
```

}

