// ============================================================
// CAMERA DEVICE DISCOVERY
// ============================================================

public struct CameraDeviceDescriptor:
Sendable
{

```
public let position:
    CameraPosition

public let deviceType:
    String

public let localizedName:
    String

public init(
    position: CameraPosition,
    deviceType: String,
    localizedName: String
) {
    self.position = position
    self.deviceType = deviceType
    self.localizedName = localizedName
}
```

}

public actor CameraDeviceManager {

```
public init() {}

public func availableCameras()
    -> [CameraDeviceDescriptor]
{

    let discovery =
        AVCaptureDevice.DiscoverySession(
            deviceTypes: [
                .builtInWideAngleCamera,
                .builtInUltraWideCamera,
                .builtInTelephotoCamera
            ],
            mediaType: .video,
            position: .unspecified
        )

    return discovery.devices.map {

        CameraDeviceDescriptor(
            position:
                $0.position == .front
                ? .front
                : .back,

            deviceType:
                $0.deviceType.rawValue,

            localizedName:
                $0.localizedName
        )
    }
}

public func device(
    position:
        CameraPosition
) -> AVCaptureDevice?
{

    let avPosition:
        AVCaptureDevice.Position =
            position == .front
            ? .front
            : .back

    let discovery =
        AVCaptureDevice.DiscoverySession(
            deviceTypes: [
                .builtInWideAngleCamera,
                .builtInUltraWideCamera,
                .builtInTelephotoCamera
            ],
            mediaType: .video,
            position: avPosition
        )

    return discovery.devices.first
}
```

}

// ============================================================
// CAMERA CAPTURE RUNTIME
// ============================================================
//
// AVCaptureSession and outputs are deliberately isolated from
// the rest of the application.
//
// The capture queue performs minimal work.
//
// ============================================================

public actor CameraCaptureRuntime {

```
private let session:
    AVCaptureSession

private let sessionQueue:
    DispatchQueue

private var videoOutput:
    AVCaptureVideoDataOutput?

private var running =
    false

private var configuration:
    CameraConfiguration

private var frameContinuation:
    AsyncStream<CapturedFrame>.Continuation?

private var frameStream:
    AsyncStream<CapturedFrame>?

public init(
    configuration:
        CameraConfiguration =
        CameraConfiguration()
) {

    self.configuration =
        configuration

    self.session =
        AVCaptureSession()

    self.sessionQueue =
        DispatchQueue(
            label:
                "com.eliteiphone.imaging.capture",
            qos:
                .userInitiated
        )
}

public func start() async throws {

    guard
        AVCaptureDevice.authorizationStatus(
            for: .video
        ) == .authorized
    else {
        throw ImagingRuntimeError.permissionDenied
    }

    guard let device =
        await CameraDeviceManager()
            .device(
                position:
                    configuration.position
            )
    else {
        throw ImagingRuntimeError.cameraUnavailable
    }

    try await configure(
        device:
            device
    )

    sessionQueue.async {
        self.session.startRunning()
    }

    running = true
}

public func stop() {

    sessionQueue.async {
        self.session.stopRunning()
    }

    frameContinuation?.finish()
    frameContinuation = nil
    frameStream = nil

    running = false
}

private func configure(
    device:
        AVCaptureDevice
) async throws {

    try await withCheckedThrowingContinuation {
        continuation in

        sessionQueue.async {

            do {

                self.session.beginConfiguration()

                defer {
                    self.session.commitConfiguration()
                }

                self.session.sessionPreset =
                    self.capturePreset()

                for input
                in self.session.inputs
                {
                    self.session.removeInput(
                        input
                    )
                }

                let input =
                    try AVCaptureDeviceInput(
                        device:
                            device
                    )

                guard self.session.canAddInput(
                    input
                ) else {

                    continuation.resume(
                        throwing:
                            ImagingRuntimeError
                                .configurationFailed(
                                    "Cannot add camera input."
                                )
                    )

                    return
                }

                self.session.addInput(
                    input
                )

                let output =
                    AVCaptureVideoDataOutput()

                output.videoSettings = [
                    kCVPixelBufferPixelFormatTypeKey
                        as String:
                        self.configuration.pixelFormat
                ]

                output.alwaysDiscardsLateVideoFrames =
                    true

                guard self.session.canAddOutput(
                    output
                ) else {

                    continuation.resume(
                        throwing:
                            ImagingRuntimeError
                                .noVideoOutput
                    )

                    return
                }

                self.session.addOutput(
                    output
                )

                if let connection =
                    output.connection(
                        with:
                            .video
                    ) {

                        if self.configuration
                            .enableVideoStabilization,
                           connection.isVideoStabilizationSupported
                        {
                            connection.preferredVideoStabilizationMode =
                                .auto
                        }
                    }

                self.videoOutput =
                    output

                continuation.resume()

            } catch {

                continuation.resume(
                    throwing:
                        ImagingRuntimeError
                            .configurationFailed(
                                error.localizedDescription
                            )
                )
            }
        }
    }
}

private func capturePreset()
    -> AVCaptureSession.Preset
{

    switch configuration.quality {

    case .preview:
        return .medium

    case .standard:
        return .high

    case .high:
        return .high

    case .maximum:
        return .photo
    }
}

public func frames()
    -> AsyncStream<CapturedFrame>
{

    if let frameStream {
        return frameStream
    }

    let stream =
        AsyncStream<CapturedFrame>(
            bufferingPolicy:
                .bufferingNewest(2)
        ) {
            continuation in

            self.frameContinuation =
                continuation
        }

    frameStream =
        stream

    return stream
}

public func isRunning()
    -> Bool
{
    running
}
```

}

