// ============================================================
// PIXEL BUFFER CONVERSION
// ============================================================

public struct PixelBufferConverter:
Sendable
{

```
public init() {}

public func copy(
    _ pixelBuffer:
        CVPixelBuffer
) throws -> ImageData {

    CVPixelBufferLockBaseAddress(
        pixelBuffer,
        .readOnly
    )

    defer {
        CVPixelBufferUnlockBaseAddress(
            pixelBuffer,
            .readOnly
        )
    }

    guard let baseAddress =
        CVPixelBufferGetBaseAddress(
            pixelBuffer
        )
    else {
        throw ImagingRuntimeError
            .invalidPixelBuffer
    }

    let width =
        CVPixelBufferGetWidth(
            pixelBuffer
        )

    let height =
        CVPixelBufferGetHeight(
            pixelBuffer
        )

    let bytesPerRow =
        CVPixelBufferGetBytesPerRow(
            pixelBuffer
        )

    let byteCount =
        bytesPerRow * height

    let data =
        Data(
            bytes:
                baseAddress,
            count:
                byteCount
        )

    return ImageData(
        bytes:
            data,
        width:
            width,
        height:
            height,
        bytesPerRow:
            bytesPerRow,
        pixelFormat:
            CVPixelBufferGetPixelFormatType(
                pixelBuffer
            )
    )
}
```

}

// ============================================================
// CORE IMAGE PIPELINE
// ============================================================

public actor CoreImagePipeline {

```
private let context:
    CIContext

public init(
    device:
        MTLDevice? =
        MTLCreateSystemDefaultDevice()
) {

    if let device {

        context =
            CIContext(
                mtlDevice:
                    device
            )

    } else {

        context =
            CIContext()
    }
}

public func makeImage(
    from data:
        ImageData
) throws -> CIImage {

    let colorSpace =
        CGColorSpaceCreateDeviceRGB()

    guard let provider =
        CGDataProvider(
            data:
                data.bytes as CFData
        )
    else {
        throw ImagingRuntimeError
            .imageCreationFailed
    }

    guard let cgImage =
        CGImage(
            width:
                data.width,
            height:
                data.height,
            bitsPerComponent:
                8,
            bitsPerPixel:
                32,
            bytesPerRow:
                data.bytesPerRow,
            space:
                colorSpace,
            bitmapInfo:
                CGBitmapInfo(
                    rawValue:
                        CGImageAlphaInfo
                            .premultipliedFirst
                            .rawValue
                ),
            provider:
                provider,
            decode:
                nil,
            shouldInterpolate:
                false,
            intent:
                .defaultIntent
        )
    else {
        throw ImagingRuntimeError
            .imageCreationFailed
    }

    return CIImage(
        cgImage:
            cgImage
    )
}

public func resize(
    _ image:
        CIImage,
    width:
        Int,
    height:
        Int
) -> CIImage {

    let targetWidth =
        max(1, width)

    let targetHeight =
        max(1, height)

    let scaleX =
        CGFloat(targetWidth) /
        image.extent.width

    let scaleY =
        CGFloat(targetHeight) /
        image.extent.height

    return image.transformed(
        by:
            CGAffineTransform(
                scaleX:
                    scaleX,
                y:
                    scaleY
            )
    )
}

public func crop(
    _ image:
        CIImage,
    to rect:
        CGRect
) -> CIImage {

    image.cropped(
        to:
            rect
    )
}

public func applyExposure(
    _ image:
        CIImage,
    value:
        Float
) -> CIImage {

    let filter =
        CIFilter.exposureAdjust()

    filter.inputImage =
        image

    filter.ev =
        value

    return filter.outputImage ??
        image
}

public func applyColorControls(
    _ image:
        CIImage,
    saturation:
        Float,
    brightness:
        Float,
    contrast:
        Float
) -> CIImage {

    let filter =
        CIFilter.colorControls()

    filter.inputImage =
        image

    filter.saturation =
        saturation

    filter.brightness =
        brightness

    filter.contrast =
        contrast

    return filter.outputImage ??
        image
}

public func encodeJPEG(
    _ image:
        CIImage,
    quality:
        CGFloat = 0.9
) throws -> Data {

    guard let data =
        context.jpegRepresentation(
            of:
                image,
            colorSpace:
                CGColorSpaceCreateDeviceRGB(),
            options: [
                CIImageRepresentationOption
                    .lossyCompressionQuality:
                    quality
            ]
        )
    else {
        throw ImagingRuntimeError
            .imageEncodingFailed
    }

    return data
}

public func encodeHEIF(
    _ image:
        CIImage,
    quality:
        CGFloat = 0.9
) throws -> Data {

    guard let data =
        context.heifRepresentation(
            of:
                image,
            format:
                .RGBA8,
            colorSpace:
                CGColorSpaceCreateDeviceRGB(),
            options: [
                CIImageRepresentationOption
                    .lossyCompressionQuality:
                    quality
            ]
        )
    else {
        throw ImagingRuntimeError
            .imageEncodingFailed
    }

    return data
}
```

}

// ============================================================
// IMAGE DOWNSAMPLER
// ============================================================

public struct ImageDownsampler:
Sendable
{

```
public init() {}

public func downsample(
    data:
        Data,
    maximumPixelSize:
        Int
) -> Data? {

    let sourceOptions:
        [CFString: Any] = [
            kCGImageSourceShouldCache:
                false
        ]

    guard let source =
        CGImageSourceCreateWithData(
            data as CFData,
            sourceOptions as CFDictionary
        )
    else {
        return nil
    }

    let destinationData =
        NSMutableData()

    guard let destination =
        CGImageDestinationCreateWithData(
            destinationData,
            UTType.jpeg.identifier as CFString,
            1,
            nil
        )
    else {
        return nil
    }

    let options:
        [CFString: Any] = [

            kCGImageSourceCreateThumbnailFromImageAlways:
                true,

            kCGImageSourceThumbnailMaxPixelSize:
                maximumPixelSize,

            kCGImageSourceCreateThumbnailWithTransform:
                true,

            kCGImageDestinationLossyCompressionQuality:
                0.88
        ]

    guard let image =
        CGImageSourceCreateThumbnailAtIndex(
            source,
            0,
            options as CFDictionary
        )
    else {
        return nil
    }

    CGImageDestinationAddImage(
        destination,
        image,
        options as CFDictionary
    )

    guard
        CGImageDestinationFinalize(
            destination
        )
    else {
        return nil
    }

    return destinationData as Data
}
```

}

