// ============================================================
// IMAGE CACHE ADAPTER
// ============================================================
//
// Uses #11's bounded memory cache.
//
// ============================================================

public actor ImagingCache {

```
private let cache:
    MemoryBoundedCache<String, Data>

public init(
    maximumBytes:
        Int64 =
        128 * 1024 * 1024
) {

    cache =
        MemoryBoundedCache(
            maximumCost:
                maximumBytes
        )
}

public func image(
    for key:
        String
) async -> Data? {

    await cache.value(
        for:
            key
    )
}

public func insert(
    data:
        Data,
    key:
        String
) async {

    await cache.insert(
        data,
        for:
            key,
        cost:
            Int64(data.count)
    )
}

public func trim(
    to:
        Int64
) async {

    await cache.trim(
        toCost:
            to
    )
}

public func clear() async {

    await cache.removeAll()
}
```

}

// ============================================================
// IMAGE PIPELINE
// ============================================================

public actor ImageProcessingRuntime {

```
private let coreImage:
    CoreImagePipeline

private let cache:
    ImagingCache

private let memory:
    AdvancedMemoryRuntime

public init(
    coreImage:
        CoreImagePipeline =
        CoreImagePipeline(),
    cache:
        ImagingCache =
        ImagingCache(),
    memory:
        AdvancedMemoryRuntime =
        .shared
) {

    self.coreImage =
        coreImage

    self.cache =
        cache

    self.memory =
        memory
}

public func process(
    data:
        ImageData,
    request:
        ImageProcessingRequest
) async throws -> Data {

    let estimatedBytes =
        Int64(
            max(
                1,
                data.width *
                data.height *
                4
            )
        )

    guard let lease =
        await memory.acquire(
            workload:
                .imageProcessing,
            bytes:
                estimatedBytes,
            priority:
                request.workload == .preview
                ? 2
                : 3
        )
    else {

        throw ImagingRuntimeError
            .memoryRejected
    }

    defer {

        Task {
            await memory.release(
                lease
            )
        }
    }

    if Task.isCancelled {
        throw ImagingRuntimeError.cancelled
    }

    let image =
        try await coreImage.makeImage(
            from:
                data
        )

    var result =
        image

    if let width =
        request.targetWidth,
       let height =
        request.targetHeight
    {

        result =
            await coreImage.resize(
                result,
                width:
                    width,
                height:
                    height
            )
    }

    switch request.mode {

    case .passthrough:
        break

    case .preview:

        result =
            await coreImage.applyColorControls(
                result,
                saturation:
                    1.0,
                brightness:
                    0,
                contrast:
                    1.0
            )

    case .balanced:

        result =
            await coreImage.applyColorControls(
                result,
                saturation:
                    1.03,
                brightness:
                    0,
                contrast:
                    1.02
            )

    case .highQuality,
         .maximumQuality:

        result =
            await coreImage.applyColorControls(
                result,
                saturation:
                    1.05,
                brightness:
                    0,
                contrast:
                    1.04
            )
    }

    let encoded =
        try await coreImage.encodeHEIF(
            result
        )

    return encoded
}

public func cachedProcess(
    key:
        String,
    data:
        ImageData,
    request:
        ImageProcessingRequest
) async throws -> Data {

    if let cached =
        await cache.image(
            for:
                key
        )
    {
        return cached
    }

    let result =
        try await process(
            data:
                data,
            request:
                request
        )

    await cache.insert(
        data:
            result,
        key:
            key
    )

    return result
}

public func trimCache() async {

    await cache.trim(
        to:
            32 * 1024 * 1024
    )
}

public func clearCache() async {

    await cache.clear()
}
```

}

