public struct ImagingMetrics:
Sendable,
Codable
{

```
public private(set) var framesReceived:
    UInt64 = 0

public private(set) var framesDropped:
    UInt64 = 0

public private(set) var imagesProcessed:
    UInt64 = 0

public private(set) var processingFailures:
    UInt64 = 0

public private(set) var totalProcessingMilliseconds:
    Double = 0

public private(set) var peakInputBytes:
    Int64 = 0

public mutating func recordFrame() {
    framesReceived += 1
}

public mutating func recordDrop() {
    framesDropped += 1
}

public mutating func recordProcessed(
    milliseconds:
        Double
) {

    imagesProcessed += 1

    totalProcessingMilliseconds +=
        max(
            0,
            milliseconds
        )
}

public mutating func recordFailure() {
    processingFailures += 1
}

public mutating func recordInputBytes(
    _ bytes:
        Int64
) {

    peakInputBytes =
        max(
            peakInputBytes,
            bytes
        )
}
```

}

