public actor AdvancedImagingRuntime {

```
public static let shared =
    AdvancedImagingRuntime()

public let camera:
    CameraCaptureRuntime

public let processor:
    ImageProcessingRuntime

public let governor:
    ImagingWorkloadGovernor

public let permission:
    CameraPermissionManager

public let devices:
    CameraDeviceManager

private var metrics =
    ImagingMetrics()

private var running =
    false

public init(
    configuration:
        CameraConfiguration =
        CameraConfiguration()
) {

    self.camera =
        CameraCaptureRuntime(
            configuration:
                configuration
        )

    self.processor =
        ImageProcessingRuntime()

    self.governor =
        ImagingWorkloadGovernor()

    self.permission =
        CameraPermissionManager()

    self.devices =
        CameraDeviceManager()
}

public func start() async throws {

    guard !running else {
        return
    }

    let status =
        await permission.authorizationStatus()

    if status == .notDetermined {

        let granted =
            await permission.requestAccess()

        guard granted else {
            throw ImagingRuntimeError
                .permissionDenied
        }

    } else if status != .authorized {

        throw ImagingRuntimeError
            .permissionDenied
    }

    await camera.start()

    running = true

    Logger.imaging.info(
        "Advanced imaging runtime started."
    )
}

public func stop() {

    camera.stop()

    running = false

    Logger.imaging.info(
        "Advanced imaging runtime stopped."
    )
}

public func frames()
    -> AsyncStream<CapturedFrame>
{
    camera.frames()
}

public func process(
    data:
        ImageData,
    request:
        ImageProcessingRequest
) async throws -> Data {

    let start =
        Date()

    metrics.recordFrame()

    metrics.recordInputBytes(
        Int64(data.bytes.count)
    )

    do {

        let result =
            try await processor.process(
                data:
                    data,
                request:
                    request
            )

        metrics.recordProcessed(
            milliseconds:
                Date()
                .timeIntervalSince(start)
                * 1000
        )

        return result

    } catch {

        metrics.recordFailure()

        throw error
    }
}

public func trimMemory() async {

    await processor.trimCache()

    await AdvancedMemoryRuntime
        .shared
        .snapshot()
}

public func currentMetrics()
    -> ImagingMetrics
{
    metrics
}
```

}

