@MainActor
@Observable
public final class ImagingRuntimeViewModel {

```
public private(set) var status:
    CameraRuntimeStatus?

private let runtime:
    AdvancedImagingRuntime

private var task:
    Task<Void, Never>?

public init(
    runtime:
        AdvancedImagingRuntime =
        .shared
) {
    self.runtime =
        runtime
}

public func start() {

    task?.cancel()

    task = Task {

        while !Task.isCancelled {

            status =
                CameraRuntimeStatus(
                    running:
                        await runtime.camera
                            .isRunning(),

                    permission:
                        await runtime.permission
                            .authorizationStatus(),

                    metrics:
                        await runtime.currentMetrics()
                )

            try? await Task.sleep(
                for:
                    .seconds(1)
            )
        }
    }
}

public func stop() {

    task?.cancel()
    task = nil
}
```

}

