# 13. Route Change Handling

```swift
public actor AudioRouteMonitor {

    private let session = AVAudioSession.sharedInstance()

    private var continuation:
        AsyncStream<AudioRouteDescriptor>.Continuation?

    private var observer: NSObjectProtocol?

    public init() {}

    public func start()
        -> AsyncStream<AudioRouteDescriptor>
    {
        AsyncStream { continuation in

            self.continuation = continuation

            self.observer =
                NotificationCenter.default.addObserver(
                    forName:
                        AVAudioSession.routeChangeNotification,
                    object: self.session,
                    queue: nil
                ) { [weak self] _ in

                    Task {
                        await self?.publishRoute()
                    }
                }
        }
    }

    public func stop() {

        if let observer {
            NotificationCenter.default.removeObserver(
                observer
            )
        }

        observer = nil
        continuation?.finish()
        continuation = nil
    }

    private func publishRoute() {

        let output = session.currentRoute.outputs.first
        let input = session.currentRoute.inputs.first

        let descriptor = AudioRouteDescriptor(
            route: Self.mapRoute(output?.portType),
            name: output?.portName ?? "Unknown",
            sampleRate: session.sampleRate,
            inputChannels: input?.numberOfChannels ?? 0,
            outputChannels: output?.numberOfChannels ?? 0
        )

        continuation?.yield(descriptor)
    }

    private static func mapRoute(
        _ type: AVAudioSession.Port?
    ) -> AudioRoute {

        switch type {
        case .builtInSpeaker:
            return .speaker

        case .builtInReceiver:
            return .receiver

        case .headphones,
             .headsetMic:
            return .wiredHeadphones

        case .bluetoothA2DP,
             .bluetoothHFP,
             .bluetoothLE:
            return .bluetooth

        case .airPlay:
            return .airPlay

        case .usbAudio:
            return .usb

        case .carAudio:
            return .carAudio

        default:
            return .unknown
        }
    }
}
```

