# 19. Master Audio Runtime

```swift
public actor AudioRuntime {

    public static let shared = AudioRuntime()

    private let permissions =
        AudioPermissionManager()

    private let session =
        AudioSessionManager()

    private let governor =
        AudioWorkloadGovernor()

    private let engineController:
        AudioEngineController

    private let recorder =
        AudioRecordingController()

    private var configuration:
        AudioEngineConfiguration

    private var state:
        AudioRuntimeState = .stopped

    private var metrics =
        AudioMetrics()

    private var currentLevel =
        AudioLevel(rms: 0, peak: 0)

    private init() {

        configuration =
            AudioEngineConfiguration()

        engineController =
            AudioEngineController(
                configuration: configuration
            )
    }

    public func start() async throws {

        state = .starting

        if configuration.mode == .recording ||
           configuration.mode == .playAndRecord ||
           configuration.mode == .measurement ||
           configuration.mode == .voiceProcessing {

            guard await permissions.microphoneAuthorized()
            else {
                state = .failed
                throw AudioRuntimeError.microphonePermissionDenied
            }
        }

        do {

            try await session.configure(
                mode: configuration.mode,
                configuration: configuration
            )

            try await startEngineController()

            state = .running

        } catch {

            state = .failed
            throw error
        }
    }

    private func startEngineController()
        async throws
    {
        try await withCheckedThrowingContinuation {
            continuation in

            engineController.start { result in

                continuation.resume(
                    with: result
                )
            }
        }
    }

    public func stop() async {

        await withCheckedContinuation {
            continuation in

            engineController.stop {
                continuation.resume()
            }
        }

        try? await session.deactivate()

        state = .stopped
    }

    public func play(
        fileURL: URL
    ) async throws {

        try await withCheckedThrowingContinuation {
            continuation in

            engineController.play(
                fileURL: fileURL
            ) { result in

                continuation.resume(
                    with: result
                )
            }
        }

        metrics.playbackSeconds = 0
    }

    public func pause() {
        engineController.pause()
    }

    public func resume() {
        engineController.resume()
    }

    public func stopPlayback() {
        engineController.stopPlayback()
    }

    public func setVolume(
        _ volume: Float
    ) {
        engineController.setVolume(
            volume
        )
    }

    public func startRecording(
        to url: URL
    ) async throws {

        try await withCheckedThrowingContinuation {
            continuation in

            recorder.startRecording(
                to: url
            ) { result in

                continuation.resume(
                    with: result
                )
            }
        }
    }

    public func stopRecording() async {

        await withCheckedContinuation {
            continuation in

            recorder.stopRecording {
                continuation.resume()
            }
        }
    }

    public func configure(
        _ configuration:
            AudioEngineConfiguration
    ) {
        self.configuration = configuration
    }

    public func updatePowerPolicy(
        mode: String
    ) async {
        await governor.update(
            powerMode: mode
        )
    }

    public func snapshot()
        async -> AudioRuntimeSnapshot
    {
        let route =
            await session.route()

        let format =
            await session.currentFormat()

        return AudioRuntimeSnapshot(
            state: state,
            mode: configuration.mode,
            route: route,
            format: format,
            level: currentLevel,
            metrics: metrics
        )
    }
}
```

