@MainActor
@Observable
public final class AudioRuntimeViewModel {

    public private(set) var snapshot:
        AudioRuntimeSnapshot?

    public private(set) var isRunning = false

    public init() {}

    public func refresh() async {

        let value =
            await AudioRuntime.shared.snapshot()

        snapshot = value
        isRunning =
            value.state == .running
