# 25. Runtime Bootstrap

```swift
public actor AudioRuntimeBootstrap {

    public static let shared =
        AudioRuntimeBootstrap()

    private var started = false

    private init() {}

    public func start(
        configuration:
            AudioEngineConfiguration
    ) async throws {

        guard !started else {
            return
        }

        await AudioRuntime.shared.configure(
            configuration
        )

        try await AudioRuntime.shared.start()

        started = true
    }

    public func stop() async {

        guard started else {
            return
        }

        await AudioRuntime.shared.stop()

        started = false
    }
}
