# 5. Row

```swift
public struct DatabaseRow:
    Sendable
{
    private let values:
        [String: DatabaseValue]

    public init(
        values: [String: DatabaseValue]
    ) {
        self.values = values
    }

    public subscript(
        _ column: String
    ) -> DatabaseValue? {
        values[column]
    }

    public func string(
        _ column: String
    ) -> String? {

        guard case .text(let value) =
            values[column]
        else {
            return nil
        }

        return value
    }

    public func integer(
        _ column: String
    ) -> Int64? {

        guard case .integer(let value) =
            values[column]
        else {
            return nil
        }

        return value
    }

    public func double(
        _ column: String
    ) -> Double? {

        guard case .real(let value) =
            values[column]
        else {
            return nil
        }

        return value
    }

    public func data(
        _ column: String
    ) -> Data? {

        guard case .blob(let value) =
            values[column]
        else {
            return nil
        }

        return value
    }

    public var columnNames: [String] {
        Array(values.keys)
    }
}
```

