# 8. SQLite Connection

This object never crosses the database actor boundary.

```swift
final class SQLiteConnection {

    let handle: OpaquePointer

    init(
        path: String
    ) throws {

        var database:
            OpaquePointer?

        let result =
            sqlite3_open_v2(
                path,
                &database,
                SQLITE_OPEN_READWRITE |
                SQLITE_OPEN_CREATE |
                SQLITE_OPEN_FULLMUTEX,
                nil
            )

        guard
            result == SQLITE_OK,
            let database
        else {

            let message =
                database.map {
                    String(
                        cString:
                            sqlite3_errmsg($0)
                    )
                }
                ?? "Unknown SQLite error"

            if let database {
                sqlite3_close(database)
            }

            throw DatabaseError.openFailed(
                message
            )
        }

        handle = database
    }

    deinit {
        sqlite3_close(handle)
    }

    func execute(
        _ sql: String
    ) throws {

        var errorMessage:
            UnsafeMutablePointer<CChar>?

        let result =
            sqlite3_exec(
                handle,
                sql,
                nil,
                nil,
                &errorMessage
            )

        guard result == SQLITE_OK else {

            let message =
                errorMessage.map {
                    String(cString: $0)
                }
                ?? String(
                    cString:
                        sqlite3_errmsg(handle)
                )

            sqlite3_free(errorMessage)

            throw DatabaseError.executionFailed(
                message
            )
        }
    }
}
```

---

# 9. SQLite Parameter Binding

```swift
private enum SQLiteBinder {

    static func bind(
        _ parameters: [DatabaseValue],
        to statement: OpaquePointer
    ) throws {

        for (
            index,
            parameter
        ) in parameters.enumerated() {

            let position =
                Int32(index + 1)

            let result: Int32

            switch parameter {

            case .null:
                result =
                    sqlite3_bind_null(
                        statement,
                        position
                    )

            case .integer(let value):
                result =
                    sqlite3_bind_int64(
                        statement,
                        position,
                        value
                    )

            case .real(let value):
                result =
                    sqlite3_bind_double(
                        statement,
                        position,
                        value
                    )

            case .text(let value):

                result =
                    sqlite3_bind_text(
                        statement,
                        position,
                        value,
                        -1,
                        SQLITE_TRANSIENT
                    )

            case .blob(let value):

                result =
                    value.withUnsafeBytes {
                        bytes in

                        sqlite3_bind_blob(
                            statement,
                            position,
                            bytes.baseAddress,
                            Int32(value.count),
                            SQLITE_TRANSIENT
                        )
                    }
            }

            guard result == SQLITE_OK else {
                throw DatabaseError.invalidParameter
            }
        }
    }
}
```

---

# 10. SQLite Query Engine

```swift
final class SQLiteQueryEngine {

    private let connection:
        SQLiteConnection

    init(
        connection: SQLiteConnection
    ) {
        self.connection = connection
    }

    func execute(
        _ statement: SQLStatement
    ) throws {

        var prepared:
            OpaquePointer?

        let prepareResult =
            sqlite3_prepare_v2(
                connection.handle,
                statement.sql,
                -1,
                &prepared,
                nil
            )

        guard
            prepareResult == SQLITE_OK,
            let prepared
        else {
            throw DatabaseError.preparationFailed(
                String(
                    cString:
                        sqlite3_errmsg(
                            connection.handle
                        )
                )
            )
        }

        defer {
            sqlite3_finalize(prepared)
        }

        try SQLiteBinder.bind(
            statement.parameters,
            to: prepared
        )

        let result =
            sqlite3_step(prepared)

        guard
            result == SQLITE_DONE ||
            result == SQLITE_ROW
        else {

            throw DatabaseError.executionFailed(
                String(
                    cString:
                        sqlite3_errmsg(
                            connection.handle
                        )
                )
            }
        }
    }

    func query(
        _ statement: SQLStatement
    ) throws -> [DatabaseRow] {

        var prepared:
            OpaquePointer?

        let prepareResult =
            sqlite3_prepare_v2(
                connection.handle,
                statement.sql,
                -1,
                &prepared,
                nil
            )

        guard
            prepareResult == SQLITE_OK,
            let prepared
        else {
            throw DatabaseError.preparationFailed(
                String(
                    cString:
                        sqlite3_errmsg(
                            connection.handle
                        )
                )
            }

        }

        defer {
            sqlite3_finalize(prepared)
        }

        try SQLiteBinder.bind(
            statement.parameters,
            to: prepared
        )

        let columnCount =
            sqlite3_column_count(prepared)

        var rows:
            [DatabaseRow] = []

        while true {

            let result =
                sqlite3_step(prepared)

            if result == SQLITE_DONE {
                break
            }

            guard result == SQLITE_ROW else {
                throw DatabaseError.queryFailed(
                    String(
                        cString:
                            sqlite3_errmsg(
                                connection.handle
                            )
                    )
                )
            }

            var values:
                [String: DatabaseValue] = [:]

            for index in 0..<columnCount {

                guard
                    let namePointer =
                        sqlite3_column_name(
                            prepared,
                            index
                        )
                else {
                    continue
                }

                let name =
                    String(
                        cString:
                            namePointer
                    )

                let value =
                    readColumn(
                        prepared,
                        index: index
                    )

                values[name] = value
            }

            rows.append(
                DatabaseRow(
                    values: values
                )
            )
        }

        return rows
    }

    private func readColumn(
        _ statement: OpaquePointer,
        index: Int32
    ) -> DatabaseValue {

        switch sqlite3_column_type(
            statement,
            index
        ) {

        case SQLITE_INTEGER:
            return .integer(
                sqlite3_column_int64(
                    statement,
                    index
                )
            )

        case SQLITE_FLOAT:
            return .real(
                sqlite3_column_double(
                    statement,
                    index
                )
            )

        case SQLITE_TEXT:

            guard
                let pointer =
                    sqlite3_column_text(
                        statement,
                        index
                    )
            else {
                return .null
            }

            return .text(
                String(
                    cString:
                        pointer
                )
            )

        case SQLITE_BLOB:

            let length =
                Int(
                    sqlite3_column_bytes(
                        statement,
                        index
                    )
                )

            guard length > 0,
                  let pointer =
                    sqlite3_column_blob(
                        statement,
                        index
                    )
            else {
                return .blob(Data())
            }

            return .blob(
                Data(
                    bytes: pointer,
                    count: length
                )
            )

        default:
            return .null
        }
    }
}
```

