# 13. Schema Manager

```swift
final class DatabaseSchemaManager {

    private let connection:
        SQLiteConnection

    init(
        connection: SQLiteConnection
    ) {
        self.connection = connection
    }

    func ensureMetadataTable()
        throws
    {
        try connection.execute(
            """
            CREATE TABLE IF NOT EXISTS
            database_metadata (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            )
            """
        )
    }

    func currentVersion()
        throws -> Int
    {
        let engine =
            SQLiteQueryEngine(
                connection: connection
            )

        let rows =
            try engine.query(
                SQLStatement(
                    sql:
                    """
                    SELECT value
                    FROM database_metadata
                    WHERE key = 'schema_version'
                    """
                )
            )

        guard let row = rows.first,
              let value =
                row.string("value")
        else {
            return 0
        }

        return Int(value) ?? 0
    }

    func setVersion(
        _ version: Int
    ) throws {

        try connection.execute(
            """
            INSERT INTO database_metadata
            (key, value)
            VALUES ('schema_version', '\(version)')
            ON CONFLICT(key)
            DO UPDATE SET value = excluded.value
            """
        )
    }
}
```

