# 15. Database Runtime

The public database is an actor.

SQLite itself remains isolated behind it.

```swift
public actor DatabaseRuntime {

    public static let shared =
        DatabaseRuntime()

    private let configuration:
        DatabaseConfiguration

    private var connection:
        SQLiteConnection?

    private var queryEngine:
        SQLiteQueryEngine?

    private var transactionController:
        SQLiteTransactionController?

    private var state:
        DatabaseRuntimeState = .stopped

    private var schemaVersion:
        Int = 0

    private init(
        configuration:
            DatabaseConfiguration =
            DatabaseConfiguration()
    ) {
        self.configuration =
            configuration
    }

    public func open()
        throws
    {
        guard connection == nil else {
            return
        }

        state = .opening

        let directory =
            try databaseDirectory()

        let path =
            directory
                .appendingPathComponent(
                    configuration.filename
                )

        let connection =
            try SQLiteConnection(
                path: path.path
            )

        self.connection =
            connection

        self.queryEngine =
            SQLiteQueryEngine(
                connection: connection
            )

        self.transactionController =
            SQLiteTransactionController(
                connection: connection
            )

        try configureSQLite(
            connection: connection
        )

        try migrate(
            connection: connection
        )

        state = .ready
    }

    public func close()
        throws
    {
        queryEngine = nil
        transactionController = nil
        connection = nil

        state = .stopped
    }

    private func databaseDirectory()
        throws -> URL
    {
        let base =
            try FileManager.default.url(
                for: .applicationSupportDirectory,
                in: .userDomainMask,
                appropriateFor: nil,
                create: true
            )

        let directory =
            base.appendingPathComponent(
                "Database",
                isDirectory: true
            )

        try FileManager.default.createDirectory(
            at: directory,
            withIntermediateDirectories: true
        )

        return directory
    }

    private func configureSQLite(
        connection:
            SQLiteConnection
    ) throws {

        try connection.execute(
            """
            PRAGMA foreign_keys = ON
            """
        )

        try connection.execute(
            """
            PRAGMA busy_timeout =
            \(configuration.busyTimeoutMilliseconds)
            """
        )

        try connection.execute(
            """
            PRAGMA journal_mode = WAL
            """
        )

        if configuration.synchronousNormal {

            try connection.execute(
                """
                PRAGMA synchronous = NORMAL
                """
            )
        }

        try connection.execute(
            """
            PRAGMA cache_size =
            -\(configuration.cacheSizePages)
            """
        )
    }

    private func migrate(
        connection:
            SQLiteConnection
    ) throws {

        let schema =
            DatabaseSchemaManager(
                connection: connection
            )

        try schema.ensureMetadataTable()

        let version =
            try schema.currentVersion()

        if version < 1 {

            state = .migrating

            try InitialDatabaseSchema.create(
                connection: connection
            )

            try schema.setVersion(1)

            schemaVersion = 1
        } else {
            schemaVersion = version
        }

        state = .ready
    }
}
```

