# 18. Telemetry Repository

This connects directly to the Watch/iPhone telemetry architecture.

```swift
public struct TelemetryRecord:
    Sendable,
    Codable
{
    public let timestamp: Double
    public let kind: String
    public let value: Double
    public let quality: Int
    public let sessionID: String?

    public init(
        timestamp: Double,
        kind: String,
        value: Double,
        quality: Int = 0,
        sessionID: String? = nil
    ) {
        self.timestamp = timestamp
        self.kind = kind
        self.value = value
        self.quality = quality
        self.sessionID = sessionID
    }
}
```

```swift
public actor TelemetryRepository {

    private let database:
        DatabaseRuntime

    public init(
        database: DatabaseRuntime =
            .shared
    ) {
        self.database = database
    }

    public func insert(
        _ record: TelemetryRecord
    ) throws {

        try database.execute(
            SQLStatement(
                sql:
                """
                INSERT INTO telemetry
                (
                    timestamp,
                    kind,
                    value,
                    quality,
                    session_id
                )
                VALUES (?, ?, ?, ?, ?)
                """,
                parameters: [
                    .real(record.timestamp),
                    .text(record.kind),
                    .real(record.value),
                    .integer(
                        Int64(record.quality)
                    ),
                    record.sessionID
                        .map(DatabaseValue.text)
                        ?? .null
                ]
            )
        )
    }

    public func insertBatch(
        _ records: [TelemetryRecord]
    ) throws {

        guard !records.isEmpty else {
            return
        }

        try database.transaction {

            for record in records {

                try database.execute(
                    SQLStatement(
                        sql:
                        """
                        INSERT INTO telemetry
                        (
                            timestamp,
                            kind,
                            value,
                            quality,
                            session_id
                        )
                        VALUES (?, ?, ?, ?, ?)
                        """,
                        parameters: [
                            .real(
                                record.timestamp
                            ),
                            .text(
                                record.kind
                            ),
                            .real(
                                record.value
                            ),
                            .integer(
                                Int64(
                                    record.quality
                                )
                            ),
                            record.sessionID
                                .map(
                                    DatabaseValue.text
                                )
                                ?? .null
                        ]
                    )
                )
            }
        }
    }

    public func latest(
        kind: String,
        limit: Int = 100
    ) throws -> [DatabaseRow] {

        let boundedLimit =
            max(
                1,
                min(limit, 10_000)
            )

        return try database.query(
            SQLStatement(
                sql:
                """
                SELECT
                    id,
                    timestamp,
                    kind,
                    value,
                    quality,
                    session_id
                FROM telemetry
                WHERE kind = ?
                ORDER BY timestamp DESC
                LIMIT ?
                """,
                parameters: [
                    .text(kind),
                    .integer(
                        Int64(boundedLimit)
                    )
                ]
            )
        )
    }
}
```

