# 19. Persistent Network Outbox

This replaces the in-memory-only queue from networking subsystem #4.

```swift
public enum OutboxState:
    String,
    Sendable,
    Codable
{
    case pending
    case sending
    case completed
    case failed
}

public struct NetworkOutboxRecord:
    Sendable,
    Codable
{
    public let endpoint: String
    public let method: String
    public let payload: Data
    public let priority:
        DatabasePriority

    public init(
        endpoint: String,
        method: String,
        payload: Data,
        priority: DatabasePriority =
            .normal
    ) {
        self.endpoint = endpoint
        self.method = method
        self.payload = payload
        self.priority = priority
    }
}
```

```swift
public actor NetworkOutboxRepository {

    private let database:
        DatabaseRuntime

    public init(
        database: DatabaseRuntime =
            .shared
    ) {
        self.database = database
    }

    @discardableResult
    public func enqueue(
        _ record:
            NetworkOutboxRecord
    ) throws -> Int64 {

        try database.execute(
            SQLStatement(
                sql:
                """
                INSERT INTO network_outbox
                (
                    created_at,
                    priority,
                    endpoint,
                    method,
                    payload,
                    attempts,
                    state
                )
                VALUES (?, ?, ?, ?, ?, 0, ?)
                """,
                parameters: [
                    .real(
                        Date().timeIntervalSince1970
                    ),
                    .integer(
                        Int64(
                            record.priority.rawValue
                        )
                    ),
                    .text(record.endpoint),
                    .text(record.method),
                    .blob(record.payload),
                    .text(
                        OutboxState.pending.rawValue
                    )
                ]
            )
        )

        return try database.query(
            SQLStatement(
                sql:
                "SELECT last_insert_rowid() AS id"
            )
        )
        .first?
        .integer("id") ?? 0
    }

    public func nextBatch(
        limit: Int = 50
    ) throws -> [DatabaseRow] {

        let boundedLimit =
            max(
                1,
                min(limit, 500)
            )

        return try database.query(
            SQLStatement(
                sql:
                """
                SELECT
                    id,
                    created_at,
                    priority,
                    endpoint,
                    method,
                    payload,
                    attempts,
                    next_attempt,
                    state
                FROM network_outbox
                WHERE state = ?
                  AND (
                    next_attempt IS NULL
                    OR next_attempt <= ?
                  )
                ORDER BY
                    priority DESC,
                    created_at ASC
                LIMIT ?
                """,
                parameters: [
                    .text(
                        OutboxState.pending.rawValue
                    ),
                    .real(
                        Date().timeIntervalSince1970
                    ),
                    .integer(
                        Int64(boundedLimit)
                    )
                ]
            )
        )
    }

    public func markSending(
        id: Int64
    ) throws {

        try database.execute(
            SQLStatement(
                sql:
                """
                UPDATE network_outbox
                SET state = ?
                WHERE id = ?
                """,
                parameters: [
                    .text(
                        OutboxState.sending.rawValue
                    ),
                    .integer(id)
                ]
            )
        )
    }

    public func markCompleted(
        id: Int64
    ) throws {

        try database.execute(
            SQLStatement(
                sql:
                """
                UPDATE network_outbox
                SET state = ?
                WHERE id = ?
                """,
                parameters: [
                    .text(
                        OutboxState.completed.rawValue
                    ),
                    .integer(id)
                ]
            )
        )
    }

    public func markFailed(
        id: Int64,
        retryAt: Date
    ) throws {

        try database.execute(
            SQLStatement(
                sql:
                """
                UPDATE network_outbox
                SET
                    state = ?,
                    attempts = attempts + 1,
                    next_attempt = ?
                WHERE id = ?
                """,
                parameters: [
                    .text(
                        OutboxState.pending.rawValue
                    ),
                    .real(
                        retryAt.timeIntervalSince1970
                    ),
                    .integer(id)
                ]
            )
        )
    }

    public func purgeCompleted(
        olderThan date: Date
    ) throws {

        try database.execute(
            SQLStatement(
                sql:
                """
                DELETE FROM network_outbox
                WHERE state = ?
                  AND created_at < ?
                """,
                parameters: [
                    .text(
                        OutboxState.completed.rawValue
                    ),
                    .real(
                        date.timeIntervalSince1970
                    )
                ]
            )
        )
    }
}
```

