# 20. Application State Repository

```swift
public actor ApplicationStateRepository {

    private let database:
        DatabaseRuntime

    public init(
        database: DatabaseRuntime =
            .shared
    ) {
        self.database = database
    }

    public func set(
        key: String,
        value: Data
    ) throws {

        try database.execute(
            SQLStatement(
                sql:
                """
                INSERT INTO application_state
                (
                    key,
                    value,
                    updated_at
                )
                VALUES (?, ?, ?)
                ON CONFLICT(key)
                DO UPDATE SET
                    value = excluded.value,
                    updated_at = excluded.updated_at
                """,
                parameters: [
                    .text(key),
                    .blob(value),
                    .real(
                        Date()
                            .timeIntervalSince1970
                    )
                ]
            )
        )
    }

    public func get(
        key: String
    ) throws -> Data? {

        let rows =
            try database.query(
                SQLStatement(
                    sql:
                    """
                    SELECT value
                    FROM application_state
                    WHERE key = ?
                    """,
                    parameters: [
                        .text(key)
                    ]
                )
            )

        return rows.first?.data(
            "value"
        )
    }

    public func remove(
        key: String
    ) throws {

        try database.execute(
            SQLStatement(
                sql:
                """
                DELETE FROM application_state
                WHERE key = ?
                """,
                parameters: [
                    .text(key)
                ]
            )
        )
    }
}
```

