# 22. Database Maintenance

```swift
public actor DatabaseMaintenance {

    private let database:
        DatabaseRuntime

    public init(
        database: DatabaseRuntime =
            .shared
    ) {
        self.database = database
    }

    public func checkpoint()
        throws
    {
        try database.execute(
            SQLStatement(
                sql:
                """
                PRAGMA wal_checkpoint(PASSIVE)
                """
            )
        )
    }

    public func analyze()
        throws
    {
        try database.execute(
            SQLStatement(
                sql:
                "ANALYZE"
            )
        )
    }

    public func optimize()
        throws
    {
        try database.execute(
            SQLStatement(
                sql:
                "PRAGMA optimize"
            )
        )
    }
}
