@MainActor
@Observable
public final class DatabaseRuntimeViewModel {

    public private(set) var state:
        DatabaseRuntimeState = .stopped

    public private(set) var schemaVersion:
        Int = 0

    public init() {}

    public func refresh() async {

        state =
            await DatabaseRuntime.shared
                .currentState()

        schemaVersion =
            await DatabaseRuntime.shared
                .currentSchemaVersion()
    }

    public func open() async {

        do {
            try await
                DatabaseRuntime.shared.open()
        } catch {
            // Production UI should surface
            // a structured database error.
        }

        await refresh()
    }

    public func close() async {

        try? await
            DatabaseRuntime.shared.close()

        await refresh()
    }
}
