# 14. Cloud Record Repository

```swift
public actor CloudRecordRepository {

    private let database:
        CKDatabase

    public init(
        database: CKDatabase
    ) {
        self.database = database
    }

    public func save(
        _ record: CloudRecord
    ) async throws {

        let cloudRecord =
            CloudRecordMapper.makeRecord(
                record
            )

        _ = try await database.save(
            cloudRecord
        )
    }

    public func fetch(
        id: CloudRecordID,
        recordType: String
    ) async throws
        -> CloudRecord
    {

        let recordID =
            CKRecord.ID(
                recordName:
                    id.recordName
            )

        let record =
            try await database.record(
                for: recordID
            )

        guard
            record.recordType ==
                recordType
        else {
            throw CloudRuntimeError.invalidRecord
        }

        var fields:
            [String: CloudValue] = [:]

        for key in record.allKeys() {

            fields[key] =
                CloudRecordMapper.makeValue(
                    record[key]
                )
        }

        return CloudRecord(
            id: id,
            recordType:
                record.recordType,
            fields: fields
        )
    }

    public func delete(
        id: CloudRecordID
    ) async throws {

        let recordID =
            CKRecord.ID(
                recordName:
                    id.recordName
            )

        _ = try await database.deleteRecord(
            withID: recordID
        )
    }
}
```

