# 12. Local Notification Scheduler

```swift
public actor LocalNotificationScheduler {

    private let center:
        UNUserNotificationCenter

    public init(
        center:
            UNUserNotificationCenter =
            .current()
    ) {
        self.center = center
    }

    public func schedule(
        _ request:
            LocalNotificationRequest
    ) async throws {

        let content =
            UNMutableNotificationContent()

        if let title =
            request.payload.title {

            content.title =
                title
        }

        if let body =
            request.payload.body {

            content.body =
                body
        }

        content.categoryIdentifier =
            request.payload.category.rawValue

        if !request.payload.data.isEmpty {

            content.userInfo =
                request.payload.data
        }

        let trigger:
            UNNotificationTrigger

        switch request.trigger {

        case .immediate:

            trigger = nil

        case .after(let seconds):

            trigger =
                UNTimeIntervalNotificationTrigger(
                    timeInterval:
                        max(
                            1,
                            seconds
                        ),
                    repeats: false
                )

        case .calendar(
            let components,
            let repeats
        ):

            trigger =
                UNCalendarNotificationTrigger(
                    dateMatching:
                        components,
                    repeats:
                        repeats
                )
        }

        let notificationRequest =
            UNNotificationRequest(
                identifier:
                    request.id,
                content:
                    content,
                trigger:
                    trigger
            )

        try await center.add(
            notificationRequest
        )
    }

    public func cancel(
        identifier:
            String
    ) {

        center.removePendingNotificationRequests(
            withIdentifiers: [
                identifier
            ]
        )
    }

    public func cancelAll() {

        center.removeAllPendingNotificationRequests()
    }
}
```

