public actor NotificationDeepLinkRouter {

    public init() {}

    public func destination(
        from payload:
            PushPayload
    ) -> NotificationDestination?
    {
        guard
            let raw =
                payload.deepLink,
            let url =
                URL(string: raw)
        else {
            return nil
        }

        return NotificationDestination(
            url: url
        )
    }
}
