# 21. Notification Delegate

UIKit's notification delegate should be a MainActor boundary.

```swift
@MainActor
public final class ApplicationNotificationDelegate:
    NSObject,
    UNUserNotificationCenterDelegate
{
    private let router:
        PushEventRouter

    public init(
        router:
            PushEventRouter
    ) {
        self.router =
            router

        super.init()
    }

    public func userNotificationCenter(
        _ center:
            UNUserNotificationCenter,
        willPresent notification:
            UNNotification
    ) async
        -> UNNotificationPresentationOptions
    {
        let envelope =
            Self.makeEnvelope(
                notification
            )

        await router.publish(
            .received(
                envelope
            )
        )

        return [
            .banner,
            .sound,
            .badge
        ]
    }

    public func userNotificationCenter(
        _ center:
            UNUserNotificationCenter,
        didReceive response:
            UNNotificationResponse
    ) async
    {
        let envelope =
            Self.makeEnvelope(
                response.notification
            )

        if response.actionIdentifier ==
            UNNotificationDefaultActionIdentifier {

            await router.publish(
                .opened(
                    envelope
                )
            )

            return
        }

        if let action =
            NotificationAction(
                rawValue:
                    response.actionIdentifier
            ) {

            await router.publish(
                .action(
                    action,
                    envelope
                )
            )
        }
    }

    private static func makeEnvelope(
        _ notification:
            UNNotification
    ) -> RemoteNotificationEnvelope {

        let request =
            notification.request

        let content =
            request.content

        let category =
            NotificationCategory(
                rawValue:
                    content.categoryIdentifier
            )
            ?? .general

        var data:
            [String: String] = [:]

        for (
            key,
            value
        ) in content.userInfo {

            if let string =
                value as? String {

                data[key] =
                    string
            }
        }

        let payload =
            PushPayload(
                identifier:
                    request.identifier,
                title:
                    content.title,
                body:
                    content.body,
                category:
                    category,
                data:
                    data
            )

        return RemoteNotificationEnvelope(
            payload:
                payload
        )
    }
}
```

