# 26. Push Runtime

```swift
public actor PushRuntime {

    public static let shared =
        PushRuntime()

    private let permission:
        NotificationPermissionManager

    private let categories:
        NotificationCategoryRegistry

    private let scheduler:
        LocalNotificationScheduler

    private let badge:
        NotificationBadgeManager

    private let tokenRegistry:
        PushTokenRegistry

    public let eventRouter:
        PushEventRouter

    private var state:
        PushRuntimeState =
        .stopped

    private var metrics =
        PushMetrics()

    private init() {

        let center =
            UNUserNotificationCenter.current()

        self.permission =
            NotificationPermissionManager(
                center: center
            )

        self.categories =
            NotificationCategoryRegistry(
                center: center
            )

        self.scheduler =
            LocalNotificationScheduler(
                center: center
            )

        self.badge =
            NotificationBadgeManager()

        self.tokenRegistry =
            PushTokenRegistry()

        self.eventRouter =
            PushEventRouter()
    }

    public func start()
        async
    {
        guard state == .stopped else {
            return
        }

        state = .starting

        await categories.register()

        let authorization =
            await permission.status()

        switch authorization {

        case .authorized,
             .provisional,
             .ephemeral:

            state = .ready

        case .notDetermined:

            state =
                .permissionRequired

        case .denied:

            state = .denied
        }
    }

    public func requestAuthorization()
        async throws
        -> Bool
    {
        let granted =
            try await permission
                .requestAuthorization()

        state =
            granted
            ? .ready
            : .denied

        let authorization =
            await permission.status()

        await eventRouter.publish(
            .authorizationChanged(
                authorization
            )
        )

        return granted
    }

    public func registerToken(
        _ token:
            Data
    ) async {

        let pushToken =
            APNsTokenEncoder.encode(
                token
            )

        await tokenRegistry.update(
            pushToken
        )

        metrics.tokensUpdated += 1

        await eventRouter.publish(
            .tokenUpdated(
                pushToken
            )
        )

        state = .registered
    }

    public func currentToken()
        async
        -> PushToken?
    {
        await tokenRegistry.current()
    }

    public func schedule(
        _ request:
            LocalNotificationRequest
    ) async throws {

        guard
            state == .ready ||
            state == .registered
        else {
            throw CloudRuntimeError
                .accountUnavailable
        }

        try await scheduler.schedule(
            request
        )
    }

    public func cancel(
        identifier:
            String
    ) async {

        await scheduler.cancel(
            identifier:
                identifier
        )
    }

    public func clearBadge()
        async
    {
        await badge.clear()
    }

    public func runtimeState()
        -> PushRuntimeState
    {
        state
    }

    public func currentMetrics()
        -> PushMetrics
    {
        metrics
    }
}
```

The `schedule` error above should be replaced with a dedicated `PushRuntimeError` in the production code; the cloud error was only used to keep this subsystem example compact.

