# 35. Push Runtime View Model

```swift
@MainActor
@Observable
public final class PushRuntimeViewModel {

    public private(set) var state:
        PushRuntimeState =
        .stopped

    public private(set) var authorization:
        NotificationAuthorizationState =
        .notDetermined

    public private(set) var hasToken =
        false

    public init() {}

    public func refresh()
        async
    {
        state =
            await PushRuntime.shared
                .runtimeState()

        hasToken =
            await PushRuntime.shared
                .currentToken() != nil
    }

    public func start()
        async
    {
        await PushRuntime.shared.start()
        await refresh()
    }

    public func requestPermission()
        async
    {
        do {
            _ = try await
                PushRuntime.shared
                    .requestAuthorization()
        } catch {
            // Surface through production
            // diagnostics / UI state.
        }

        await refresh()
    }
}
```

