        kind: BackgroundTaskKind,
        priority:
            BackgroundTaskPriority =
            .normal,
        earliestBeginDate:
            Date? = nil,
        createdAt:
            Date = Date()
    ) {
        self.id = id
        self.kind = kind
        self.priority = priority
        self.earliestBeginDate =
            earliestBeginDate
        self.createdAt = createdAt
    }
}
