# 17. Scheduler

```swift
public actor BackgroundScheduler {

    private let queue:
        BackgroundWorkQueue

    private let policy:
        BackgroundExecutionPolicy

    private let powerGate:
        BackgroundPowerGate

    private let networkGate:
        BackgroundNetworkGate

    private let cancellation:
        BackgroundCancellationController

    private let expiration:
        BackgroundExpirationController

    private var metrics =
        BackgroundMetrics()

    private var state:
        BackgroundRuntimeState =
        .stopped

    public init(
        policy:
            BackgroundExecutionPolicy =
            BackgroundExecutionPolicy()
    ) {
        self.policy =
            policy

        self.queue =
            BackgroundWorkQueue()

        self.powerGate =
            BackgroundPowerGate()

        self.networkGate =
            BackgroundNetworkGate()

        self.cancellation =
            BackgroundCancellationController()

        self.expiration =
            BackgroundExpirationController()
    }

    public func start() {

        guard
            policy.enabled
        else {
            state = .degraded
            return
        }

        state = .ready
    }

    public func stop() {

        state = .stopped
    }

    public func submit(
        _ work:
            BackgroundWorkUnit
    ) {

        guard
            policy.enabled
        else {
            return
        }

        metrics.submitted += 1

        Task {
            await queue.enqueue(
                work
            )
        }
    }

    public func updatePower(
        _ snapshot:
            BackgroundPowerSnapshot
    ) async {

        await powerGate.update(
            snapshot
        )
    }

    public func updateNetwork(
        available:
            Bool
    ) async {

        await networkGate.update(
            available:
                available
        )
    }

    public func beginExpiration()
        async
    {
        await expiration
            .beginExpiration()

        state = .expiring
    }

    public func resetExpiration()
        async
    {
        await expiration.reset()

        state = .ready
    }

    public func execute(
        context:
            BackgroundExecutionContext
    ) async
        -> BackgroundTaskResult
    {
        guard policy.enabled else {
            return .failed
        }

        state = .executing

        metrics.started += 1

        let powerDecision =
            await powerGate.decision(
                for:
                    context.kind
            )

        guard
            powerDecision == .execute
        else {
            metrics.deferred += 1
            state = .ready
            return .retry
        }

        guard
            await networkGate.canExecute(
                kind:
                    context.kind
            )
        else {
            metrics.deferred += 1
            state = .ready
            return .retry
        }

        let work =
            await queue.dequeue(
                limit:
                    policy.maximumWorkItems
            )

        guard !work.isEmpty else {
            state = .ready
            return .noWork
        }

        for item in work {

            if
                await expiration.shouldStop()
            {
                metrics.expired += 1
                state = .ready
                return .expired
            }

            if
                context.remainingTime <= 0
            {
                metrics.expired += 1
                state = .ready
                return .expired
            }

            do {

                try await item.operation()

            } catch {

                Logger.background.error(
                    """
                    Background work failed:
                    \(String(describing: error))
                    """
                )

                metrics.failed += 1

                state = .ready
                return .failed
            }
        }

        metrics.completed += 1
        metrics.lastExecution = Date()

        state = .ready

        return .completed
    }

    public func currentState()
        -> BackgroundRuntimeState
    {
        state
    }

    public func currentMetrics()
        -> BackgroundMetrics
    {
        metrics
    }
}
```

---

# 18. BGTaskScheduler Registration

`BGTaskScheduler` registration belongs at application startup.

```swift
@MainActor
public final class BackgroundTaskRegistration {

    public init() {}

    public func register() {

        BGTaskScheduler.shared.register(
            forTaskWithIdentifier:
                BackgroundTaskIdentifier.refresh,
            using:
                nil
        ) { task in

            guard
                let refreshTask =
                    task as? BGAppRefreshTask
            else {
                task.setTaskCompleted(
                    success: false
                )
                return
            }

            Task {
                await BackgroundRuntime.shared
                    .handleRefresh(
                        refreshTask
                    )
            }
        }

        BGTaskScheduler.shared.register(
            forTaskWithIdentifier:
                BackgroundTaskIdentifier.processing,
            using:
                nil
        ) { task in

            guard
                let processingTask =
                    task as? BGProcessingTask
            else {
                task.setTaskCompleted(
                    success: false
                )
                return
            }

            Task {
                await BackgroundRuntime.shared
                    .handleProcessing(
                        processingTask
                    )
            }
        }
    }
}
```

