# 11. Extension Router

```swift
public actor ExtensionEventRouter {

    private var continuations:
        [
            UUID:
            AsyncStream<ExtensionEvent>
                .Continuation
        ] = [:]

    public init() {}

    public func stream()
        -> AsyncStream<ExtensionEvent>
    {
        let id =
            UUID()

        return AsyncStream { continuation in

            continuations[id] =
                continuation

            continuation.onTermination = {
                [weak self]
                _ in

                Task {
                    await self?.remove(
                        id
                    )
                }
            }
        }
    }

    public func publish(
        _ event:
            ExtensionEvent
    ) {

        for continuation
            in continuations.values {

            continuation.yield(
                event
            )
        }
    }

    private func remove(
        _ id:
            UUID
    ) {
        continuations[id] = nil
    }
}
```

---

# 12. Extension Runtime

```swift
public actor ExtensionRuntime {

    public static let shared =
        ExtensionRuntime()

    private var state:
        ExtensionRuntimeState =
        .stopped

    private var activeContext:
        ExtensionContext?

    private let router =
        ExtensionEventRouter()

    private init() {}

    public func start(
        context:
            ExtensionContext
    ) async {

        guard
            state == .stopped
        else {
            return
        }

        activeContext =
            context

        state =
            .ready

        await router.publish(
            .launched
        )
    }

    public func beginExecution() async
        throws
    {
        guard
            state == .ready
        else {
            throw ExtensionRuntimeError
                .unavailable
        }

        state =
            .executing
    }

    public func complete(
        success:
            Bool
    ) async {

        state =
            success
            ? .ready
            : .failed

        await router.publish(
            success
            ? .completed
            : .failed
        )
    }

    public func expire() async {

        state =
            .expiring

        await router.publish(
            .expired
        )
    }

    public func cancel() async {

        state =
            .cancelled

        await router.publish(
            .cancelled
        )
    }

    public func stop() async {

        activeContext =
            nil

        state =
            .stopped
    }

    public func currentState()
        -> ExtensionRuntimeState
    {
        state
    }

    public func currentContext()
        -> ExtensionContext?
    {
        activeContext
    }

    public func events()
        -> AsyncStream<ExtensionEvent>
    {
        router.stream()
    }
}
```

