    Codable
{
    public let maximumSnapshotBytes:
        Int

    public let maximumInputBytes:
        Int

    public let maximumCacheBytes:
        Int

    public init(
        maximumSnapshotBytes:
            Int = 1_048_576,
        maximumInputBytes:
            Int = 25_000_000,
