# 30. Extension Runtime Coordinator

```swift
public actor ExtensionRuntimeCoordinator {

    public static let shared =
        ExtensionRuntimeCoordinator()

    private let diagnostics =
        ExtensionDiagnostics()

    private init() {}

    public func execute(
        context:
            ExtensionContext,
        operation:
            @escaping @Sendable () async throws -> Void
    ) async
        -> ExtensionRuntimeSnapshot
    {
        await ExtensionRuntime.shared.start(
            context:
                context
        )

        await diagnostics.launched()

        do {

            try await
                ExtensionRuntime.shared
                .beginExecution()

            try Task.checkCancellation()

            try await operation()

            try Task.checkCancellation()

            await diagnostics.completed()

            await ExtensionRuntime.shared
                .complete(
                    success:
                        true
                )

        } catch is CancellationError {

            await diagnostics.cancelled()

            await ExtensionRuntime.shared
                .cancel()

        } catch {

            await diagnostics.failed()

            await ExtensionRuntime.shared
                .complete(
                    success:
                        false
                )
        }

        return ExtensionRuntimeSnapshot(
            state:
                await ExtensionRuntime.shared
                    .currentState(),
            context:
                await ExtensionRuntime.shared
                    .currentContext(),
            metrics:
                await diagnostics.snapshot()
        )
    }
}
```

