# 8. Scene Registry

```swift
public actor SceneRegistry {

    private var scenes:
        [ApplicationSceneID: SceneRecord] = [:]

    public init() {}

    public func register(
        _ descriptor:
            SceneDescriptor
    ) {

        if scenes[descriptor.id] == nil {

            scenes[descriptor.id] =
                SceneRecord(
                    descriptor:
                        descriptor
                )
        }
    }

    public func remove(
        _ id:
            ApplicationSceneID
    ) {
        scenes[id] = nil
    }

    public func record(
        _ id:
            ApplicationSceneID
    )
        -> SceneRecord?
    {
        scenes[id]
    }

    public func all()
        -> [SceneRecord]
    {
        Array(
            scenes.values
        )
    }

    public func updateState(
        _ state:
            SceneLifecycleState,
        id:
            ApplicationSceneID
    ) {

        guard
            var scene =
                scenes[id]
        else {
            return
        }

        scene.state =
            state

        scene.lastTransition =
            Date()

        if state == .active {

            scene.lastActive =
                Date()

            scene.activationCount += 1
        }

        scenes[id] =
            scene
    }

    public func setPriority(
        _ priority:
            ScenePriority,
        id:
            ApplicationSceneID
    ) {

        guard
            var scene =
                scenes[id]
        else {
            return
        }

        scene.priority =
            priority

        scenes[id] =
            scene
    }
}
```

---

# 9. Scene Event Bus

```swift
public actor SceneEventBus {

    private var continuations:
        [
            UUID:
            AsyncStream<SceneEvent>.Continuation
        ] = [:]

    public init() {}

    public func stream()
        -> AsyncStream<SceneEvent>
    {
        let id =
            UUID()

        return AsyncStream { continuation in

            continuations[id] =
                continuation

            continuation.onTermination = {
                [weak self]
                _ in

                Task {
                    await self?.remove(
                        id
                    )
                }
            }
        }
    }

    public func publish(
        _ event:
            SceneEvent
    ) {

        for continuation
            in continuations.values {

            continuation.yield(
                event
            )
        }
    }

    private func remove(
        _ id:
            UUID
    ) {
        continuations[id] =
            nil
    }
}
```

---

# 10. Scene Manager

```swift
public actor SceneManager {

    public static let shared =
        SceneManager()

    private let registry =
        SceneRegistry()

    private let eventBus =
        SceneEventBus()

    private init() {}

    public func connect(
        _ descriptor:
            SceneDescriptor
    ) async {

        await registry.register(
            descriptor
        )

        await registry.updateState(
            .connecting,
            id:
                descriptor.id
        )

        await eventBus.publish(
            .connected(
                descriptor.id
            )
        )
    }

    public func activate(
        _ id:
            ApplicationSceneID
    ) async {

        await registry.updateState(
            .active,
            id:
                id
        )

        await eventBus.publish(
            .active(id)
        )
    }

    public func deactivate(
        _ id:
            ApplicationSceneID
    ) async {

        await registry.updateState(
            .inactive,
            id:
                id
        )

        await eventBus.publish(
            .inactive(id)
        )
    }

    public func background(
        _ id:
            ApplicationSceneID
    ) async {

        await registry.updateState(
            .background,
            id:
                id
        )

        await eventBus.publish(
            .background(id)
        )
    }

    public func suspend(
        _ id:
            ApplicationSceneID
    ) async {

        await registry.updateState(
            .suspended,
            id:
                id
        )

        await eventBus.publish(
            .suspended(id)
        )
    }

    public func disconnect(
        _ id:
            ApplicationSceneID
    ) async {

        await registry.updateState(
            .disconnected,
            id:
                id
        )

        await eventBus.publish(
            .disconnected(id)
        )
    }

    public func terminate(
        _ id:
            ApplicationSceneID
    ) async {

        await registry.updateState(
            .terminating,
            id:
                id
        )

        await eventBus.publish(
            .terminated(id)
        )

        await registry.remove(
            id
        )
    }

    public func setPriority(
        _ priority:
            ScenePriority,
        for id:
            ApplicationSceneID
    ) async {

        await registry.setPriority(
            priority,
            id:
                id
        )
    }

    public func snapshot()
        async
        -> [SceneRecord]
    {
        await registry.all()
    }

    public func events()
        -> AsyncStream<SceneEvent>
    {
        eventBus.stream()
    }
}
```

