# 19. Scene-Aware SwiftUI Root

```swift
public struct SceneAwareRoot<Content: View>:
    View
{
    @Environment(\.scenePhase)
    private var scenePhase

    private let bridge:
        ScenePhaseBridge

    private let content:
        Content

    public init(
        sceneID:
            ApplicationSceneID,
        @ViewBuilder content:
            () -> Content
    ) {
        self.bridge =
            ScenePhaseBridge(
                sceneID:
                    sceneID
            )

        self.content =
            content()
    }

    public var body:
        some View
    {
        content
            .onChange(
                of:
                    scenePhase
            ) {
                _,
                newPhase in

                bridge.update(
                    phase:
                        newPhase
                )
            }
    }
}
