# 22. Scene Coordinator

```swift
public actor SceneCoordinator {

    public static let shared =
        SceneCoordinator()

    private let restoration:
        SceneRestorationStore

    private let governor:
        SceneResourceGovernor

    private let scheduler:
        SceneScheduler

    private init() {

        let governor =
            SceneResourceGovernor()

        self.governor =
            governor

        self.scheduler =
            SceneScheduler(
                governor:
                    governor
            )

        self.restoration =
            SceneRestorationStore()
    }

    public func register(
        id:
            ApplicationSceneID,
        role:
            ApplicationSceneRole
    ) async {

        let descriptor =
            SceneDescriptor(
                id:
                    id,
                role:
                    role
            )

        await SceneManager.shared
            .connect(
                descriptor
            )
    }

    public func workload(
        _ request:
            SceneWorkloadRequest
    ) async {

        await governor.submit(
            request
        )
    }

    public func policy(
        for scene:
            ApplicationSceneID
    ) async
        -> SceneExecutionDecision?
    {
        let scenes =
            await SceneManager.shared
                .snapshot()

        guard
            let scene =
                scenes.first(
                    where:
                        {
                            $0.descriptor.id ==
                            scene
                        }
                )
        else {
            return nil
        }

        return await scheduler.decision(
            for:
                scene
        )
    }

    public func saveRestoration(
        _ state:
            SceneRestorationState
    ) async {

        await restoration.save(
            state
        )
    }

    public func restore(
        _ id:
            ApplicationSceneID
    ) async
        -> SceneRestorationState?
    {
        await restoration.load(
            id
        )
    }
}
```

