# 25. Multitasking Runtime

```swift
public actor MultitaskingRuntime {

    public static let shared =
        MultitaskingRuntime()

    private let coordinator:
        SceneCoordinator

    private var running =
        false

    private init() {

        coordinator =
            SceneCoordinator.shared
    }

    public func start() async {

        guard !running else {
            return
        }

        running =
            true
    }

    public func stop() async {

        guard running else {
            return
        }

        running =
            false
    }

    public func registerScene(
        id:
            ApplicationSceneID,
        role:
            ApplicationSceneRole
    ) async {

        await coordinator.register(
            id:
                id,
            role:
                role
        )
    }

    public func submitWorkload(
        _ request:
            SceneWorkloadRequest
    ) async {

        await coordinator.workload(
            request
        )
    }

    public func snapshot()
        async
        -> MultitaskingSnapshot
    {
        await MultitaskingSnapshotProvider()
            .snapshot()
    }
}
```

