public actor MultitaskingDiagnostics {

    private var metrics =
        MultitaskingMetrics()

    public init() {}

    public func connected() {
        metrics.connectedScenes += 1
    }

    public func activated() {
        metrics.activations += 1
        metrics.lastActivation =
            Date()
    }

    public func backgrounded() {
        metrics.backgroundTransitions += 1
    }

    public func disconnected() {
        metrics.disconnections += 1
    }

    public func restored() {
        metrics.restorations += 1
    }

    public func snapshot()
        -> MultitaskingMetrics
