# 6. Path Monitor

`NWPathMonitor` remains the authoritative public API for observing network-path changes.

```swift
public actor ConnectivityPathMonitor {

    private let monitor:
        NWPathMonitor

    private let queue:
        DispatchQueue

    private var currentPath:
        NWPath?

    private var continuation:
        AsyncStream<ConnectivityEnvironment>
            .Continuation?

    public init() {

        monitor =
            NWPathMonitor()

        queue =
            DispatchQueue(
                label:
                    "com.runtime.connectivity.path",
                qos:
                    .utility
            )
    }

    public func start()
        -> AsyncStream<ConnectivityEnvironment>
    {
        let stream =
            AsyncStream<ConnectivityEnvironment> {
                continuation in

                self.continuation =
                    continuation

                monitor.pathUpdateHandler = {
                    [weak self]
                    path in

                    Task {

                        await self?
                            .handle(
                                path
                            )
                    }
                }

                monitor.start(
                    queue:
                        queue
                )
            }

        return stream
    }

    public func stop() {

        monitor.cancel()

        continuation?
            .finish()

        continuation =
            nil
    }

    public func snapshot()
        -> ConnectivityEnvironment?
    {
        guard
            let path =
                currentPath
        else {
            return nil
        }

        return Self.environment(
            from:
                path
        )
    }

    private func handle(
        _ path:
            NWPath
    ) {

        currentPath =
            path

        continuation?
            .yield(
                Self.environment(
                    from:
                        path
                )
            )
    }

    private static func environment(
        from path:
            NWPath
    )
        -> ConnectivityEnvironment
    {
        let status:
            ConnectivityStatus

        switch path.status {

        case .satisfied:
            status =
                path.isConstrained
                ? .constrained
                : .available

        case .unsatisfied,
             .requiresConnection:
            status =
                .unavailable

        @unknown default:
            status =
                .unavailable
        }

        var interfaces =
            Set<ConnectivityInterface>()

        if path.usesInterfaceType(
            .wifi
        ) {
            interfaces.insert(
                .wifi
            )
        }

        if path.usesInterfaceType(
            .cellular
        ) {
            interfaces.insert(
                .cellular
            )
        }

        if path.usesInterfaceType(
            .wiredEthernet
        ) {
            interfaces.insert(
                .wiredEthernet
            )
        }

        if path.usesInterfaceType(
            .loopback
        ) {
            interfaces.insert(
                .loopback
            )
        }

        if interfaces.isEmpty {
            interfaces.insert(
                .unknown
            )
        }

        return ConnectivityEnvironment(
            status:
                status,
            interfaces:
                interfaces,
            isExpensive:
                path.isExpensive,
            isConstrained:
                path.isConstrained,
            supportsIPv4:
                path.supportsIPv4,
            supportsIPv6:
                path.supportsIPv6
        )
    }
}
```

