# 9. Policy Engine

```swift
public actor ConnectivityPolicyEngine {

    public init() {}

    public func evaluate(
        environment:
            ConnectivityEnvironment,
        policy:
            ConnectivityPolicy
    )
        -> ConnectivityPolicyDecision
    {
        guard
            environment.status !=
            .unavailable
        else {

            return ConnectivityPolicyDecision(
                decision:
                    policy.requireConnectivity
                    ? .defer
                    : .execute,
                reason:
                    "No usable network path"
            )
        }

        if environment.isConstrained &&
            !policy.allowConstrainedNetwork {

            switch policy.workload {

            case .critical,
                 .interactive:
                return ConnectivityPolicyDecision(
                    decision:
                        .executeReduced,
                    reason:
                        "Constrained path"

                )

            default:
                return ConnectivityPolicyDecision(
                    decision:
                        .defer,
                    reason:
                        "Constrained path"
                )
            }
        }

        if environment.isExpensive &&
            !policy.allowExpensiveNetwork {

            switch policy.workload {

            case .critical,
                 .interactive:

                return ConnectivityPolicyDecision(
                    decision:
                        .executeReduced,
                    reason:
                        "Expensive path"
                )

            default:

                return ConnectivityPolicyDecision(
                    decision:
                        .defer,
                    reason:
                        "Expensive path"
                )
            }
        }

        return ConnectivityPolicyDecision(
            decision:
                .execute,
            reason:
                "Network policy permits operation"
        )
    }
}
```

