# 11. Bonjour Browser

```swift
public actor BonjourServiceBrowser {

    private var browser:
        NWBrowser?

    private var continuation:
        AsyncStream<
            [DiscoveredService]
        >.Continuation?

    public init() {}

    public func start(
        serviceType:
            String,
        domain:
            String? = nil
    )
        -> AsyncStream<
            [DiscoveredService]
        >
    {
        let stream =
            AsyncStream<
                [DiscoveredService]
            > {
                continuation in

                self.continuation =
                    continuation

                let descriptor =
                    NWBrowser.Descriptor
                        .bonjour(
                            type:
                                serviceType,
                            domain:
                                domain
                        )

                let parameters =
                    NWParameters()

                let browser =
                    NWBrowser(
                        for:
                            descriptor,
                        using:
                            parameters
                    )

                self.browser =
                    browser

                browser.browseResultsChangedHandler = {
                    [weak self]
                    results,
                    _ in

                    let services =
                        results.compactMap {
                            result
                            -> DiscoveredService?
                            in

                            guard
                                case let
                                .service(
                                    name,
                                    type,
                                    domain,
                                    _
                                ) =
                                    result.endpoint
                            else {
                                return nil
                            }

                            return DiscoveredService(
                                name:
                                    name,
                                type:
                                    type,
                                domain:
                                    domain
                            )
                        }

                    Task {

                        await self?
                            .publish(
                                services
                            )
                    }
                }

                browser.start(
                    queue:
                        .main
                )
            }

        return stream
    }

    public func stop() {

        browser?
            .cancel()

        browser =
            nil

        continuation?
            .finish()

        continuation =
            nil
    }

    private func publish(
        _ services:
            [DiscoveredService]
    ) {
        continuation?
            .yield(
                services
            )
    }
}
```

