# 15. Managed Network Connection

```swift
public actor ManagedNetworkConnection {

    public let id:
        UUID

    private let endpoint:
        ServiceEndpoint

    private var connection:
        NWConnection?

    private var state:
        AdvancedConnectionState =
            .idle

    public init(
        endpoint:
            ServiceEndpoint
    ) {
        self.id =
            UUID()

        self.endpoint =
            endpoint
    }

    public func start()
        async throws
    {
        guard
            state == .idle
        else {
            return
        }

        state =
            .preparing

        guard
            let port =
                NWEndpoint.Port(
                    rawValue:
                        endpoint.port
                )
        else {

            state =
                .failed

            throw AdvancedConnectionError
                .invalidEndpoint
        }

        let host =
            NWEndpoint.Host(
                endpoint.host
            )

        let connection =
            NWConnection(
                host:
                    host,
                port:
                    port,
                using:
                    .tcp
            )

        self.connection =
            connection

        state =
            .connecting

        try await withCheckedThrowingContinuation {
            continuation
                in

            connection.stateUpdateHandler = {
                [weak self]
                newState in

                Task {

                    switch newState {

                    case .ready:

                        await self?
                            .setReady()

                        continuation.resume()

                    case .failed:

                        await self?
                            .setFailed()

                        continuation.resume(
                            throwing:
                                AdvancedConnectionError
                                    .connectionFailed
                        )

                    case .cancelled:

                        await self?
                            .setCancelled()

                        continuation.resume(
                            throwing:
                                AdvancedConnectionError
                                    .cancelled
                        )

                    default:
                        break
                    }
                }
            }

            connection.start(
                queue:
                    .global(
                        qos:
                            .userInitiated
                    )
            )
        }
    }

    public func send(
        _ data:
            Data
    )
        async throws
    {
        guard
            state == .ready,
            let connection
        else {
            throw AdvancedConnectionError
                .unavailable
        }

        try await withCheckedThrowingContinuation {
            continuation
                in

            connection.send(
                content:
                    data,
                completion:
                    .contentProcessed {
                        error in

                        if let error {

                            continuation.resume(
                                throwing:
                                    error
                            )

                        } else {

                            continuation.resume()
                        }
                    }
            )
        }
    }

    public func cancel() {

        connection?
            .cancel()

        state =
            .cancelled
    }

    public func currentState()
        -> AdvancedConnectionState
    {
        state
    }

    private func setReady() {
        state =
            .ready
    }

    private func setFailed() {
        state =
            .failed
    }

    private func setCancelled() {
        state =
            .cancelled
    }
}
```

