# 16. Connection Pool

```swift
public actor ConnectionPool {

    private var connections:
        [
            UUID:
            ManagedNetworkConnection
        ] = [:]

    public init() {}

    public func add(
        _ connection:
            ManagedNetworkConnection
    ) {
        connections[
            connection.id
        ] =
            connection
    }

    public func remove(
        _ id:
            UUID
    ) {

        connections[id] =
            nil
    }

    public func connection(
        _ id:
            UUID
    )
        -> ManagedNetworkConnection?
    {
        connections[id]
    }

    public func cancelAll() {

        for connection
            in connections.values {

            Task {
                await connection.cancel()
            }
        }

        connections.removeAll()
    }

    public func count()
        -> Int
    {
        connections.count
    }
}
```

