public actor ConnectivityDiagnostics {

    private var metrics =
        ConnectivityMetrics()

    public init() {}

    public func pathChanged() {

        metrics.pathChanges += 1

        metrics.lastPathChange =
            Date()
    }

    public func discoveredService() {

        metrics.servicesDiscovered += 1
    }

    public func connectionAttempt() {

        metrics.connectionAttempts += 1
    }

    public func connectionFailure() {

        metrics.connectionFailures += 1
    }

    public func sent(
        bytes:
            Int
    ) {

        metrics.bytesSent +=
            UInt64(
                max(
                    0,
                    bytes
                )
            )
    }

    public func received(
        bytes:
            Int
    ) {

        metrics.bytesReceived +=
            UInt64(
                max(
                    0,
                    bytes
                )
            )
    }

    public func snapshot()
        -> ConnectivityMetrics
    {
        metrics
    }
}
```

