# 25. Advanced Connectivity Runtime

```swift
public actor AdvancedConnectivityRuntime {

    public static let shared =
        AdvancedConnectivityRuntime()

    private let pathMonitor:
        ConnectivityPathMonitor

    private let policyEngine:
        ConnectivityPolicyEngine

    private let serviceBrowser:
        BonjourServiceBrowser

    private let connectionPool:
        ConnectionPool

    private let eventBus:
        ConnectivityEventBus

    private let diagnostics:
        ConnectivityDiagnostics

    private var running =
        false

    private var monitorTask:
        Task<Void, Never>?

    private init() {

        pathMonitor =
            ConnectivityPathMonitor()

        policyEngine =
            ConnectivityPolicyEngine()

        serviceBrowser =
            BonjourServiceBrowser()

        connectionPool =
            ConnectionPool()

        eventBus =
            ConnectivityEventBus()

        diagnostics =
            ConnectivityDiagnostics()
    }

    public func start() {

        guard !running else {
            return
        }

        running =
            true

        let stream =
            pathMonitor.start()

        monitorTask =
            Task {

                for await environment
                    in stream {

                    await diagnostics
                        .pathChanged()

                    await eventBus
                        .publish(
                            .pathChanged(
                                environment
                            )
                        )
                }
            }
    }

    public func stop() {

        guard running else {
            return
        }

        running =
            false

        monitorTask?
            .cancel()

        monitorTask =
            nil

        Task {

            await pathMonitor.stop()

            await connectionPool
                .cancelAll()
        }
    }

    public func environment()
        -> ConnectivityEnvironment?
    {
        nil
    }

    public func evaluate(
        policy:
            ConnectivityPolicy
    ) async
        -> ConnectivityPolicyDecision?
    {
        guard
            let environment =
                await pathMonitor.snapshot()
        else {
            return nil
        }

        return await policyEngine.evaluate(
            environment:
                environment,
            policy:
                policy
        )
    }

    public func events()
        -> AsyncStream<ConnectivityEvent>
    {
        eventBus.stream()
    }

    public func metrics()
        async
        -> ConnectivityMetrics
    {
        await diagnostics.snapshot()
    }

    public func addConnection(
        _ connection:
            ManagedNetworkConnection
    ) async {

        await connectionPool.add(
            connection
        )
    }

    public func connectionCount()
        async
        -> Int
    {
        await connectionPool.count()
    }
}
```

