# 23. Attestation Runtime

```swift
public actor DeviceAttestationRuntime {

    public static let shared =
        DeviceAttestationRuntime()

    private var configuration:
        AttestationConfiguration?

    private var provider:
        AppAttestProvider?

    private var state:
        AttestationState =
            .unavailable

    private var session:
        AttestationSession?

    private var lastAttestation:
        Date?

    private var lastAssertion:
        Date?

    private var failedOperations:
        UInt64 = 0

    private init() {}

    public func configure(
        _ configuration:
            AttestationConfiguration
    ) {

        self.configuration =
            configuration

        provider =
            AppAttestProvider(
                configuration:
                    configuration
            )

        state =
            .checking
    }

    public func start()
        async
    {
        guard
            let provider
        else {
            state =
                .unavailable
            return
        }

        guard
            await AppAttestAvailability()
                .isSupported()
        else {
            state =
                .unsupported
            return
        }

        do {

            let key =
                try await provider
                    .ensureKey()

            state =
                .keyReady

            session =
                AttestationSession(
                    keyID:
                        key,
                    expiresAt:
                        Date()
                            .addingTimeInterval(
                                300
                            )
                )

        } catch {

            failedOperations += 1

            state =
                .failed
        }
    }

    public func createAttestation(
        challenge:
            AttestationChallenge
    )
        async throws
        -> AttestationPayload
    {
        guard
            let provider
        else {
            throw AttestationError
                .unavailable
        }

        do {

            state =
                .checking

            let payload =
                try await provider
                    .attest(
                        challenge:
                            challenge
                    )

            lastAttestation =
                Date()

            state =
                .attested

            return payload

        } catch {

            failedOperations += 1

            state =
                .failed

            throw error
        }
    }

    public func createAssertion(
        challenge:
            AttestationChallenge
    )
        async throws
        -> AssertionPayload
    {
        guard
            let provider
        else {
            throw AttestationError
                .unavailable
        }

        do {

            let payload =
                try await provider
                    .assertion(
                        challenge:
                            challenge
                    )

            lastAssertion =
                Date()

            state =
                .assertionReady

            return payload

        } catch {

            failedOperations += 1

            state =
                .failed

            throw error
        }
    }

    public func snapshot()
        -> AttestationRuntimeSnapshot
    {
        AttestationRuntimeSnapshot(
            state:
                state,
            keyID:
                session?.keyID,
            session:
                session,
            lastAttestation:
                lastAttestation,
            lastAssertion:
                lastAssertion,
            failedOperations:
                failedOperations
        )
    }
}
```

