# 31. AI Router

```swift
public actor AIRouter {

    private let governor:
        AIGovernor

    public init(
        governor:
            AIGovernor
    ) {
        self.governor =
            governor
    }

    public func route(
        _ request:
            AIRequest
    )
        async
        -> AIRoutingDecision
    {
        let budget =
            await governor.budget(
                for:
                    request.priority
            )

        switch request.preferredLocation {

        case .onDevice:

            return AIRoutingDecision(
                location:
                    .onDevice,
                reason:
                    "Explicit local execution policy.",
                budget:
                    budget
            )

        case .privateCloudCompute:

            guard budget.allowCloud else {

                return AIRoutingDecision(
                    location:
                        .onDevice,
                    reason:
                        "Cloud execution prohibited by workload policy.",
                    budget:
                        budget
                )
            }

            return AIRoutingDecision(
                location:
                    .privateCloudCompute,
                reason:
                    "Private Cloud Compute requested.",
                budget:
                    budget
            )

        case .applicationServer:

            guard budget.allowNetwork else {

                return AIRoutingDecision(
                    location:
                        .onDevice,
                    reason:
                        "Network execution prohibited by workload policy.",
                    budget:
                        budget
                )
            }

            return AIRoutingDecision(
                location:
                    .applicationServer,
                reason:
                    "Application server execution requested.",
                budget:
                    budget
            )

        case .automatic:

            if request.priority ==
                .realtime
            {
                return AIRoutingDecision(
                    location:
                        .onDevice,
                    reason:
                        "Realtime workload prefers local execution.",
                    budget:
                        budget
                )
            }

            if budget.allowCloud {

                return AIRoutingDecision(
                    location:
                        .onDevice,
                    reason:
                        "Local-first automatic policy.",
                    budget:
                        budget
                )
            }

            return AIRoutingDecision(
                location:
                    .onDevice,
                reason:
                    "Only local execution permitted.",
                budget:
                    budget
            )
        }
    }
}
```

