# 35. Advanced AI Engine

```swift
public actor AdvancedAIRuntime {

    public static let shared =
        AdvancedAIRuntime()

    private let registry:
        AIModelRegistry

    private let governor:
        AIGovernor

    private let router:
        AIRouter

    private let toolRegistry:
        AIToolRegistry

    private let contextStore:
        AIContextStore

    private var running:
        Bool = false

    private var requestCount:
        UInt64 = 0

    private var failureCount:
        UInt64 = 0

    private var totalLatency:
        Duration = .zero

    private init() {

        let governor =
            AIGovernor()

        self.governor =
            governor

        registry =
            AIModelRegistry()

        router =
            AIRouter(
                governor:
                    governor
            )

        toolRegistry =
            AIToolRegistry()

        contextStore =
            AIContextStore()
    }

    public func start() {

        running =
            true

        AILog.info(
            "Advanced AI runtime started."
        )
    }

    public func stop() {

        running =
            false

        AILog.info(
            "Advanced AI runtime stopped."
        )
    }

    public func register(
        model:
            AIModelDescriptor
    )
        async
    {
        await registry.register(
            model
        )
    }

    public func execute(
        _ request:
            AIRequest
    )
        async throws
        -> AIResult
    {
        guard running else {
            throw AIRuntimeError
                .unavailable
        }

        let decision =
            await router.route(
                request
            )

        let start =
            ContinuousClock
                .now

        requestCount += 1

        do {

            let result =
                try await executeInternal(
                    request:
                        request,
                    decision:
                        decision
                )

            let elapsed =
                ContinuousClock
                    .now
                    .duration(
                        since:
                            start
                    )

            totalLatency +=
                elapsed

            return AIResult(
                requestID:
                    request.id,
                location:
                    result.location,
                text:
                    result.text,
                structuredData:
                    result.structuredData,
                latency:
                    elapsed,
                tokenCount:
                    result.tokenCount
            )

        } catch {

            failureCount += 1

            throw error
        }
    }

    private func executeInternal(
        request:
            AIRequest,
        decision:
            AIRoutingDecision
    )
        async throws
        -> AIResult
    {
        switch decision.location {

        case .onDevice:

            return try await executeOnDevice(
                request
            )

        case .privateCloudCompute:

            return try await executeCloud(
                request,
                location:
                    .privateCloudCompute
            )

        case .applicationServer:

            return try await executeCloud(
                request,
                location:
                    .applicationServer
            )

        case .automatic:

            return try await executeOnDevice(
                request
            )
        }
    }

    private func executeOnDevice(
        _ request:
            AIRequest
    )
        async throws
        -> AIResult
    {
        #if canImport(FoundationModels)

        if request.workload ==
            .textGeneration ||
            request.workload ==
            .summarization ||
            request.workload ==
            .extraction ||
            request.workload ==
            .reasoning
        {
            let adapter =
                FoundationModelAdapter()

            try await adapter.start()

            let output =
                try await adapter.generate(
                    prompt:
                        request.prompt ??
                        ""
                )

            return AIResult(
                requestID:
                    request.id,
                location:
                    .onDevice,
                text:
                    output,
                latency:
                    .zero
            )
        }

        #endif

        throw AIRuntimeError
            .unsupported
    }

    private func executeCloud(
        _ request:
            AIRequest,
        location:
            AIExecutionLocation
    )
        async throws
        -> AIResult
    {
        throw AIRuntimeError
            .cloudUnavailable
    }

    public func snapshot()
        -> AdvancedAISnapshot
    {
        AdvancedAISnapshot(
            running:
                running,
            requests:
                requestCount,
            failures:
                failureCount,
            averageLatency:
                requestCount > 0
                ? totalLatency /
                    requestCount
                : .zero
        )
    }
}
```

The cloud branch is deliberately an integration boundary rather than a fabricated Apple API.

