# 9. Location Controller Boundary

Core Location delegates are kept behind an isolated boundary.

```swift
@MainActor
public final class LocationDelegateBridge:
    NSObject,
    CLLocationManagerDelegate
{
    private let manager:
        CLLocationManager

    public var onLocation:
        (([CLLocation]) -> Void)?

    public var onAuthorization:
        ((CLAuthorizationStatus) -> Void)?

    public var onError:
        ((Error) -> Void)?

    public init(
        manager:
            CLLocationManager
    ) {
        self.manager =
            manager

        super.init()

        manager.delegate =
            self
    }

    public func locationManager(
        _ manager:
            CLLocationManager,
        didUpdateLocations locations:
            [CLLocation]
    ) {
        onLocation?(
            locations
        )
    }

    public func locationManager(
        _ manager:
            CLLocationManager,
        didFailWithError error:
            Error
    ) {
        onError?(
            error
        )
    }

    public func locationManagerDidChangeAuthorization(
        _ manager:
            CLLocationManager
    ) {
        onAuthorization?(
            manager.authorizationStatus
        )
    }
}
```

The UIKit/Core Location object remains on the main actor instead of being passed through arbitrary actors.

---

# 10. Location Runtime

```swift
@MainActor
public final class LocationRuntime {

    public static let shared =
        LocationRuntime()

    private let manager:
        CLLocationManager

    private var bridge:
        LocationDelegateBridge?

    private(set) public var authorization:
        LocationAuthorization =
            .notDetermined

    private(set) public var latest:
        LocationObservation?

    private(set) public var running:
        Bool = false

    private var configuration:
        LocationConfiguration

    private init() {

        manager =
            CLLocationManager()

        configuration =
            LocationConfiguration()

        bridge =
            LocationDelegateBridge(
                manager:
                    manager
            )

        bridge?.onLocation =
            { [weak self] locations in

                self?.receive(
                    locations
                )
            }

        bridge?.onAuthorization =
            { [weak self] status in

                self?.updateAuthorization(
                    status
                )
            }

        bridge?.onError =
            { [weak self] error in

                self?.handle(
                    error
                )
            }

        updateAuthorization(
            manager.authorizationStatus
        )
    }

    public func configure(
        _ configuration:
            LocationConfiguration
    ) {
        self.configuration =
            configuration

        manager.desiredAccuracy =
            configuration.desiredAccuracy

        manager.distanceFilter =
            configuration.distanceFilter

        manager.pausesLocationUpdatesAutomatically =
            configuration.pausesAutomatically

        switch configuration.activityType {

        case .automotiveNavigation:
            manager.activityType =
                .automotiveNavigation

        case .fitness:
            manager.activityType =
                .fitness

        case .otherNavigation:
            manager.activityType =
                .otherNavigation

        case .other:
            manager.activityType =
                .other
        }
    }

    public func requestPermission() {

        manager.requestWhenInUseAuthorization()
    }

    public func start() {

        guard
            authorization ==
                .authorizedWhenInUse ||
            authorization ==
                .authorizedAlways
        else {
            requestPermission()
            return
        }

        manager.startUpdatingLocation()

        running =
            true
    }

    public func stop() {

        manager.stopUpdatingLocation()

        running =
            false
    }

    private func receive(
        _ locations:
            [CLLocation]
    ) {

        guard
            let location =
                locations.last
        else {
            return
        }

        guard
            location.coordinate.latitude
                .isFinite,
            location.coordinate.longitude
                .isFinite
        else {
            return
        }

        let quality =
            Self.quality(
                accuracy:
                    location.horizontalAccuracy
            )

        latest =
            LocationObservation(
                coordinate:
                    GeoCoordinate(
                        latitude:
                            location.coordinate.latitude,
                        longitude:
                            location.coordinate.longitude,
                        altitude:
                            location.altitude
                    ),
                horizontalAccuracy:
                    location.horizontalAccuracy,
                verticalAccuracy:
                    location.verticalAccuracy,
                speed:
                    location.speed >= 0
                    ? location.speed
                    : nil,
                course:
                    location.course >= 0
                    ? location.course
                    : nil,
                timestamp:
                    location.timestamp,
                quality:
                    quality
            )
    }

    private func updateAuthorization(
        _ status:
            CLAuthorizationStatus
    ) {

        switch status {

        case .notDetermined:
            authorization =
                .notDetermined

        case .restricted:
            authorization =
                .restricted

        case .denied:
            authorization =
                .denied

        case .authorizedWhenInUse:
            authorization =
                .authorizedWhenInUse

        case .authorizedAlways:
            authorization =
                .authorizedAlways

        @unknown default:
            authorization =
                .denied
        }
    }

    private func handle(
        _ error:
            Error
    ) {
        GeoLog.error(
            "Location error: \(error.localizedDescription)"
        )
    }

    private static func quality(
        accuracy:
            Double
    )
        -> LocationQuality
    {
        if accuracy < 0 {
            return .unavailable
        }

        if accuracy <= 5 {
            return .excellent
        }

        if accuracy <= 25 {
            return .good
        }

        if accuracy <= 100 {
            return .approximate
        }

        return .poor
    }
}
```

