# 13. Bearing Engine

```swift
public enum GeoBearing {

    public static func degrees(
        from:
            GeoCoordinate,
        to:
            GeoCoordinate
    )
        -> Double
    {
        let lat1 =
            from.latitude
            .radians

        let lat2 =
            to.latitude
            .radians

        let delta =
            (
                to.longitude -
                from.longitude
            )
            .radians

        let y =
            sin(delta) *
            cos(lat2)

        let x =
            cos(lat1) *
            sin(lat2)
            -
            sin(lat1) *
            cos(lat2) *
            cos(delta)

        let bearing =
            atan2(
                y,
                x
            )
            .degrees

        return (
            bearing +
            360
        )
        .truncatingRemainder(
            dividingBy:
                360
        )
    }
}

private extension Double {

    var radians:
        Double
    {
        self *
            .pi /
            180
    }

    var degrees:
        Double
    {
        self *
            180 /
            .pi
    }
}
```

