# 14. Bounding Box

```swift
public struct GeoBoundingBox:
    Codable,
    Sendable,
    Hashable
{
    public let minimumLatitude:
        Double

    public let minimumLongitude:
        Double

    public let maximumLatitude:
        Double

    public let maximumLongitude:
        Double

    public init(
        minimumLatitude:
            Double,
        minimumLongitude:
            Double,
        maximumLatitude:
            Double,
        maximumLongitude:
            Double
    ) {
        self.minimumLatitude =
            minimumLatitude

        self.minimumLongitude =
            minimumLongitude

        self.maximumLatitude =
            maximumLatitude

        self.maximumLongitude =
            maximumLongitude
    }

    public func contains(
        _ coordinate:
            GeoCoordinate
    )
        -> Bool
    {
        coordinate.latitude >=
            minimumLatitude
        &&
        coordinate.latitude <=
            maximumLatitude
        &&
        coordinate.longitude >=
            minimumLongitude
        &&
        coordinate.longitude <=
            maximumLongitude
    }
}
