# 18. Geocoder

```swift
public actor GeoCoder {

    private let geocoder:
        CLGeocoder

    public init() {

        geocoder =
            CLGeocoder()
    }

    public func reverseGeocode(
        coordinate:
            GeoCoordinate
    )
        async throws
        -> GeoAddress
    {
        guard
            GeoCoordinateValidator
                .isValid(
                    coordinate
                )
        else {
            throw GeoRuntimeError
                .invalidCoordinate
        }

        let placemarks =
            try await geocoder
                .reverseGeocodeLocation(
                    coordinate.clLocation
                )

        guard
            let place =
                placemarks.first
        else {
            throw GeoRuntimeError
                .geocodingFailed
        }

        return GeoAddress(
            name:
                place.name,
            street:
                place.thoroughfare,
            locality:
                place.locality,
            administrativeArea:
                place.administrativeArea,
            postalCode:
                place.postalCode,
            country:
                place.country
        )
    }
}
```

