# 22. Map Search Engine

```swift
public actor GeoSearchEngine {

    public init() {}

    public func search(
        _ request:
            GeoSearchRequest
    )
        async throws
        -> [GeoPlace]
    {
        let search =
            MKLocalSearch.Request()

        search.naturalLanguageQuery =
            request.query

        if let region =
            request.region {

            search.region =
                MKCoordinateRegion(
                    center:
                        CLLocationCoordinate2D(
                            latitude:
                                (
                                    region.minimumLatitude +
                                    region.maximumLatitude
                                ) / 2,
                            longitude:
                                (
                                    region.minimumLongitude +
                                    region.maximumLongitude
                                ) / 2
                        ),
                    span:
                        MKCoordinateSpan(
                            latitudeDelta:
                                max(
                                    0.001,
                                    region.maximumLatitude -
                                    region.minimumLatitude
                                ),
                            longitudeDelta:
                                max(
                                    0.001,
                                    region.maximumLongitude -
                                    region.minimumLongitude
                                )
                        )
                )
        }

        let response =
            try await MKLocalSearch(
                request:
                    search
            )
            .start()

        return response.mapItems
            .prefix(
                request.resultLimit
            )
            .map { item in

                GeoPlace(
                    name:
                        item.name ??
                        "Unknown",
                    coordinate:
                        GeoCoordinate(
                            latitude:
                                item.placemark
                                    .coordinate
                                    .latitude,
                            longitude:
                                item.placemark
                                    .coordinate
                                    .longitude
                        ),
                    address:
                        GeoAddress(
                            name:
                                item.placemark.name,
                            street:
                                item.placemark.thoroughfare,
                            locality:
                                item.placemark.locality,
                            administrativeArea:
                                item.placemark.administrativeArea,
                            postalCode:
                                item.placemark.postalCode,
                            country:
                                item.placemark.country
                        )
                )
            }
    }
}
```

