# 26. Route Engine

```swift
public actor GeoRouteEngine {

    public init() {}

    public func calculate(
        _ request:
            GeoRouteRequest
    )
        async throws
        -> GeoRoute
    {
        guard
            GeoCoordinateValidator
                .isValid(
                    request.source
                ),
            GeoCoordinateValidator
                .isValid(
                    request.destination
                )
        else {
            throw GeoRuntimeError
                .invalidCoordinate
        }

        let source =
            MKMapItem(
                location:
                    CLLocation(
                        latitude:
                            request.source.latitude,
                        longitude:
                            request.source.longitude
                    )
            )

        let destination =
            MKMapItem(
                location:
                    CLLocation(
                        latitude:
                            request.destination.latitude,
                        longitude:
                            request.destination.longitude
                    )
            )

        let directions =
            MKDirections(
                request:
                    {
                        let request =
                            MKDirections.Request()

                        request.source =
                            source

                        request.destination =
                            destination

                        switch request.transport {

                        case .automobile:
                            request.transportType =
                                .automobile

                        case .walking:
                            request.transportType =
                                .walking

                        case .cycling:
                            request.transportType =
                                .cycling

                        case .transit:
                            request.transportType =
                                .transit
                        }

                        request.requestsAlternateRoutes =
                            false

                        return request
                    }()
            )

        let response =
            try await directions
                .calculate()

        guard
            let route =
                response.routes.first
        else {
            throw GeoRuntimeError
                .routeUnavailable
        }

        let points =
            route.polyline
                .coordinates()

        return GeoRoute(
            distanceMeters:
                route.distance,
            expectedTravelSeconds:
                route.expectedTravelTime,
            polyline:
                points
        )
    }
}
```

