# 39. Geospatial Runtime

```swift
public actor AdvancedGeoRuntime {

    public static let shared =
        AdvancedGeoRuntime()

    private let search:
        GeoSearchEngine

    private let routes:
        GeoRouteEngine

    private let geocoder:
        GeoCoder

    private let spatialIndex:
        GeoSpatialIndex

    private let privacy:
        GeoPrivacyReducer

    private let power:
        GeoPowerPolicy

    private let events:
        GeoEventBus

    private var running:
        Bool = false

    private var locationUpdates:
        UInt64 = 0

    private var routeRequests:
        UInt64 = 0

    private var searchRequests:
        UInt64 = 0

    private init() {

        search =
            GeoSearchEngine()

        routes =
            GeoRouteEngine()

        geocoder =
            GeoCoder()

        spatialIndex =
            GeoSpatialIndex()

        privacy =
            GeoPrivacyReducer()

        power =
            GeoPowerPolicy()

        events =
            GeoEventBus()
    }

    public func start() {

        running =
            true

        GeoLog.info(
            "Geospatial runtime started."
        )
    }

    public func stop() {

        running =
            false

        GeoLog.info(
            "Geospatial runtime stopped."
        )
    }

    public func searchPlaces(
        _ request:
            GeoSearchRequest
    )
        async throws
        -> [GeoPlace]
    {
        guard running else {
            throw GeoRuntimeError
                .unavailable
        }

        searchRequests += 1

        let results =
            try await search.search(
                request
            )

        await events.publish(
            .searchCompleted(
                results.count
            )
        )

        return results
    }

    public func route(
        _ request:
            GeoRouteRequest
    )
        async throws
        -> GeoRoute
    {
        guard running else {
            throw GeoRuntimeError
                .unavailable
        }

        routeRequests += 1

        let route =
            try await routes.calculate(
                request
            )

        await events.publish(
            .routeUpdated(
                route
            )
        )

        return route
    }

    public func reverseGeocode(
        coordinate:
            GeoCoordinate
    )
        async throws
        -> GeoAddress
    {
        guard running else {
            throw GeoRuntimeError
                .unavailable
        }

        return try await geocoder
            .reverseGeocode(
                coordinate:
                    coordinate
            )
    }

    public func addPoint(
        _ point:
            GeoPoint
    )
        async
    {
        await spatialIndex.insert(
            point
        )
    }

    public func nearest(
        coordinate:
            GeoCoordinate,
        limit:
            Int = 10
    )
        async
        -> [GeoPoint]
    {
        await spatialIndex.nearest(
            to:
                coordinate,
            limit:
                limit
        )
    }

    public func snapshot()
        async
        -> GeoRuntimeSnapshot
    {
        GeoRuntimeSnapshot(
            running:
                running,
            locationUpdates:
                locationUpdates,
            routeRequests:
                routeRequests,
            searchRequests:
                searchRequests
        )
    }
}
```

