# 55. Testing

```swift
import XCTest

final class GeoRuntimeTests:
    XCTestCase
{
    func testCoordinateValidation() {

        let valid =
            GeoCoordinate(
                latitude:
                    53.8,
                longitude:
                    -1.55
            )

        XCTAssertTrue(
            GeoCoordinateValidator
                .isValid(
                    valid
                )
        )
    }

    func testInvalidLatitude() {

        let invalid =
            GeoCoordinate(
                latitude:
                    100,
                longitude:
                    0
            )

        XCTAssertFalse(
            GeoCoordinateValidator
                .isValid(
                    invalid
                )
        )
    }

    func testDistance() {

        let london =
            GeoCoordinate(
                latitude:
                    51.5074,
                longitude:
                    -0.1278
            )

        let manchester =
            GeoCoordinate(
                latitude:
                    53.4808,
                longitude:
                    -2.2426
            )

        let distance =
            GeoDistance.kilometers(
                from:
                    london,
                to:
                    manchester
            )

        XCTAssertGreaterThan(
            distance,
            250
        )

        XCTAssertLessThan(
            distance,
            350
        )
    }

    func testBearing() {

        let origin =
            GeoCoordinate(
                latitude:
                    0,
                longitude:
                    0
            )

        let north =
            GeoCoordinate(
                latitude:
                    1,
                longitude:
                    0
            )

        let bearing =
            GeoBearing.degrees(
                from:
                    origin,
                to:
                    north
            )

        XCTAssertEqual(
            bearing,
            0,
            accuracy:
                0.001
        )
    }
}
```

