# 13. Search Engine

```swift
public actor SearchEngine {

    private let index:
        SearchIndex

    private let tokenizer:
        SearchTokenizer

    private let normalizer:
        SearchNormalizer

    private let scorer:
        SearchScorer

    public init(
        index:
            SearchIndex
    ) {
        self.index =
            index

        tokenizer =
            SearchTokenizer()

        normalizer =
            SearchNormalizer()

        scorer =
            SearchScorer()
    }

    public func search(
        _ query:
            SearchQuery
    )
        async
        -> [SearchResult]
    {
        let queryTokens =
            tokenizer
                .tokenize(
                    query.text
                )
                .map {
                    normalizer.normalize(
                        $0
                    )
                }

        guard
            !queryTokens.isEmpty
        else {
            return []
        }

        var candidates:
            Set<String> = []

        for token in
            queryTokens
        {
            candidates.formUnion(
                await index
                    .candidateIDs(
                        for:
                            token
                    )
            )
        }

        var results:
            [SearchResult] = []

        for id in
            candidates
        {
            guard
                let document =
                    await index.document(
                        id:
                            id
                    )
            else {
                continue
            }

            guard
                query.domains.contains(
                    .all
                )
                ||
                query.domains.contains(
                    document.domain
                )
            else {
                continue
            }

            let result =
                scorer.score(
                    document:
                        document,
                    queryTokens:
                        queryTokens,
                    query:
                        query
                )

            guard
                result.score > 0
            else {
                continue
            }

            results.append(
                SearchResult(
                    id:
                        document.id,
                    domain:
                        document.domain,
                    title:
                        document.title,
                    score:
                        result.score,
                    matchedTerms:
                        result.matches,
                    modifiedAt:
                        document.modifiedAt,
                    latitude:
                        document.latitude,
                    longitude:
                        document.longitude
                )
            )
        }

        return results
            .sorted {
                if $0.score !=
                    $1.score
                {
                    return $0.score >
                        $1.score
                }

                return $0.modifiedAt >
                    $1.modifiedAt
            }
            .prefix(
                query.limit
            )
            .map {
                $0
            }
    }
}
```

