# 23. Search Cache

```swift
public actor SearchCache {

    private struct Entry:
        Sendable
    {
        let result:
            [SearchResult]

        let timestamp:
            Date
    }

    private var entries:
        [String: Entry] = [:]

    private let maximumEntries:
        Int

    private let lifetime:
        TimeInterval

    public init(
        maximumEntries:
            Int = 128,
        lifetime:
            TimeInterval = 30
    ) {
        self.maximumEntries =
            maximumEntries

        self.lifetime =
            lifetime
    }

    public func get(
        key:
            String
    )
        -> [SearchResult]?
    {
        guard
            let entry =
                entries[key]
        else {
            return nil
        }

        guard
            Date()
                .timeIntervalSince(
                    entry.timestamp
                )
            <
            lifetime
        else {
            entries[
                key
            ] =
                nil

            return nil
        }

        return entry.result
    }

    public func put(
        key:
            String,
        result:
            [SearchResult]
    ) {

        if entries.count >=
            maximumEntries,
           entries[key] == nil {

            if let first =
                entries.keys.first
            {
                entries[
                    first
                ] =
                    nil
            }
        }

        entries[
            key
        ] =
            Entry(
                result:
                    result,
                timestamp:
                    Date()
            )
    }

    public func clear() {
        entries.removeAll()
    }
}
```

