# 24. Cached Search Service

```swift
public actor CachedSearchService {

    private let engine:
        SearchEngine

    private let cache:
        SearchCache

    public init(
        engine:
            SearchEngine,
        cache:
            SearchCache =
            SearchCache()
    ) {
        self.engine =
            engine

        self.cache =
            cache
    }

    public func search(
        _ query:
            SearchQuery
    )
        async
        -> [SearchResult]
    {
        let key =
            makeKey(
                query
            )

        if let cached =
            await cache.get(
                key:
                    key
            )
        {
            return cached
        }

        let result =
            await engine.search(
                query
            )

        await cache.put(
            key:
                key,
            result:
                result
        )

        return result
    }

    private func makeKey(
        _ query:
            SearchQuery
    )
        -> String
    {
        [
            query.text.lowercased(),
            query.domains
                .map {
                    $0.rawValue
                }
                .sorted()
                .joined(
                    separator:
                        ","
                ),
            String(
                query.limit
            )
        ]
        .joined(
            separator:
                "|"
        )
    }
}
```

