# 27. Runtime

```swift
public actor SearchRuntime {

    public static let shared =
        SearchRuntime()

    private let index:
        SearchIndex

    private let engine:
        SearchEngine

    private let cache:
        SearchCache

    private let cachedSearch:
        CachedSearchService

    private let indexer:
        SearchIndexer

    private let suggestions:
        SearchSuggestionStore

    private var running:
        Bool = false

    private var queryCount:
        UInt64 = 0

    private var indexedCount:
        UInt64 = 0

    private var cacheHits:
        UInt64 = 0

    private var cacheMisses:
        UInt64 = 0

    private var totalResults:
        UInt64 = 0

    private init() {

        index =
            SearchIndex()

        engine =
            SearchEngine(
                index:
                    index
            )

        cache =
            SearchCache()

        cachedSearch =
            CachedSearchService(
                engine:
                    engine,
                cache:
                    cache
            )

        indexer =
            SearchIndexer(
                index:
                    index
            )

        suggestions =
            SearchSuggestionStore()
    }

    public func start() {

        running =
            true

        SearchLog.info(
            "Search runtime started."
        )
    }

    public func stop() {

        running =
            false

        SearchLog.info(
            "Search runtime stopped."
        )
    }

    public func index(
        document:
            SearchDocument
    )
        async
    {
        guard running else {
            return
        }

        await indexer.enqueue(
            .upsert(
                document
            )
        )

        indexedCount += 1
    }

    public func delete(
        documentID:
            String
    )
        async
    {
        await indexer.enqueue(
            .delete(
                documentID
            )
        )
    }

    public func processIndex(
        batchSize:
            Int = 100
    )
        async
    {
        await indexer.process(
            batchSize:
                batchSize
        )
    }

    public func search(
        _ query:
            SearchQuery
    )
        async
        -> [SearchResult]
    {
        guard
            running
        else {
            return []
        }

        queryCount += 1

        await suggestions.record(
            query:
                query.text
        )

        let result =
            await cachedSearch.search(
                query
            )

        totalResults +=
            UInt64(
                result.count
            )

        return result
    }

    public func suggest(
        prefix:
            String
    )
        async
        -> [SearchSuggestion]
    {
        await suggestions.suggest(
            prefix:
                prefix
        )
    }

    public func clearCache()
        async
    {
        await cache.clear()
    }

    public func metrics()
        async
        -> SearchMetrics
    {
        let average =
            queryCount == 0
            ? 0
            : Double(
                totalResults
            )
            /
            Double(
                queryCount
            )

        return SearchMetrics(
            queries:
                queryCount,
            indexedDocuments:
                indexedCount,
            cacheHits:
                cacheHits,
            cacheMisses:
                cacheMisses,
            averageResultCount:
                average
        )
    }
}
```

