# 36. UI View Model

```swift
@MainActor
@Observable
public final class SearchViewModel {

    public var query:
        String = ""

    public private(set) var results:
        [SearchResult] = []

    public private(set) var suggestions:
        [SearchSuggestion] = []

    public private(set) var searching:
        Bool = false

    private var searchTask:
        Task<Void, Never>?

    public init() {}

    public func updateQuery(
        _ value:
            String
    ) {

        query =
            value

        searchTask?
            .cancel()

        guard
            !value
                .trimmingCharacters(
                    in:
                        .whitespacesAndNewlines
                )
                .isEmpty
        else {
            results =
                []

            suggestions =
                []

            return
        }

        searchTask =
            Task { [weak self] in

                guard
                    let self
                else {
                    return
                }

                let suggestions =
                    await SearchRuntime
                        .shared
                        .suggest(
                            prefix:
                                value
                        )

                guard
                    !Task.isCancelled
                else {
                    return
                }

                let results =
                    await SearchRuntime
                        .shared
                        .search(
                            SearchQuery(
                                text:
                                    value
                            )
                        )

                guard
                    !Task.isCancelled
                else {
                    return
                }

                self.suggestions =
                    suggestions

                self.results =
                    results
            }
    }

    deinit {
        searchTask?
            .cancel()
    }
}
```

