                            .font(
                                .headline
                            )

                            Text(
                                result.domain.rawValue
                            )
                            .font(
                                .caption
                            )

                            if !result
                                .matchedTerms
                                .isEmpty
                            {
                                Text(
                                    result
                                        .matchedTerms
                                        .joined(
