# 6. File Metadata

```swift
public struct FileMetadata:
    Codable,
    Sendable
{
    public let reference:
        FileReference

    public let filename:
        String

    public let fileExtension:
        String?

    public let contentType:
        String?

    public let size:
        Int64

    public let createdAt:
        Date?

    public let modifiedAt:
        Date?

    public let isDirectory:
        Bool

    public let isRegularFile:
        Bool

    public init(
        reference:
            FileReference,
        filename:
            String,
        fileExtension:
            String?,
        contentType:
            String?,
        size:
            Int64,
        createdAt:
            Date?,
        modifiedAt:
            Date?,
        isDirectory:
            Bool,
        isRegularFile:
            Bool
    ) {
        self.reference =
            reference

        self.filename =
            filename

        self.fileExtension =
            fileExtension

        self.contentType =
            contentType

        self.size =
            size

        self.createdAt =
            createdAt

        self.modifiedAt =
            modifiedAt

        self.isDirectory =
            isDirectory

        self.isRegularFile =
            isRegularFile
    }
}
