# 15. Metadata

```swift
extension FileStore {

    public func metadata(
        for reference:
            FileReference
    )
        throws
        -> FileMetadata
    {
        let url =
            try await url(
                for:
                    reference
            )

        guard
            fileManager.fileExists(
                atPath:
                    url.path
            )
        else {
            throw FileRuntimeError
                .fileNotFound
        }

        let values =
            try url.resourceValues(
                forKeys:
                    [
                        .isDirectoryKey,
                        .isRegularFileKey,
                        .fileSizeKey,
                        .creationDateKey,
                        .contentModificationDateKey,
                        .contentTypeKey
                    ]
            )

        let type =
            values.contentType?
                .identifier

        return FileMetadata(
            reference:
                reference,
            filename:
                url.lastPathComponent,
            fileExtension:
                url.pathExtension.isEmpty
                    ? nil
                    : url.pathExtension,
            contentType:
                type,
            size:
                Int64(
                    values.fileSize ?? 0
                ),
            createdAt:
                values.creationDate,
            modifiedAt:
                values.contentModificationDate,
            isDirectory:
                values.isDirectory == true,
            isRegularFile:
                values.isRegularFile == true
        )
    }
}
```

