# 30. File Indexer

```swift
public actor DocumentIndexCoordinator {

    private let events:
        DocumentEventBus

    private let search:
        SearchRuntime

    public init(
        events:
            DocumentEventBus,
        search:
            SearchRuntime =
            .shared
    ) {
        self.events =
            events

        self.search =
            search
    }

    public func observe()
        async
    {
        let stream =
            await events.stream()

        for await event in
            stream
        {
            guard
                !Task.isCancelled
            else {
                return
            }

            switch event.kind {

            case .deleted:

                await search.delete(
                    documentID:
                        event.id.rawValue
                )

            default:

                // Re-fetch metadata/content from
                // #15/#26 and enqueue an updated
                // SearchDocument here.
                break
            }
        }
    }
}
```

