    ) {
        self.reads =
            reads

        self.writes =
            writes

        self.imports =
            imports

        self.exports =
            exports

        self.deletes =
            deletes

        self.bytesRead =
            bytesRead

        self.bytesWritten =
            bytesWritten

        self.failures =
            failures
    }
}
