# 34. Runtime

```swift
public actor DocumentFileRuntime {

    public static let shared =
        DocumentFileRuntime()

    private let fileStore:
        FileStore

    private let repository:
        DocumentRepository

    private let importer:
        DocumentImporter

    private let exporter:
        DocumentExporter

    private let versions:
        DocumentVersionStore

    private let events:
        DocumentEventBus

    private var running:
        Bool = false

    private var reads:
        UInt64 = 0

    private var writes:
        UInt64 = 0

    private var imports:
        UInt64 = 0

    private var exports:
        UInt64 = 0

    private var deletes:
        UInt64 = 0

    private var bytesRead:
        UInt64 = 0

    private var bytesWritten:
        UInt64 = 0

    private var failures:
        UInt64 = 0

    private init() {

        let store =
            FileStore()

        fileStore =
            store

        repository =
            DocumentRepository(
                fileStore:
                    store
            )

        importer =
            DocumentImporter(
                fileStore:
                    store
            )

        exporter =
            DocumentExporter(
                fileStore:
                    store
            )

        versions =
            DocumentVersionStore()

        events =
            DocumentEventBus()
    }

    public func start() {

        running =
            true

        FileRuntimeLog.info(
            "Document/file runtime started."
        )
    }

    public func stop() {

        running =
            false

        FileRuntimeLog.info(
            "Document/file runtime stopped."
        )
    }

    public func read(
        _ reference:
            FileReference
    )
        throws
        -> Data
    {
        guard running else {
            throw FileRuntimeError
                .runtimeNotStarted
        }

        do {

            let data =
                try await fileStore.read(
                    reference
                )

            reads += 1

            bytesRead +=
                UInt64(
                    data.count
                )

            return data

        }
        catch {

            failures += 1

            throw error
        }
    }

    public func write(
        _ data:
            Data,
        to reference:
            FileReference
    )
        throws
    {
        guard running else {
            throw FileRuntimeError
                .runtimeNotStarted
        }

        do {

            try await fileStore.write(
                data,
                to:
                    reference
            )

            writes += 1

            bytesWritten +=
                UInt64(
                    data.count
                )

            await events.publish(
                DocumentChangeEvent(
                    id:
                        reference.id,
                    kind:
                        .modified
                )
            )

        }
        catch {

            failures += 1

            throw error
        }
    }

    public func delete(
        _ reference:
            FileReference
    )
        throws
    {
        try await fileStore.delete(
            reference
        )

        deletes += 1

        await versions.remove(
            reference.id
        )

        await events.publish(
            DocumentChangeEvent(
                id:
                    reference.id,
                kind:
                    .deleted
            )
        )
    }

    public func metadata(
        for reference:
            FileReference
    )
        throws
        -> FileMetadata
    {
        try await fileStore.metadata(
            for:
                reference
        )
    }

    public func importDocument(
        _ request:
            DocumentImportRequest
    )
        throws
        -> FileMetadata
    {
        let metadata =
            try await importer
                .importDocument(
                    request
                )

        imports += 1

        await events.publish(
            DocumentChangeEvent(
                id:
                    request.destination.id,
                kind:
                    .imported
            )
        )

        return metadata
    }

    public func exportDocument(
        _ request:
            DocumentExportRequest
    )
        throws
    {
        try await exporter
            .exportDocument(
                request
            )

        exports += 1

        await events.publish(
            DocumentChangeEvent(
                id:
                    request.source.id,
                kind:
                    .exported
            )
        )
    }

    public func metrics()
        -> FileRuntimeMetrics
    {
        FileRuntimeMetrics(
            reads:
                reads,
            writes:
                writes,
            imports:
                imports,
            exports:
                exports,
            deletes:
                deletes,
            bytesRead:
                bytesRead,
            bytesWritten:
                bytesWritten,
            failures:
                failures
        )
    }
}
```

