                )
            )

        XCTAssertEqual(
            checksum.algorithm,
            "SHA-256"
        )

        XCTAssertFalse(
            checksum.hexadecimal.isEmpty
        )
    }

    func testDocumentReference() {

        let reference =
            FileReference(
                id:
                    FileIdentifier(
                        "document-1"
                    ),
                domain:
                    .applicationDocuments,
                relativePath:
                    "document.pdf"
            )

        XCTAssertEqual(
            reference.id.rawValue,
            "document-1"
        )
    }
