# 10. Usage Accounting

```swift
public struct ResourceAccount:
    Codable,
    Sendable
{
    public private(set) var usage:
        ResourceUsage

    public init(
        usage:
            ResourceUsage =
            ResourceUsage()
    ) {
        self.usage =
            usage
    }

    public mutating func add(
        _ value:
            ResourceUsage
    ) {
        usage =
            ResourceUsage(
                cpuMilliseconds:
                    usage.cpuMilliseconds +
                    value.cpuMilliseconds,

                gpuMilliseconds:
                    usage.gpuMilliseconds +
                    value.gpuMilliseconds,

                neuralMilliseconds:
                    usage.neuralMilliseconds +
                    value.neuralMilliseconds,

                networkBytes:
                    usage.networkBytes +
                    value.networkBytes,

                diskReadBytes:
                    usage.diskReadBytes +
                    value.diskReadBytes,

                diskWriteBytes:
                    usage.diskWriteBytes +
                    value.diskWriteBytes,

                memoryBytes:
                    max(
                        usage.memoryBytes,
                        value.memoryBytes
                    ),

                wallClockSeconds:
                    usage.wallClockSeconds +
                    value.wallClockSeconds
            )
    }
}
```

---

# 11. Budget Validator

```swift
public struct ResourceBudgetValidator:
    Sendable
{
    public init() {}

    public func exceeds(
        usage:
            ResourceUsage,
        budget:
            ResourceBudget
    )
        -> Bool
    {
        if let limit =
            budget.cpuMilliseconds,
           usage.cpuMilliseconds > limit
        {
            return true
        }

        if let limit =
            budget.gpuMilliseconds,
           usage.gpuMilliseconds > limit
        {
            return true
        }

        if let limit =
            budget.neuralMilliseconds,
           usage.neuralMilliseconds > limit
        {
            return true
        }

        if let limit =
            budget.networkBytes,
           usage.networkBytes > limit
        {
            return true
        }

        if let limit =
            budget.diskReadBytes,
           usage.diskReadBytes > limit
        {
            return true
        }

        if let limit =
            budget.diskWriteBytes,
           usage.diskWriteBytes > limit
        {
            return true
        }

        if let limit =
            budget.memoryBytes,
           usage.memoryBytes > limit
        {
            return true
        }

        if let limit =
            budget.wallClockSeconds,
           usage.wallClockSeconds > limit
        {
            return true
        }

        return false
    }
}
```

