# 14. Energy Governor

```swift
public actor EnergyGovernor {

    private var mode:
        EnergyGovernorMode =
        .balanced

    private var profile:
        EnergyProfile =
        .balanced

    private var environment:
        EnergyEnvironment =
        EnergyEnvironment(
            thermalState:
                .nominal,
            lowPowerMode:
                false,
            applicationActive:
                true,
            networkAvailable:
                true
        )

    public init() {}

    public func setMode(
        _ mode:
            EnergyGovernorMode
    ) {
        self.mode =
            mode

        switch mode {

        case .unrestricted:
            profile =
                .unrestricted

        case .balanced:
            profile =
                .balanced

        case .efficiency:
            profile =
                .efficiency

        case .lowPower:
            profile =
                .lowPower

        case .thermalProtection:
            profile =
                EnergyProfile(
                    mode:
                        .thermalProtection,
                    cpuMultiplier:
                        0.40,
                    gpuMultiplier:
                        0.35,
                    neuralMultiplier:
                        0.45,
                    networkMultiplier:
                        0.50,
                    backgroundMultiplier:
                        0.10
                )

        case .background:
            profile =
                EnergyProfile(
                    mode:
                        .background,
                    cpuMultiplier:
                        0.55,
                    gpuMultiplier:
                        0.40,
                    neuralMultiplier:
                        0.50,
                    networkMultiplier:
                        0.55,
                    backgroundMultiplier:
                        0.20
                )
        }
    }

    public func updateEnvironment(
        _ environment:
            EnergyEnvironment
    ) {
        self.environment =
            environment

        if environment.lowPowerMode {
            mode =
                .lowPower

            profile =
                .lowPower
        }

        switch environment.thermalState {

        case .serious:
            mode =
                .thermalProtection

            profile =
                EnergyProfile(
                    mode:
                        .thermalProtection,
                    cpuMultiplier:
                        0.40,
                    gpuMultiplier:
                        0.35,
                    neuralMultiplier:
                        0.45,
                    networkMultiplier:
                        0.50,
                    backgroundMultiplier:
                        0.10
                )

        case .critical:
            mode =
                .thermalProtection

            profile =
                EnergyProfile(
                    mode:
                        .thermalProtection,
                    cpuMultiplier:
                        0.25,
                    gpuMultiplier:
                        0.20,
                    neuralMultiplier:
                        0.30,
                    networkMultiplier:
                        0.30,
                    backgroundMultiplier:
                        0.05
                )

        default:
            break
        }
    }

    public func evaluate(
        workload:
            EnergyWorkload
    )
        -> EnergyDecisionResult
    {
        if environment.thermalState ==
            .critical
        {
            if workload.priority <
                .realtime
            {
                return EnergyDecisionResult(
                    decision:
                        .defer,
                    reason:
                        "Critical thermal state.",
                    recommendedDelay:
                        30,
                    effectiveBudget:
                        workload.budget
                )
            }
        }

        if environment.lowPowerMode &&
            workload.priority ==
                .background
        {
            return EnergyDecisionResult(
                decision:
                    .defer,
                reason:
                    "Low Power Mode is active.",
                recommendedDelay:
                    60,
                effectiveBudget:
                    workload.budget
            )
        }

        if !environment.applicationActive &&
            workload.priority <=
                .deferred
        {
            return EnergyDecisionResult(
                decision:
                    .defer,
                reason:
                    "Application is not active.",
                recommendedDelay:
                    15,
                effectiveBudget:
                    workload.budget
            )
        }

        if workload.resources.contains(
            .network
        ),
        !environment.networkAvailable
        {
            return EnergyDecisionResult(
                decision:
                    .defer,
                reason:
                    "Network unavailable.",
                recommendedDelay:
                    10,
                effectiveBudget:
                    workload.budget
            )
        }

        if mode ==
            .thermalProtection
        {
            return EnergyDecisionResult(
                decision:
                    .runThrottled,
                reason:
                    "Thermal protection policy.",
                recommendedDelay:
                    nil,
                effectiveBudget:
                    workload.budget
            )
        }

        if mode ==
            .efficiency ||
            mode ==
            .lowPower
        {
            if workload.priority <=
                .deferred
            {
                return EnergyDecisionResult(
                    decision:
                        .defer,
                    reason:
                        "Efficiency policy.",
                    recommendedDelay:
                        20,
                    effectiveBudget:
                        workload.budget
                )
            }

            return EnergyDecisionResult(
                decision:
                    .runThrottled,
                reason:
                    "Efficiency policy.",
                recommendedDelay:
                    nil,
                effectiveBudget:
                    workload.budget
            )
        }

        return EnergyDecisionResult(
            decision:
                .run,
            reason:
                "Workload permitted.",
            recommendedDelay:
                nil,
            effectiveBudget:
                workload.budget
        )
    }

    public func currentMode()
        -> EnergyGovernorMode
    {
        mode
    }

    public func currentProfile()
        -> EnergyProfile
    {
        profile
    }
}
```

