# 17. Accounting Ledger

```swift
public actor EnergyAccountingLedger {

    private var accounts:
        [ResourceClass: ResourceAccount] = [:]

    private var workloadUsage:
        [UUID: ResourceAccount] = [:]

    public init() {}

    public func record(
        workload:
            EnergyWorkload,
        usage:
            ResourceUsage
    ) {

        var workloadAccount =
            workloadUsage[
                workload.id
            ] ??
            ResourceAccount()

        workloadAccount.add(
            usage
        )

        workloadUsage[
            workload.id
        ] =
            workloadAccount

        for resource in
            workload.resources
        {
            var account =
                accounts[
                    resource
                ] ??
                ResourceAccount()

            account.add(
                usage
            )

            accounts[
                resource
            ] =
                account
        }
    }

    public func usage(
        for workloadID:
            UUID
    )
        -> ResourceUsage?
    {
        workloadUsage[
            workloadID
        ]?.usage
    }

    public func usage(
        for resource:
            ResourceClass
    )
        -> ResourceUsage?
    {
        accounts[
            resource
        ]?.usage
    }

    public func reset() {
        accounts.removeAll(
            keepingCapacity:
                true
        )

        workloadUsage.removeAll(
            keepingCapacity:
                true
        )
    }
}
```

