# 22. Unified Runtime

```swift
public actor EnergyBudgetRuntime {

    public static let shared =
        EnergyBudgetRuntime()

    public let governor:
        EnergyGovernor

    public let ledger:
        EnergyAccountingLedger

    public let leases:
        ResourceLeaseManager

    public let runner:
        EnergyWorkloadRunner

    private var started:
        Bool = false

    private init() {

        let governor =
            EnergyGovernor()

        let ledger =
            EnergyAccountingLedger()

        let leases =
            ResourceLeaseManager(
                governor:
                    governor
            )

        let runner =
            EnergyWorkloadRunner(
                governor:
                    governor,
                leases:
                    leases,
                ledger:
                    ledger
            )

        self.governor =
            governor

        self.ledger =
            ledger

        self.leases =
            leases

        self.runner =
            runner
    }

    public func start() {

        started =
            true

        EnergyRuntimeLog.info(
            "Energy budget runtime started."
        )
    }

    public func stop() {

        started =
            false

        EnergyRuntimeLog.info(
            "Energy budget runtime stopped."
        )
    }

    public func setMode(
        _ mode:
            EnergyGovernorMode
    )
        async
    {
        await governor.setMode(
            mode
        )
    }

    public func updateEnvironment(
        _ environment:
            EnergyEnvironment
    )
        async
    {
        await governor.updateEnvironment(
            environment
        )
    }

    public func evaluate(
        _ workload:
            EnergyWorkload
    )
        async
        -> EnergyDecisionResult
    {
        await governor.evaluate(
            workload:
                workload
        )
    }

    public func run(
        _ workload:
            EnergyWorkload,
        operation:
            @escaping @Sendable () async throws -> ResourceUsage
    )
        async throws
        -> WorkloadResult
    {
        guard started else {
            throw CancellationError()
        }

        return try await runner.run(
            workload:
                workload,
            operation:
                operation
        )
    }

    public func snapshot()
        async
        -> EnergyRuntimeSnapshot
    {
        let mode =
            await governor.currentMode()

        let active =
            await leases.activeCount()

        let cpu =
            await ledger.usage(
                for:
                    .cpu
            )

        let gpu =
            await ledger.usage(
                for:
                    .gpu
            )

        let network =
            await ledger.usage(
                for:
                    .network
            )

        let disk =
            await ledger.usage(
                for:
                    .diskRead
            )

        return EnergyRuntimeSnapshot(
            mode:
                mode,
            activeWorkloads:
                active,
            cpuUsage:
                cpu,
            gpuUsage:
                gpu,
            networkUsage:
                network,
            diskUsage:
                disk
        )
    }
}
```

