public struct ThermalForecast:
    Codable,
    Sendable
{
    public let horizon:
        TimeInterval

    public let currentPressure:
        ThermalPressure

    public let predictedPressure:
        ThermalPressure

    public let confidence:
        Double

    public let sustainedWorkload:
        Bool

    public let recommendedAction:
        ThermalAction

    public let generatedAt:
        Date

    public init(
        horizon:
            TimeInterval,
        currentPressure:
            ThermalPressure,
        predictedPressure:
            ThermalPressure,
        confidence:
            Double,
        sustainedWorkload:
            Bool,
        recommendedAction:
            ThermalAction,
        generatedAt:
            Date = Date()
    ) {
        self.horizon =
            horizon

        self.currentPressure =
            currentPressure

        self.predictedPressure =
            predictedPressure

        self.confidence =
            max(
                0,
                min(
                    1,
                    confidence
                )
            )

        self.sustainedWorkload =
            sustainedWorkload

        self.recommendedAction =
            recommendedAction

        self.generatedAt =
            generatedAt
    }
}
