        Double

    public let minimumConfidence:
        Double

    public init(
        observationWindow:
            TimeInterval = 60,
        sustainedWorkloadThreshold:
            TimeInterval = 15,
        elevatedPressureThreshold:
            Double = 0.40,
        highPressureThreshold:
            Double = 0.65,
        severePressureThreshold:
            Double = 0.85,
        minimumConfidence:
            Double = 0.55
    ) {
        self.observationWindow =
            max(
                5,
                observationWindow
            )

        self.sustainedWorkloadThreshold =
            max(
                1,
                sustainedWorkloadThreshold
            )

        self.elevatedPressureThreshold =
            max(
                0,
                min(
                    1,
                    elevatedPressureThreshold
                )
            )

        self.highPressureThreshold =
            max(
                elevatedPressureThreshold,
                min(
                    1,
                    highPressureThreshold
                )
            )

        self.severePressureThreshold =
            max(
                highPressureThreshold,
                min(
                    1,
                    severePressureThreshold
                )
            )

        self.minimumConfidence =
            max(
                0,
                min(
                    1,
                    minimumConfidence
                )
            )
    }
}
