    public func currentState()
        -> ThermalState
    {
        switch ProcessInfo.processInfo.thermalState {

        case .nominal:
            return .nominal

        case .fair:
            return .fair

        case .serious:
            return .serious

        case .critical:
            return .critical

        @unknown default:
