# 18. Adaptive Policy

```swift
public struct ThermalAdaptivePolicy:
    Sendable
{
    public init() {}

    public func concurrencyLimit(
        forecast:
            ThermalForecast
    )
        -> Int
    {
        switch forecast
            .recommendedAction
        {
        case .maintain:
            return 4

        case .reduceFrequency:
            return 3

        case .reduceQuality:
            return 3

        case .reduceConcurrency:
            return 1

        case .deferBackgroundWork:
            return 1

        case .pauseOptionalWork:
            return 1

        case .emergencyStopOptionalWork:
            return 0
        }
    }

    public func shouldDeferBackground(
        forecast:
            ThermalForecast
    )
        -> Bool
    {
        switch forecast
            .recommendedAction
        {
        case .deferBackgroundWork,
             .pauseOptionalWork,
             .emergencyStopOptionalWork:
            return true

        default:
            return false
        }
    }

    public func qualityScale(
        forecast:
            ThermalForecast
    )
        -> Double
    {
        switch forecast
            .recommendedAction
        {
        case .maintain:
            return 1.0

        case .reduceFrequency:
            return 0.90

        case .reduceQuality:
            return 0.70

        case .reduceConcurrency:
            return 0.75

        case .deferBackgroundWork:
            return 0.60

        case .pauseOptionalWork:
            return 0.40

        case .emergencyStopOptionalWork:
            return 0
        }
    }
}
```

