# 20. Process Environment Collector

```swift
public struct ThermalEnvironmentCollector:
    Sendable
{
    private let thermalProvider:
        ProcessThermalStateProvider

    private let lowPowerProvider:
        LowPowerModeProvider

    public init() {
        thermalProvider =
            ProcessThermalStateProvider()

        lowPowerProvider =
            LowPowerModeProvider()
    }

    public func collect(
        activeWorkloads:
            Int,
        usage:
            ResourceUsage
    )
        -> ThermalObservation
    {
        ThermalObservation(
            thermalState:
                thermalProvider.currentState(),

            lowPowerMode:
                lowPowerProvider.isEnabled,

            activeWorkloads:
                activeWorkloads,

            cpuMilliseconds:
                usage.cpuMilliseconds,

            gpuMilliseconds:
                usage.gpuMilliseconds,

            neuralMilliseconds:
                usage.neuralMilliseconds,

            memoryBytes:
                usage.memoryBytes,

            networkBytes:
                usage.networkBytes,

            diskBytes:
                usage.diskReadBytes +
                usage.diskWriteBytes
        )
    }
}
