# 22. Runtime

```swift
public actor ThermalPredictionRuntime {

    public static let shared =
        ThermalPredictionRuntime()

    private let forecastEngine:
        ThermalForecastEngine

    public let controller:
        ThermalWorkloadController

    private let environmentCollector:
        ThermalEnvironmentCollector

    private var metrics:
        ThermalForecastMetrics =
        ThermalForecastMetrics()

    private var running:
        Bool = false

    private init() {

        let engine =
            ThermalForecastEngine()

        forecastEngine =
            engine

        controller =
            ThermalWorkloadController(
                forecastEngine:
                    engine
            )

        environmentCollector =
            ThermalEnvironmentCollector()
    }

    public func start() {

        guard !running else {
            return
        }

        running =
            true

        ThermalRuntimeLog.info(
            "Thermal prediction runtime started."
        )
    }

    public func stop() {

        running =
            false

        ThermalRuntimeLog.info(
            "Thermal prediction runtime stopped."
        )
    }

    public func sample(
        activeWorkloads:
            Int,
        usage:
            ResourceUsage
    )
        async
    {
        guard running else {
            return
        }

        let observation =
            environmentCollector.collect(
                activeWorkloads:
                    activeWorkloads,
                usage:
                    usage
            )

        await controller.observe(
            observation
        )

        metrics =
            ThermalForecastMetrics(
                observations:
                    metrics.observations + 1,
                forecasts:
                    metrics.forecasts,
                elevatedForecasts:
                    metrics.elevatedForecasts,
                highForecasts:
                    metrics.highForecasts,
                severeForecasts:
                    metrics.severeForecasts,
                deferredWorkloads:
                    metrics.deferredWorkloads,
                throttledWorkloads:
                    metrics.throttledWorkloads
            )
    }

    public func forecast()
        async
        -> ThermalForecast
    {
        let result =
            await forecastEngine.forecast(
                horizon:
                    .short
            )

        metrics =
            ThermalForecastMetrics(
                observations:
                    metrics.observations,
                forecasts:
                    metrics.forecasts + 1,
                elevatedForecasts:
                    metrics.elevatedForecasts +
                    (result.predictedPressure ==
                        .elevated
                        ? 1
                        : 0),
                highForecasts:
                    metrics.highForecasts +
                    (result.predictedPressure ==
                        .high
                        ? 1
                        : 0),
                severeForecasts:
                    metrics.severeForecasts +
                    (result.predictedPressure ==
                        .severe
                        ? 1
                        : 0),
                deferredWorkloads:
                    metrics.deferredWorkloads +
                    (
                        result.recommendedAction ==
                            .deferBackgroundWork
                        ? 1
                        : 0
                    ),
                throttledWorkloads:
                    metrics.throttledWorkloads +
                    (
                        result.recommendedAction ==
                            .reduceConcurrency ||
                        result.recommendedAction ==
                            .reduceQuality
                        ? 1
                        : 0
                    )
            )

        return result
    }

    public func snapshot()
        async
        -> ThermalPredictionSnapshot
    {
        let forecast =
            await forecast()

        return ThermalPredictionSnapshot(
            running:
                running,
            forecast:
                forecast,
            metrics:
                metrics
        )
    }
}
```

