            )

        XCTAssertTrue(
            policy.shouldDeferBackground(
                forecast:
                    forecast
            )
        )
    }

    func testQualityScaleIsBounded() {

        let policy =
            ThermalAdaptivePolicy()

        let forecast =
            ThermalForecast(
                horizon:
                    15,
                currentPressure:
                    .low,
                predictedPressure:
                    .low,
                confidence:
                    1,
                sustainedWorkload:
                    false,
                recommendedAction:
                    .maintain
            )

        let scale =
            policy.qualityScale(
                forecast:
                    forecast
            )

        XCTAssertGreaterThanOrEqual(
            scale,
            0
        )

        XCTAssertLessThanOrEqual(
            scale,
            1
        )
    }
