# 12. Runtime Watchdog

The watchdog identifies operations that have stopped making progress.

```swift
public actor RuntimeWatchdog {

    public struct Registration:
        Sendable
    {
        public let id:
            UUID

        public let name:
            String

        public let timeout:
            TimeInterval

        public let registeredAt:
            Date

        public var lastHeartbeat:
            Date

        public init(
            id:
                UUID = UUID(),
            name:
                String,
            timeout:
                TimeInterval,
            registeredAt:
                Date = Date(),
            lastHeartbeat:
                Date = Date()
        ) {
            self.id =
                id

            self.name =
                name

            self.timeout =
                timeout

            self.registeredAt =
                registeredAt

            self.lastHeartbeat =
                lastHeartbeat
        }
    }

    private var registrations:
        [UUID: Registration] = [:]

    public init() {}

    public func register(
        name:
            String,
        timeout:
            TimeInterval
    )
        -> UUID
    {
        let registration =
            Registration(
                name:
                    name,
                timeout:
                    max(
                        0.5,
                        timeout
                    )
            )

        registrations[
            registration.id
        ] =
            registration

        return registration.id
    }

    public func heartbeat(
        id:
            UUID
    ) {

        guard
            var registration =
                registrations[id]
        else {
            return
        }

        registration.lastHeartbeat =
            Date()

        registrations[id] =
            registration
    }

    public func unregister(
        id:
            UUID
    ) {
        registrations.removeValue(
            forKey:
                id
        )
    }

    public func stalled()
        -> [Registration]
    {
        let now =
            Date()

        return registrations.values
            .filter {
                now.timeIntervalSince(
                    $0.lastHeartbeat
                ) >
                $0.timeout
            }
    }
}
```

