# 16. Diagnostic Engine

```swift
public actor DiagnosticEngine {

    private let registry:
        DiagnosticCheckRegistry

    private let verificationRegistry:
        VerificationRuleRegistry

    private let history:
        DiagnosticHistory

    private let watchdog:
        RuntimeWatchdog

    private var metrics:
        DiagnosticMetrics =
        DiagnosticMetrics()

    private var activeFindings:
        [String: DiagnosticFinding] = [:]

    public init(
        registry:
            DiagnosticCheckRegistry =
            DiagnosticCheckRegistry(),
        verificationRegistry:
            VerificationRuleRegistry =
            VerificationRuleRegistry(),
        history:
            DiagnosticHistory =
            DiagnosticHistory(),
        watchdog:
            RuntimeWatchdog =
            RuntimeWatchdog()
    ) {
        self.registry =
            registry

        self.verificationRegistry =
            verificationRegistry

        self.history =
            history

        self.watchdog =
            watchdog
    }

    public func runChecks()
        async
        -> [DiagnosticFinding]
    {
        let checks =
            await registry.all()

        var results:
            [DiagnosticFinding] = []

        for check in checks {

            let start =
                ContinuousClock.now

            let finding =
                await check.run()

            let duration =
                ContinuousClock.now
                    .duration(
                        since:
                            start
                    )

            let milliseconds =
                durationSeconds(
                    duration
                ) *
                1000

            await history.append(
                finding
            )

            results.append(
                finding
            )

            activeFindings[
                check.identifier
            ] =
                finding

            updateMetrics(
                finding:
                    finding,
                durationMilliseconds:
                    milliseconds
            )
        }

        return results
    }

    public func verify()
        async
        -> [DiagnosticFinding]
    {
        let rules =
            await verificationRegistry.all()

        var findings:
            [DiagnosticFinding] = []

        for rule in rules {

            guard
                let finding =
                    await rule.evaluate()
            else {
                continue
            }

            findings.append(
                finding
            )

            await history.append(
                finding
            )

            updateMetrics(
                finding:
                    finding,
                durationMilliseconds:
                    0
            )
        }

        return findings
    }

    public func checkWatchdog()
        async
        -> [DiagnosticFinding]
    {
        let stalled =
            await watchdog.stalled()

        guard !stalled.isEmpty else {
            return []
        }

        var findings:
            [DiagnosticFinding] = []

        for registration in stalled {

            let finding =
                DiagnosticFinding(
                    domain:
                        .runtime,
                    severity:
                        .error,
                    status:
                        .degraded,
                    code:
                        "WATCHDOG_TIMEOUT",
                    message:
                        "Runtime component '\(registration.name)' stopped reporting heartbeats.",
                    remediation:
                        "Inspect actor progress, task cancellation and blocking operations."
                )

            findings.append(
                finding
            )

            await history.append(
                finding
            )

            updateMetrics(
                finding:
                    finding,
                durationMilliseconds:
                    0
            )
        }

        return findings
    }

    public func snapshot()
        async
        -> DiagnosticSnapshot
    {
        let all =
            Array(
                activeFindings.values
            )

        let status =
            overallStatus(
                findings:
                    all
            )

        return DiagnosticSnapshot(
            overallStatus:
                status,
            activeFindings:
                all,
            completedChecks:
                metrics.completedChecks,
            failedChecks:
                metrics.failedChecks,
            warningCount:
                metrics.warnings,
            errorCount:
                metrics.errors,
            criticalCount:
                metrics.critical
        )
    }

    public func clearFinding(
        identifier:
            String
    ) {
        activeFindings
            .removeValue(
                forKey:
                    identifier
            )
    }

    public func clearAll() {
        activeFindings.removeAll()
    }

    public func getWatchdog()
        -> RuntimeWatchdog
    {
        watchdog
    }

    private func updateMetrics(
        finding:
            DiagnosticFinding,
        durationMilliseconds:
            Double
    ) {

        let count =
            metrics.completedChecks + 1

        let oldAverage =
            metrics.averageCheckMilliseconds

        let newAverage =
            (
                oldAverage *
                Double(
                    metrics.completedChecks
                ) +
                durationMilliseconds
            ) /
            Double(
                count
            )

        metrics =
            DiagnosticMetrics(
                completedChecks:
                    count,
                failedChecks:
                    metrics.failedChecks +
                    (
                        finding.status ==
                            .failed
                        ? 1
                        : 0
                    ),
                warnings:
                    metrics.warnings +
                    (
                        finding.severity ==
                            .warning
                        ? 1
                        : 0
                    ),
                errors:
                    metrics.errors +
                    (
                        finding.severity ==
                            .error
                        ? 1
                        : 0
                    ),
                critical:
                    metrics.critical +
                    (
                        finding.severity ==
                            .critical
                        ? 1
                        : 0
                    ),
                watchdogTimeouts:
                    metrics.watchdogTimeouts,
                verificationFailures:
                    metrics.verificationFailures,
                averageCheckMilliseconds:
                    newAverage
            )
    }

    private func overallStatus(
        findings:
            [DiagnosticFinding]
    )
        -> DiagnosticStatus
    {
        if findings.contains(
            where: {
                $0.severity ==
                    .critical
            }
        ) {
            return .failed
        }

        if findings.contains(
            where: {
                $0.status ==
                    .failed
            }
        ) {
            return .failed
        }

        if findings.contains(
            where: {
                $0.severity ==
                    .error
            }
        ) {
            return .degraded
        }

        if findings.contains(
            where: {
                $0.severity ==
                    .warning
            }
        ) {
            return .degraded
        }

        return .healthy
    }

    private func durationSeconds(
        _ duration:
            Duration
    )
        -> Double
    {
        let components =
            duration.components

        return Double(
            components.seconds
        ) +
        Double(
            components.attoseconds
        ) /
        1_000_000_000_000_000_000
    }
}
```

