# 20. Thermal Verification

#28 itself can expose a verification rule.

```swift
public struct ThermalVerificationRules {

    public static func forecast(
        _ forecast:
            ThermalForecast
    )
        -> DiagnosticFinding?
    {
        switch forecast.predictedPressure {

        case .low,
             .moderate:
            return nil

        case .elevated:
            return DiagnosticFinding(
                domain:
                    .thermal,
                severity:
                    .warning,
                status:
                    .degraded,
                code:
                    "THERMAL_PRESSURE_ELEVATED",
                message:
                    "Thermal forecast indicates elevated application workload pressure.",
                remediation:
                    "Reduce optional background work and nonessential processing."
            )

        case .high:
            return DiagnosticFinding(
                domain:
                    .thermal,
                severity:
                    .error,
                status:
                    .degraded,
                code:
                    "THERMAL_PRESSURE_HIGH",
                message:
                    "Thermal forecast indicates sustained high workload pressure.",
                remediation:
                    "Reduce concurrency and computational quality where possible."
            )

        case .severe:
            return DiagnosticFinding(
                domain:
                    .thermal,
                severity:
                    .critical,
                status:
                    .failed,
                code:
                    "THERMAL_PRESSURE_SEVERE",
                message:
                    "Thermal forecast indicates severe application workload pressure.",
                remediation:
                    "Stop optional computation and allow the system to recover."
            )
        }
    }
}
```

