# 13. Histogram

Histograms are much more useful than simple averages for latency work.

```swift
public struct LatencyHistogram:
    Codable,
    Sendable
{
    public private(set) var count:
        UInt64 = 0

    public private(set) var minimum:
        Double = .infinity

    public private(set) var maximum:
        Double = 0

    public private(set) var total:
        Double = 0

    private var buckets:
        [Int: UInt64] = [:]

    public init() {}

    public mutating func record(
        milliseconds:
            Double
    ) {
        guard milliseconds >= 0 else {
            return
        }

        count += 1

        minimum =
            min(
                minimum,
                milliseconds
            )

        maximum =
            max(
                maximum,
                milliseconds
            )

        total +=
            milliseconds

        let bucket =
            Self.bucket(
                milliseconds:
                    milliseconds
            )

        buckets[bucket, default: 0] += 1
    }

    public var average:
        Double
    {
        guard count > 0 else {
            return 0
        }

        return total /
            Double(count)
    }

    public func percentile(
        _ percentile:
            Double
    )
        -> Double
    {
        guard count > 0 else {
            return 0
        }

        let target =
            UInt64(
                ceil(
                    Double(count) *
                    percentile
                )
            )

        var cumulative:
            UInt64 = 0

        for bucket in buckets.keys.sorted() {

            cumulative +=
                buckets[bucket] ?? 0

            if cumulative >= target {
                return Double(bucket)
            }
        }

        return maximum
    }

    private static func bucket(
        milliseconds:
            Double
    )
        -> Int
    {
        if milliseconds < 1 {
            return 1
        }

        if milliseconds < 2 {
            return 2
        }

        if milliseconds < 5 {
            return 5
        }

        if milliseconds < 10 {
            return 10
        }

        if milliseconds < 16 {
            return 16
        }

        if milliseconds < 33 {
            return 33
        }

        if milliseconds < 50 {
            return 50
        }

        if milliseconds < 100 {
            return 100
        }

        if milliseconds < 250 {
            return 250
        }

        if milliseconds < 500 {
            return 500
        }

        if milliseconds < 1000 {
            return 1000
        }

        return 5000
    }
}
```

