# 18. Instrumentation Runtime

```swift
public actor InstrumentationRuntime {

    public static let shared =
        InstrumentationRuntime()

    private var configuration:
        InstrumentationConfiguration =
        .development

    private let store:
        TelemetryStore

    private var counters:
        [MetricIdentifier: UInt64] = [:]

    private var histograms:
        [MetricIdentifier: LatencyHistogram] = [:]

    private var running:
        Bool = false

    private init() {

        store =
            TelemetryStore()
    }

    public func configure(
        _ configuration:
            InstrumentationConfiguration
    ) {
        self.configuration =
            configuration
    }

    public func start() {

        guard !running else {
            return
        }

        running =
            true
    }

    public func stop() {

        running =
            false
    }

    public func increment(
        _ identifier:
            MetricIdentifier,
        by:
            UInt64 = 1,
        domain:
            InstrumentationDomain =
            .runtime
    )
        async
    {
        guard shouldRecord(
            level:
                .normal
        )
        else {
            return
        }

        counters[identifier, default: 0] +=
            by

        await store.append(
            metric:
                TelemetryMetric(
                    identifier:
                        identifier,
                    domain:
                        domain,
                    value:
                        Double(
                            counters[identifier] ?? 0
                        ),
                    unit:
                        "count"
                )
        )
    }

    public func record(
        identifier:
            MetricIdentifier,
        value:
            Double,
        unit:
            String,
        domain:
            InstrumentationDomain,
        dimensions:
            [String: String] = [:]
    )
        async
    {
        guard shouldRecord(
            level:
                .normal
        )
        else {
            return
        }

        await store.append(
            metric:
                TelemetryMetric(
                    identifier:
                        identifier,
                    domain:
                        domain,
                    value:
                        value,
                    unit:
                        unit,
                    dimensions:
                        dimensions
                )
        )
    }

    public func recordLatency(
        identifier:
            MetricIdentifier,
        milliseconds:
            Double,
        domain:
            InstrumentationDomain
    )
        async
    {
        guard
            configuration.enableHistograms
        else {
            return
        }

        histograms[
            identifier,
            default:
                LatencyHistogram()
        ]
        .record(
            milliseconds:
                milliseconds
        )

        await record(
            identifier:
                identifier,
            value:
                milliseconds,
            unit:
                "ms",
            domain:
                domain
        )
    }

    public func event(
        _ event:
            RuntimeTelemetryEvent
    )
        async
    {
        guard shouldRecord(
            level:
                .important
        )
        else {
            return
        }

        await store.append(
            event:
                event
        )
    }

    public func span(
        _ span:
            TraceSpan
    )
        async
    {
        guard shouldRecord(
            level:
                .normal
        )
        else {
            return
        }

        await store.append(
            span:
                span
        )
    }

    public func snapshot()
        async
        -> InstrumentationSnapshot
    {
        InstrumentationSnapshot(
            running:
                running,
            mode:
                configuration.mode,
            level:
                configuration.level,
            counters:
                counters,
            histograms:
                histograms
        )
    }

    public func recentTelemetry()
        async
        -> TelemetrySnapshot
    {
        TelemetrySnapshot(
            metrics:
                await store.recentMetrics(),
            events:
                await store.recentEvents(),
            spans:
                await store.recentSpans()
        )
    }

    public func clear()
        async
    {
        counters.removeAll()
        histograms.removeAll()

        await store.clear()
    }

    private func shouldRecord(
        level:
            TelemetryLevel
    )
        -> Bool
    {
        running &&
        configuration.level >= level
    }
}
```

