# 34. Developer Telemetry Runtime

```swift
public actor DeveloperTelemetryRuntime {

    public static let shared =
        DeveloperTelemetryRuntime()

    private let timeline:
        PerformanceTimeline

    private let sessions:
        TelemetrySessionManager

    private var configuration:
        InstrumentationConfiguration =
        .development

    private var running:
        Bool = false

    private init() {

        timeline =
            PerformanceTimeline()

        sessions =
            TelemetrySessionManager()
    }

    public func configure(
        _ configuration:
            InstrumentationConfiguration
    )
        async
    {
        self.configuration =
            configuration

        await InstrumentationRuntime
            .shared
            .configure(
                configuration
            )
    }

    public func start() {

        guard !running else {
            return
        }

        running =
            true

        Task {
            _ =
                await sessions.start(
                    mode:
                        configuration.mode
                )

            await InstrumentationRuntime
                .shared
                .start()
        }
    }

    public func stop()
        async
    {
        running =
            false

        _ =
            await sessions.end()

        await InstrumentationRuntime
            .shared
            .stop()
    }

    public func mark(
        subsystem:
            String,
        event:
            String
    )
        async
    {
        guard running else {
            return
        }

        await timeline.append(
            TimelineEvent(
                subsystem:
                    subsystem,
                event:
                    event
            )
        )
    }

    public func measure<T: Sendable>(
        subsystem:
            String,
        operation:
            String,
        execute:
            @escaping @Sendable () async throws ->
            T
    )
        async throws
        -> T
    {
        let start =
            ContinuousClock.now

        await mark(
            subsystem:
                subsystem,
            event:
                "\(operation).begin"
        )

        do {

            let result =
                try await execute()

            let duration =
                ContinuousClock.now
                    .duration(
                        since:
                            start
                    )

            let milliseconds =
                durationSeconds(
                    duration
                ) * 1000

            await timeline.append(
                TimelineEvent(
                    subsystem:
                        subsystem,
                    event:
                        "\(operation).end",
                    durationMilliseconds:
                        milliseconds
                )
            )

            return result

        } catch {

            let duration =
                ContinuousClock.now
                    .duration(
                        since:
                            start
                    )

            let milliseconds =
                durationSeconds(
                    duration
                ) * 1000

            await timeline.append(
                TimelineEvent(
                    subsystem:
                        subsystem,
                    event:
                        "\(operation).failed",
                    durationMilliseconds:
                        milliseconds
                )
            )

            throw error
        }
    }

    public func exportPackage()
        async
        -> DiagnosticTelemetryPackage
    {
        DiagnosticTelemetryPackage(
            session:
                await sessions.active(),
            instrumentation:
                await InstrumentationRuntime
                    .shared
                    .snapshot(),
            telemetry:
                await InstrumentationRuntime
                    .shared
                    .recentTelemetry(),
            timeline:
                await timeline.snapshot()
        )
    }

    private func durationSeconds(
        _ duration:
            Duration
    )
        -> Double
    {
        let components =
            duration.components

        return Double(
            components.seconds
        ) +
        Double(
            components.attoseconds
        ) /
        1_000_000_000_000_000_000
    }
}
```

