```swift
public struct DeveloperTelemetryView:
    View
{
    @State private var model =
        TelemetryViewModel()

    public init() {}

    public var body:
        some View
    {
        List {

            Section(
                "Instrumentation"
            ) {

                LabeledContent(
                    "Running",
                    value:
                        model.snapshot?
                            .running == true
                        ? "YES"
                        : "NO"
                )

                LabeledContent(
                    "Mode",
                    value:
                        model.snapshot?
                            .mode
                            .rawValue ??
                        "unknown"
                )

                LabeledContent(
                    "Level",
                    value:
                        model.snapshot?
                            .level
                            .description ??
                        "unknown"
                )
            }

            Section(
                "Counters"
            ) {

                if let counters =
                    model.snapshot?
                        .counters
                {
                    ForEach(
                        counters.keys.sorted(
                            by:
                                {
                                    $0.rawValue <
                                    $1.rawValue
                                }
                        ),
                        id:
                            \.self
                    ) { key in

                        LabeledContent(
                            key.rawValue,
                            value:
                                "\(counters[key] ?? 0)"
                        )
                    }
                }
            }

            Section(
                "Latency"
            ) {

                if let histograms =
                    model.snapshot?
                        .histograms
                {
                    ForEach(
                        histograms.keys.sorted(
                            by:
                                {
                                    $0.rawValue <
                                    $1.rawValue
                                }
                        ),
                        id:
                            \.self
                    ) { key in

                        let histogram =
                            histograms[key]

                        VStack(
                            alignment:
                                .leading
                        ) {

                            Text(
                                key.rawValue
                            )

                            Text(
                                "avg \(String(format: "%.2f", histogram?.average ?? 0)) ms"
                            )

                            Text(
                                "p95 \(String(format: "%.2f", histogram?.percentile(0.95) ?? 0)) ms"
                            )

                            Text(
                                "p99 \(String(format: "%.2f", histogram?.percentile(0.99) ?? 0)) ms"
                            )
                        }
                    }
                }
            }
        }
        .navigationTitle(
            "Developer Telemetry"
        )
        .task {
            await model.refresh()
        }
    }
}
```

