# 49. Tests

```swift
import XCTest

final class InstrumentationTests:
    XCTestCase
{
    func testHistogramRecordsValues() {

        var histogram =
            LatencyHistogram()

        histogram.record(
            milliseconds:
                5
        )

        histogram.record(
            milliseconds:
                10
        )

        histogram.record(
            milliseconds:
                20
        )

        XCTAssertEqual(
            histogram.count,
            3
        )

        XCTAssertGreaterThan(
            histogram.maximum,
            0
        )

        XCTAssertGreaterThan(
            histogram.average,
            0
        )
    }

    func testMetricIdentifierEquality() {

        let a =
            MetricIdentifier(
                "camera.frame"
            )

        let b =
            MetricIdentifier(
                "camera.frame"
            )

        XCTAssertEqual(
            a,
            b
        )
    }

    func testBaseline() {

        let baseline =
            PerformanceBaseline(
                operation:
                    "camera.process",
                expectedMilliseconds:
                    20,
                p95Milliseconds:
                    30,
                p99Milliseconds:
                    50
            )

        XCTAssertEqual(
            baseline.operation,
            "camera.process"
        )
    }
}
```

